/**
 * @file ldpc_decoder_flexible.cu
 * @brief Optimized Flexible 5G NR LDPC Decoder with CUDA Acceleration
 *
 * Supports both Base Graph 1 and Base Graph 2 with all valid lifting sizes.
 * Uses optimized layered min-sum algorithm with:
 * - Half-precision (__half) for 2x memory bandwidth
 * - Codeword pairing (x2) for better GPU utilization
 * - Early termination with syndrome check
 * - In-place APP updates (layered decoding)
 */

#include "ldpc_decoder.h"
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cooperative_groups.h>
#include <cooperative_groups/reduce.h>
