// Get optimal normalization for given base graph and number of parity nodes
static float get_optimal_norm(int base_graph, int num_parity_nodes) {
    if (base_graph == 1) {
        if (num_parity_nodes > 46) num_parity_nodes = 46;
        if (num_parity_nodes < 4) num_parity_nodes = 4;
        return g_min_sum_norm_BG1[num_parity_nodes];
    } else {
        if (num_parity_nodes > 42) num_parity_nodes = 42;
        if (num_parity_nodes < 4) num_parity_nodes = 4;
        return g_min_sum_norm_BG2[num_parity_nodes];
    }
}

// ============================================================================
// CRC Tables and Functions for Early Termination
// ============================================================================
// 5G NR uses different CRCs for different scenarios:
// - CRC16:  Single-CB, TB <= 3824 bits (poly 0x1021)
// - CRC24A: Single-CB, TB > 3824 bits (poly 0x864CFB)
// - CRC24B: Multi-CB, per-codeblock CRC (poly 0x800063)

// CRC type enum (matches ldpc_crc_type_t in header)
enum LdpcCrcType {
    LDPC_CRC_NONE_INTERNAL = 0,   // No CRC check (confidence-only)
    LDPC_CRC_16_INTERNAL = 1,     // CRC16 (single-CB, small TB)
    LDPC_CRC_24A_INTERNAL = 2,    // CRC24A (single-CB, large TB)
    LDPC_CRC_24B_INTERNAL = 3     // CRC24B (multi-CB)
};

// CRC Polynomials per 3GPP TS 38.212
// Standard (MSB-first) polynomials - NOT USED for early termination
#define CRC16_POLY_LDPC  0x1021    // D^16 + D^12 + D^5 + 1
#define CRC24A_POLY_LDPC 0x864CFB  // D^24 + D^23 + D^18 + D^17 + D^14 + D^11 + D^10 + D^7 + D^6 + D^5 + D^4 + D^3 + D + 1
#define CRC24B_POLY_LDPC 0x800063  // D^24 + D^23 + D^6 + D^5 + D + 1

// Reflected (LSB-first) polynomials - USED for early termination
// These match the batch CRC check in crc.cu which works on LSB-first packed data
#define RCRC16_POLY_LDPC  0x8408    // Reflection of 0x1021
#define RCRC24A_POLY_LDPC 0xDF3261  // Reflection of 0x864CFB
#define RCRC24B_POLY_LDPC 0xC60001  // Reflection of 0x800063

// Reflected CRC lookup tables in constant memory (for early termination)
__device__ __constant__ uint16_t d_rcrc16_table_ldpc[256];   // 512 bytes
__device__ __constant__ uint32_t d_rcrc24a_table_ldpc[256];  // 1KB
__device__ __constant__ uint32_t d_rcrc24b_table_ldpc[256];  // 1KB

// Legacy non-reflected tables (kept for compatibility but not used for early term)
__device__ __constant__ uint16_t d_crc16_table_ldpc[256];
__device__ __constant__ uint32_t d_crc24a_table_ldpc[256];
__device__ __constant__ uint32_t d_crc24b_table_ldpc[256];

// Host-side tables for initialization
static uint16_t h_rcrc16_table_ldpc[256];
static uint32_t h_rcrc24a_table_ldpc[256];
static uint32_t h_rcrc24b_table_ldpc[256];
static uint16_t h_crc16_table_ldpc[256];
static uint32_t h_crc24a_table_ldpc[256];
static uint32_t h_crc24b_table_ldpc[256];
static bool crc_tables_ldpc_initialized = false;

// Forward CRC X^(8*2^i) powers for warp-parallel CRC ET (local to this TU)
__device__ __constant__ uint32_t d_crc24b_x_powers_ldpc[21];
__device__ __constant__ uint32_t d_crc24a_x_powers_ldpc[21];
__device__ __constant__ uint32_t d_crc16_x_powers_ldpc[21];
static uint32_t h_crc24b_x_powers_ldpc[21];
static uint32_t h_crc24a_x_powers_ldpc[21];
static uint32_t h_crc16_x_powers_ldpc[21];
static bool crc_x_powers_ldpc_initialized = false;

// GF(2^24) multiplication mod CRC24B polynomial (device, fully unrolled)
__device__ __forceinline__ uint32_t gf24_multiply_crc24b(uint32_t a, uint32_t b) {
    uint32_t result = 0;
    #pragma unroll
    for (int i = 0; i < 24; i++) {
        result ^= (b & 1) ? a : 0;
        b >>= 1;
        uint32_t msb = a & 0x800000;
        a = (a << 1) & 0xFFFFFF;
        a ^= msb ? CRC24B_POLY_LDPC : 0;
    }
    return result;
}

// GF(2^24) multiplication mod CRC24A polynomial (device, fully unrolled)
__device__ __forceinline__ uint32_t gf24_multiply_crc24a_ldpc(uint32_t a, uint32_t b) {
    uint32_t result = 0;
    #pragma unroll
    for (int i = 0; i < 24; i++) {
        result ^= (b & 1) ? a : 0;
        b >>= 1;
        uint32_t msb = a & 0x800000;
        a = (a << 1) & 0xFFFFFF;
        a ^= msb ? CRC24A_POLY_LDPC : 0;
    }
    return result;
}

// Shift CRC24B by n_bytes using precomputed x^(8*2^i) powers — O(log n)
__device__ __forceinline__ uint32_t crc24b_shift_bytes(uint32_t crc, int n_bytes) {
    if (n_bytes == 0 || crc == 0) return crc;
    uint32_t x_power = 0;
    bool first = true;
    for (int i = 0; i < 21 && n_bytes > 0; i++) {
        if (n_bytes & 1) {
            if (first) {
                x_power = d_crc24b_x_powers_ldpc[i];
                first = false;
            } else {
                x_power = gf24_multiply_crc24b(x_power, d_crc24b_x_powers_ldpc[i]);
            }
        }
        n_bytes >>= 1;
    }
    if (first) return crc;
    return gf24_multiply_crc24b(crc, x_power);
}

// Shift CRC24A by n_bytes using precomputed x^(8*2^i) powers — O(log n)
__device__ __forceinline__ uint32_t crc24a_shift_bytes_ldpc(uint32_t crc, int n_bytes) {
    if (n_bytes == 0 || crc == 0) return crc;
    uint32_t x_power = 0;
    bool first = true;
    for (int i = 0; i < 21 && n_bytes > 0; i++) {
        if (n_bytes & 1) {
            if (first) {
                x_power = d_crc24a_x_powers_ldpc[i];
                first = false;
            } else {
                x_power = gf24_multiply_crc24a_ldpc(x_power, d_crc24a_x_powers_ldpc[i]);
            }
        }
        n_bytes >>= 1;
    }
    if (first) return crc;
    return gf24_multiply_crc24a_ldpc(crc, x_power);
}

// GF(2^16) multiplication mod CRC16 polynomial (device, fully unrolled)
__device__ __forceinline__ uint32_t gf16_multiply_crc16(uint32_t a, uint32_t b) {
    uint32_t result = 0;
    #pragma unroll
    for (int i = 0; i < 16; i++) {
        result ^= (b & 1) ? a : 0;
        b >>= 1;
        uint32_t msb = a & 0x8000;
        a = (a << 1) & 0xFFFF;
        a ^= msb ? CRC16_POLY_LDPC : 0;
    }
    return result;
}

// Shift CRC16 by n_bytes using precomputed x^(8*2^i) powers — O(log n)
__device__ __forceinline__ uint32_t crc16_shift_bytes_ldpc(uint32_t crc, int n_bytes) {
    if (n_bytes == 0 || crc == 0) return crc;
    uint32_t x_power = 0;
    bool first = true;
    for (int i = 0; i < 21 && n_bytes > 0; i++) {
        if (n_bytes & 1) {
            if (first) {
                x_power = d_crc16_x_powers_ldpc[i];
                first = false;
            } else {
                x_power = gf16_multiply_crc16(x_power, d_crc16_x_powers_ldpc[i]);
            }
        }
        n_bytes >>= 1;
    }
    if (first) return crc;
    return gf16_multiply_crc16(crc, x_power);
}

// Generate reflected CRC16 lookup table (for LSB-first data)
static void generate_rcrc16_table_ldpc(uint16_t* table, uint16_t poly) {
    for (int i = 0; i < 256; i++) {
        uint16_t crc = (uint16_t)i;
        for (int j = 0; j < 8; j++) {
            if (crc & 1) {
                crc = (crc >> 1) ^ poly;
            } else {
                crc >>= 1;
            }
        }
        table[i] = crc;
    }
}

// Generate reflected CRC24 lookup table (for LSB-first data)
static void generate_rcrc24_table_ldpc(uint32_t* table, uint32_t poly) {
    for (int i = 0; i < 256; i++) {
        uint32_t crc = (uint32_t)i;
        for (int j = 0; j < 8; j++) {
            if (crc & 1) {
                crc = (crc >> 1) ^ poly;
            } else {
                crc >>= 1;
            }
        }
        table[i] = crc & 0xFFFFFF;
    }
}

// Generate non-reflected CRC16 lookup table (legacy)
static void generate_crc16_table_ldpc(uint16_t* table) {
    for (int i = 0; i < 256; i++) {
        uint16_t crc = (uint16_t)i << 8;
        for (int j = 0; j < 8; j++) {
            if (crc & 0x8000) {
                crc = (crc << 1) ^ CRC16_POLY_LDPC;
            } else {
                crc <<= 1;
            }
        }
        table[i] = crc;
    }
}

// Generate non-reflected CRC24 lookup table (legacy)
static void generate_crc24_table_ldpc(uint32_t* table, uint32_t poly) {
    for (int i = 0; i < 256; i++) {
        uint32_t crc = (uint32_t)i << 16;
        for (int j = 0; j < 8; j++) {
            if (crc & 0x800000) {
                crc = (crc << 1) ^ poly;
            } else {
                crc <<= 1;
            }
        }
        table[i] = crc & 0xFFFFFF;
    }
}

// Initialize all CRC tables (called once at decoder creation)
static void init_crc_tables_ldpc() {
    if (crc_tables_ldpc_initialized) return;

    // Generate reflected tables (used for early termination)
    generate_rcrc16_table_ldpc(h_rcrc16_table_ldpc, RCRC16_POLY_LDPC);
    generate_rcrc24_table_ldpc(h_rcrc24a_table_ldpc, RCRC24A_POLY_LDPC);
    generate_rcrc24_table_ldpc(h_rcrc24b_table_ldpc, RCRC24B_POLY_LDPC);

    // Generate legacy non-reflected tables
    generate_crc16_table_ldpc(h_crc16_table_ldpc);
    generate_crc24_table_ldpc(h_crc24a_table_ldpc, CRC24A_POLY_LDPC);
    generate_crc24_table_ldpc(h_crc24b_table_ldpc, CRC24B_POLY_LDPC);

    // Copy reflected tables to constant memory
    cudaError_t err1 = cudaMemcpyToSymbol(d_rcrc16_table_ldpc, h_rcrc16_table_ldpc, sizeof(h_rcrc16_table_ldpc));
    cudaError_t err2 = cudaMemcpyToSymbol(d_rcrc24a_table_ldpc, h_rcrc24a_table_ldpc, sizeof(h_rcrc24a_table_ldpc));
    cudaError_t err3 = cudaMemcpyToSymbol(d_rcrc24b_table_ldpc, h_rcrc24b_table_ldpc, sizeof(h_rcrc24b_table_ldpc));

    // Copy legacy tables
    cudaMemcpyToSymbol(d_crc16_table_ldpc, h_crc16_table_ldpc, sizeof(h_crc16_table_ldpc));
    cudaMemcpyToSymbol(d_crc24a_table_ldpc, h_crc24a_table_ldpc, sizeof(h_crc24a_table_ldpc));
    cudaMemcpyToSymbol(d_crc24b_table_ldpc, h_crc24b_table_ldpc, sizeof(h_crc24b_table_ldpc));

    // Generate forward CRC24B/CRC24A x^(8*2^i) power tables for warp-parallel CRC ET
    if (!crc_x_powers_ldpc_initialized) {
        // CRC24B: x^8 mod G_B(x)
        uint32_t x8b = 1;
        for (int i = 0; i < 8; i++) {
            if (x8b & 0x800000) x8b = ((x8b << 1) ^ CRC24B_POLY_LDPC) & 0xFFFFFF;
            else x8b = (x8b << 1) & 0xFFFFFF;
        }
        h_crc24b_x_powers_ldpc[0] = x8b;
        for (int i = 1; i < 21; i++) {
            // Repeated squaring: x^(8*2^i) = (x^(8*2^(i-1)))^2 mod G_B(x)
            uint32_t a = h_crc24b_x_powers_ldpc[i-1];
            uint32_t b = a, result = 0;
            while (b) {
                if (b & 1) result ^= a;
                b >>= 1;
                if (a & 0x800000) a = ((a << 1) ^ CRC24B_POLY_LDPC) & 0xFFFFFF;
                else a = (a << 1) & 0xFFFFFF;
            }
            h_crc24b_x_powers_ldpc[i] = result;
        }
        cudaMemcpyToSymbol(d_crc24b_x_powers_ldpc, h_crc24b_x_powers_ldpc, sizeof(h_crc24b_x_powers_ldpc));

        // CRC24A: x^8 mod G_A(x)
        uint32_t x8a = 1;
        for (int i = 0; i < 8; i++) {
            if (x8a & 0x800000) x8a = ((x8a << 1) ^ CRC24A_POLY_LDPC) & 0xFFFFFF;
            else x8a = (x8a << 1) & 0xFFFFFF;
        }
        h_crc24a_x_powers_ldpc[0] = x8a;
        for (int i = 1; i < 21; i++) {
            uint32_t a = h_crc24a_x_powers_ldpc[i-1];
            uint32_t b = a, result = 0;
            while (b) {
                if (b & 1) result ^= a;
                b >>= 1;
                if (a & 0x800000) a = ((a << 1) ^ CRC24A_POLY_LDPC) & 0xFFFFFF;
                else a = (a << 1) & 0xFFFFFF;
            }
            h_crc24a_x_powers_ldpc[i] = result;
        }
        cudaMemcpyToSymbol(d_crc24a_x_powers_ldpc, h_crc24a_x_powers_ldpc, sizeof(h_crc24a_x_powers_ldpc));

        // CRC16: x^8 mod G_16(x) — GF(2^16) with poly 0x1021
        uint32_t x8c = 1;
        for (int i = 0; i < 8; i++) {
            if (x8c & 0x8000) x8c = ((x8c << 1) ^ CRC16_POLY_LDPC) & 0xFFFF;
            else x8c = (x8c << 1) & 0xFFFF;
        }
        h_crc16_x_powers_ldpc[0] = x8c;
        for (int i = 1; i < 21; i++) {
            uint32_t a = h_crc16_x_powers_ldpc[i-1];
            uint32_t b = a, result = 0;
            while (b) {
                if (b & 1) result ^= a;
                b >>= 1;
                if (a & 0x8000) a = ((a << 1) ^ CRC16_POLY_LDPC) & 0xFFFF;
                else a = (a << 1) & 0xFFFF;
            }
            h_crc16_x_powers_ldpc[i] = result;
        }
        cudaMemcpyToSymbol(d_crc16_x_powers_ldpc, h_crc16_x_powers_ldpc, sizeof(h_crc16_x_powers_ldpc));

        crc_x_powers_ldpc_initialized = true;
    }

    crc_tables_ldpc_initialized = true;
}

// Legacy alias for backward compatibility
static void init_crc24b_table_ldpc() {
    init_crc_tables_ldpc();
}

// ============================================================================
// Φ(x) = -log(tanh(x/2)) lookup table for true box-plus (sum-product) decoding
// Key property: Φ is self-inverse, i.e. Φ(Φ(x)) = x, so one LUT handles both
// forward (V2C → Φ-domain) and inverse (Φ-domain → C2V magnitude) directions.
//
// Algorithm: C2V[i] = sign_excl[i] · Φ(Σ_{j≠i} Φ(|V2C[j]|))
// This is the exact belief-propagation check-node update, giving ~0.2-0.5 dB
// BLER improvement over the min-sum approximation.
// ============================================================================

#define PHI_LUT_SIZE 512
#define PHI_LUT_MAX_X 12.0f
#define PHI_LUT_STEP (PHI_LUT_MAX_X / PHI_LUT_SIZE)   // 0.0234375
#define PHI_LUT_INV_STEP (PHI_LUT_SIZE / PHI_LUT_MAX_X) // 42.6667
#define PHI_CLAMP_MAX 16.0f  // Φ(x→0) → ∞; clamp to finite value

__device__ __constant__ __half d_phi_lut[PHI_LUT_SIZE + 1];  // +1 for interpolation
static bool phi_lut_initialized = false;

static void init_phi_lut() {
    if (phi_lut_initialized) return;

    __half h_lut[PHI_LUT_SIZE + 1];
    for (int i = 0; i <= PHI_LUT_SIZE; i++) {
        float x = i * PHI_LUT_STEP;
        float phi;
        if (x < 1e-6f) {
            phi = PHI_CLAMP_MAX;
        } else {
            float ex = expf(x);
            phi = logf((ex + 1.0f) / (ex - 1.0f));
            if (phi > PHI_CLAMP_MAX) phi = PHI_CLAMP_MAX;
        }
        h_lut[i] = __float2half(phi);
    }
    cudaMemcpyToSymbol(d_phi_lut, h_lut, sizeof(h_lut));
    phi_lut_initialized = true;
}

// Device function: Φ(x) lookup with FP16 linear interpolation
// Used for both Φ(|V2C|) and Φ^{-1}(sum) since Φ is self-inverse
// 512-entry LUT with FP32 index math, FP16 interpolation via FMA
__device__ __forceinline__ __half phi_lookup(__half x) {
    float xf = __half2float(x);
    if (xf >= PHI_LUT_MAX_X) return __float2half(0.0f);
    if (xf <= 0.0f) return __float2half(PHI_CLAMP_MAX);

    float idx_f = xf * PHI_LUT_INV_STEP;
    int idx = __float2int_rd(idx_f);
    if (idx >= PHI_LUT_SIZE) return __float2half(0.0f);

    __half frac = __float2half(idx_f - (float)idx);
    __half v0 = d_phi_lut[idx];
    __half v1 = d_phi_lut[idx + 1];
    return __hfma(frac, __hsub(v1, v0), v0);  // v0 + frac*(v1-v0)
}

/**
 * @brief Compute CRC24B over information bits from APP values (parallel reduction)
 *
 * Each thread processes bits tid, tid+Z, tid+2*Z, etc. for the columns it handles.
 * Bytes are assembled in shared memory, then CRC is computed by a single thread.
 *
 * The information bits include Kb columns (0 to Kb-1), giving Kb*Z total bits.
 * CRC24B is attached at the end of info bits, so CRC(info_bits) should equal 0
 * if decoding was successful.
 *
 * @param app Pointer to APP values (Kb columns of Z elements each)
 * @param Kb Number of information columns (22 for BG1, 10 for BG2)
 * @param Z Lifting size
 * @param tid Thread ID (0 to Z-1)
 * @param s_bytes Shared memory for collecting bytes (needs ceil(Kb*Z/8) bytes)
 * @return CRC24B value (0 = pass, non-zero = fail)
 */
__device__ uint32_t compute_crc24b_from_app(
    const __half* __restrict__ app,
    int Kb, int Z,
    int tid,
    uint8_t* __restrict__ s_bytes
) {
    // Total info bits = Kb * Z, round up to byte boundary
    const int total_bits = Kb * Z;
    const int total_bytes = (total_bits + 7) / 8;

    // Each thread extracts hard decisions for its bit positions and packs into bytes
    // Bit layout: col0[0..Z-1], col1[0..Z-1], ..., col(Kb-1)[0..Z-1]
    // Thread tid handles bit positions: tid, tid+Z, tid+2*Z, ... (one per column)

    // First, zero the shared memory bytes this thread will contribute to
    // Each thread tid contributes to bytes containing bits tid, tid+Z, tid+2Z, etc.
    __syncthreads();

    // Extract hard decisions and store in shared memory
    // Use atomic OR since multiple threads write to same byte
    for (int col = 0; col < Kb; col++) {
        int bit_idx = col * Z + tid;  // Linear bit index
        int byte_idx = bit_idx >> 3;  // Divide by 8 (bitwise optimization)
        int bit_in_byte = 7 - (bit_idx & 7);  // Modulo 8, MSB-first ordering

        __half app_val = app[col * Z + tid];
        int bit = __hlt(app_val, __float2half(0.0f)) ? 1 : 0;

        if (bit && byte_idx < total_bytes) {
            atomicOr(reinterpret_cast<unsigned int*>(&s_bytes[byte_idx & ~3]),
                     (unsigned int)bit << (bit_in_byte + 8 * (byte_idx & 3)));
        }
    }
    __syncthreads();

    // Single thread computes CRC over the assembled bytes
    uint32_t crc = 0;
    if (tid == 0) {
        for (int i = 0; i < total_bytes; i++) {
            uint8_t byte = s_bytes[i];
            uint8_t index = ((crc >> 16) ^ byte) & 0xFF;
            crc = (crc << 8) ^ d_crc24b_table_ldpc[index];
            crc &= 0xFFFFFF;
        }
    }

    return crc;
}

/**
 * @brief Simplified CRC24B computation using warp-level collaboration
 *
 * This version is optimized for Z <= 384 (max LDPC lifting size).
 * Uses warp shuffle to collect bits efficiently without shared memory atomics.
 *
 * @param app Pointer to APP values
 * @param Kb Number of information columns
 * @param Z Lifting size (must be <= 384)
 * @param tid Thread ID
 * @param s_crc_bytes Shared memory for byte assembly (needs ceil(Kb*Z/8) bytes, zeroed)
 * @return CRC24B result (0 = pass)
 */
__device__ uint32_t compute_crc24b_warp(
    const __half* __restrict__ app,
    int Kb, int Z,
    int tid,
    uint8_t* __restrict__ s_crc_bytes
) {
    const int total_bits = Kb * Z;
    const int total_bytes = (total_bits + 7) / 8;

    // Zero shared memory
    for (int i = tid; i < ((total_bytes + 3) / 4) * 4; i += Z) {
        if (i < total_bytes) s_crc_bytes[i] = 0;
    }
    __syncthreads();

    // Each thread extracts hard decision for each column and writes to shared mem
    for (int col = 0; col < Kb; col++) {
        int bit_idx = col * Z + tid;
        int byte_idx = bit_idx >> 3;  // Divide by 8 (bitwise optimization)
        int bit_in_byte = 7 - (bit_idx & 7);  // Modulo 8, MSB-first

        __half app_val = app[col * Z + tid];
        uint8_t bit = __hlt(app_val, __float2half(0.0f)) ? 1 : 0;

        if (byte_idx < total_bytes) {
            atomicOr(reinterpret_cast<unsigned int*>(&s_crc_bytes[byte_idx & ~3]),
                     (unsigned int)(bit << (bit_in_byte + 8 * (byte_idx & 3))));
        }
    }
    __syncthreads();

    // Thread 0 computes final CRC
    uint32_t crc = 0;
    if (tid == 0) {
        for (int i = 0; i < total_bytes; i++) {
            uint8_t byte = s_crc_bytes[i];
            uint8_t index = ((crc >> 16) ^ byte) & 0xFF;
            crc = (crc << 8) ^ d_crc24b_table_ldpc[index];
            crc &= 0xFFFFFF;
        }
    }

    return crc;
}

// ============================================================================
// Helper functions
// ============================================================================

__device__ __forceinline__ int fast_mod(int val, int Z) {
    return (val >= Z) ? (val - Z) : ((val < 0) ? (val + Z) : val);
}

/**
 * @brief Convert linear bit index to MSB-first byte-ordered bit position
 *
 * 5G NR uses MSB-first bit ordering within each byte. This function converts
 * a linear bit index (0, 1, 2, ...) to the corresponding bit position in a
 * 32-bit word where bits are ordered MSB-first within each byte.
 *
 * Example mapping (bit_idx % 32 -> bit_pos):
 *   0 -> 7, 1 -> 6, ..., 7 -> 0  (byte 0, reversed)
 *   8 -> 15, 9 -> 14, ..., 15 -> 8  (byte 1, reversed)
 *   etc.
 *
 * @param bit_idx Linear bit index
 * @return Bit position with MSB-first byte ordering
 */
__device__ __forceinline__ int msb_first_bit_pos(int bit_idx) {
    // XOR with 7 reverses bits within each byte (swaps bits 0<->7, 1<->6, etc.)
    return (bit_idx & 31) ^ 7;
}

__device__ __forceinline__ __half clamp_half(__half x, __half clamp) {
    return __hmax(__hmin(x, clamp), __hneg(clamp));
}

__device__ __forceinline__ int sign_bit(__half x) {
    return (__half_as_short(x) >> 15) & 1;
}

__device__ __forceinline__ __half habs(__half x) {
    unsigned short bits = __half_as_ushort(x);
    return __ushort_as_half(bits & 0x7FFF);
}

__device__ __forceinline__ __half conditional_neg(__half x, int negate) {
    unsigned short bits = __half_as_ushort(x);
    return __ushort_as_half(bits ^ (negate ? 0x8000 : 0));
}

// ============================================================================
// half2 Helper Functions for Vectorized Processing
// ============================================================================

__device__ __forceinline__ half2 clamp_half2(half2 x, half2 clamp) {
    return __hmax2(__hmin2(x, clamp), __hneg2(clamp));
}

__device__ __forceinline__ int sign_bit_low(half2 x) {
    // Get sign bit of .x component (low half)
    return (__half_as_short(__low2half(x)) >> 15) & 1;
}

__device__ __forceinline__ int sign_bit_high(half2 x) {
    // Get sign bit of .y component (high half)
    return (__half_as_short(__high2half(x)) >> 15) & 1;
}

__device__ __forceinline__ half2 habs2(half2 x) {
    // Absolute value of both components
    return __habs2(x);
}

__device__ __forceinline__ half2 conditional_neg2(half2 x, int negate_low, int negate_high) {
    // Conditionally negate each component independently
    unsigned int bits = *reinterpret_cast<unsigned int*>(&x);
    unsigned int mask = (negate_low ? 0x8000 : 0) | (negate_high ? 0x80000000 : 0);
    bits ^= mask;
    return *reinterpret_cast<half2*>(&bits);
}

__device__ __forceinline__ half2 make_half2_same(__half val) {
    return __half2half2(val);
}

__device__ __forceinline__ half2 hmax2_scalar(half2 a, __half b) {
    return __hmax2(a, __half2half2(b));
}

// ============================================================================
// Compressed C2V storage for FP16 boxplus decoder
// After NMS (offset==0): new_c2v[e] = scale * box_plus_excl[e]
//   = scale * min(|v2c[j]|, j!=e) * sign_product_excluding_e
// This is fully characterized by {min1, min2, min1_idx, sign_parity, sign_bits}
// Memory: M*Z*8 bytes per CB vs M*max_deg*Z*2 (~4.75x reduction for BG1)
// ============================================================================

struct __align__(8) c2v_compressed_half {
    __half   min1;          // NMS-scaled smallest |new_c2v| (2 bytes)
    __half   min2;          // NMS-scaled second smallest    (2 bytes)
    uint32_t meta;          // bits 0-18: signs, 19-23: min1_idx, 24: parity
};  // 8 bytes total, vs 38 bytes (degree 19 x 2) = 4.75x reduction

static_assert(sizeof(c2v_compressed_half) == 8, "compressed FP16 C2V summary must stay 8 bytes");

__device__ __forceinline__ uint32_t c2v_pack_meta(uint32_t sign_bits, int min1_idx, int sign_parity) {
    constexpr uint32_t sign_mask = (1u << 19) - 1u;
    return (sign_bits & sign_mask) |
           ((static_cast<uint32_t>(min1_idx) & 0x1fu) << 19) |
           ((static_cast<uint32_t>(sign_parity) & 0x1u) << 24);
}

__device__ __forceinline__ uint32_t c2v_meta_sign_bits(uint32_t meta) {
    constexpr uint32_t sign_mask = (1u << 19) - 1u;
    return meta & sign_mask;
}

__device__ __forceinline__ int c2v_meta_min1_idx(uint32_t meta) {
    return static_cast<int>((meta >> 19) & 0x1fu);
}

__device__ __forceinline__ int c2v_meta_sign_parity(uint32_t meta) {
    return static_cast<int>((meta >> 24) & 0x1u);
}

// ============================================================================
// Compressed C2V storage for INT8 min-sum decoder
// Instead of storing per-edge C2V values (19 bytes/row), stores only the
// min-sum summary: NMS-scaled min1, min2, which edge has min1, and per-edge
// sign bits. This is lossless for min-sum: PASS 2 reconstructs C2V identically.
// Memory reduction: 19*Z → 8*Z bytes per row (~2.4x for BG1).
// ============================================================================

struct __align__(8) c2v_compressed_i8 {
    int8_t   min1;          // NMS-scaled smallest |V2C|
    int8_t   min2;          // NMS-scaled second smallest |V2C|
    uint8_t  min1_idx;      // which edge has min1 (0-18)
    uint8_t  sign_parity;   // XOR of all edge signs (0 or 1)
    uint32_t sign_bits;     // per-edge sign bits (19 bits used for BG1)
};

// ============================================================================
// Aerial-Inspired Box-Plus for Min-Sum LDPC Decoding
// Uses PTX min.xorsign.abs.f16x2 on SM86+ for single-instruction box-plus
// This computes: result = min(|a|, |b|) with sign = sign(a) XOR sign(b)
// ============================================================================

__device__ __forceinline__ uint32_t box_plus_half2(uint32_t a, uint32_t b) {
#if __CUDA_ARCH__ >= 860
    // SM86+ (A100/H100/GH200): Use dedicated min.xorsign.abs instruction
    // This computes min(|a|, |b|) * sign(a XOR b) in a single instruction
    uint32_t out;
    asm volatile("min.xorsign.abs.f16x2 %0, %1, %2;" : "=r"(out) : "r"(a), "r"(b));
    return out;
#else
    // Fallback for older architectures: manual implementation
    __half2 ha = *reinterpret_cast<__half2*>(&a);
    __half2 hb = *reinterpret_cast<__half2*>(&b);

    // Compute min(|a|, |b|)
    __half2 out_mag = __hmin2(__habs2(ha), __habs2(hb));

    // Compute XOR of signs and apply to output
    uint32_t sign_xor = (a ^ b) & 0x80008000;  // Extract sign bits XOR
    uint32_t result = *reinterpret_cast<uint32_t*>(&out_mag);
    return result | sign_xor;
#endif
}

// Scalar version for single-element operations
__device__ __forceinline__ __half box_plus_half(__half a, __half b) {
#if __CUDA_ARCH__ >= 860
    // Pack into half2 and use vectorized instruction
    half2 packed_a = __halves2half2(a, a);
    half2 packed_b = __halves2half2(b, b);
    uint32_t result = box_plus_half2(*reinterpret_cast<uint32_t*>(&packed_a),
                                      *reinterpret_cast<uint32_t*>(&packed_b));
    return __low2half(*reinterpret_cast<half2*>(&result));
#else
    // Fallback: manual box-plus
    __half min_abs = __hmin(__habs(a), __habs(b));
    unsigned short sign_xor = (__half_as_ushort(a) ^ __half_as_ushort(b)) & 0x8000;
    return __ushort_as_half(__half_as_ushort(min_abs) | sign_xor);
#endif
}

// ============================================================================
// Binary tree exclusion product helpers for box-plus LDPC decoder
// Pack pairs of scalar __half V2C values into uint32_t (half2), compute two
// exclusion products per box_plus_half2 instruction. Based on NVIDIA Aerial's
// binary tree approach (ldpc2_box_plus.cuh).
// ============================================================================

// Swap high and low 16-bit halves of uint32_t (half2 lane swap)
__device__ __forceinline__ uint32_t bp_swap_hl(uint32_t x) {
    return (x >> 16) | (x << 16);
}

// Duplicate low 16-bit half to both lanes
__device__ __forceinline__ uint32_t bp_dup_low(uint32_t x) {
    uint32_t lo = x & 0xFFFF;
    return lo | (lo << 16);
}

// Pack pair of uint16_t into uint32_t: [v2c[2i+1] | v2c[2i]]
__device__ __forceinline__ uint32_t bp_pack(uint16_t lo, uint16_t hi) {
    return (uint32_t)lo | ((uint32_t)hi << 16);
}

// --- Per-degree binary tree functions for 1-CB kernel ---
// Input: v2c[0..D-1] as uint16_t (raw __half bits)
// Output: excl[0..D-1] as uint16_t (raw __half bits for exclusion product)
// Each excl[e] = box_plus of all v2c[j] for j != e

// Degree 3: 2 box_plus_half2 ops (was 5 scalar ops)
__device__ __forceinline__ void bp_tree_3(const uint16_t* v2c, uint16_t* excl) {
    uint32_t a0 = bp_pack(v2c[0], v2c[1]);    // [v1 | v0]
    uint32_t a1 = bp_dup_low(v2c[2]);          // [v2 | v2]
    uint32_t v0_1 = bp_swap_hl(a0);            // [v0 | v1]
    uint32_t s0 = box_plus_half2(a1, v0_1);    // [bp(2,0) | bp(2,1)]  = [excl(1) | excl(0)]
    uint32_t s1 = box_plus_half2(a0, v0_1);    // [bp(1,0) | bp(0,1)]  = [excl(2) | excl(2)] (low)
    excl[0] = (uint16_t)(s0);          // bp(2,1)  = excl(0)
    excl[1] = (uint16_t)(s0 >> 16);    // bp(2,0)  = excl(1)
    excl[2] = (uint16_t)(s1);          // bp(0,1)  = excl(2)
}

// Degree 4: 3 box_plus_half2 ops (was 8 scalar ops)
__device__ __forceinline__ void bp_tree_4(const uint16_t* v2c, uint16_t* excl) {
    uint32_t a0 = bp_pack(v2c[0], v2c[1]);     // [v1 | v0]
    uint32_t a1 = bp_pack(v2c[2], v2c[3]);     // [v3 | v2]
    uint32_t BP_13_02 = box_plus_half2(a1, a0);          // [bp(1,3) | bp(0,2)]
    uint32_t BP_02_13 = bp_swap_hl(BP_13_02);            // [bp(0,2) | bp(1,3)]
    uint32_t BP_023_123 = box_plus_half2(BP_02_13, a1);  // [bp(0,2,3) | bp(1,2,3)]
    uint32_t BP_012_013 = box_plus_half2(BP_02_13, a0);  // [bp(0,1,2) | bp(0,1,3)]
    excl[0] = (uint16_t)(BP_023_123);          // bp(1,2,3)
    excl[1] = (uint16_t)(BP_023_123 >> 16);    // bp(0,2,3)
    excl[2] = (uint16_t)(BP_012_013);          // bp(0,1,3)
    excl[3] = (uint16_t)(BP_012_013 >> 16);    // bp(0,1,2)
}

// Degree 5: 5 box_plus_half2 ops (was 11 scalar ops)
__device__ __forceinline__ void bp_tree_5(const uint16_t* v2c, uint16_t* excl) {
    uint32_t a0 = bp_pack(v2c[0], v2c[1]);     // [v1 | v0]
    uint32_t a1 = bp_pack(v2c[2], v2c[3]);     // [v3 | v2]
    uint32_t a2 = bp_dup_low(v2c[4]);           // [v4 | v4]
    uint32_t BP_13_02     = box_plus_half2(a1, a0);
    uint32_t BP_02_13     = bp_swap_hl(BP_13_02);
    uint32_t BP_024_134   = box_plus_half2(BP_02_13, a2);
    uint32_t BP_0234_1234 = box_plus_half2(BP_024_134, a1);
    uint32_t BP_0124_0134 = box_plus_half2(BP_024_134, a0);
    uint32_t BP_0123_0123 = box_plus_half2(BP_13_02, BP_02_13);
    excl[0] = (uint16_t)(BP_0234_1234);
    excl[1] = (uint16_t)(BP_0234_1234 >> 16);
    excl[2] = (uint16_t)(BP_0124_0134);
    excl[3] = (uint16_t)(BP_0124_0134 >> 16);
    excl[4] = (uint16_t)(BP_0123_0123);
}

// Degree 6: 6 box_plus_half2 ops (was 14 scalar ops)
__device__ __forceinline__ void bp_tree_6(const uint16_t* v2c, uint16_t* excl) {
    uint32_t a0 = bp_pack(v2c[0], v2c[1]);
    uint32_t a1 = bp_pack(v2c[2], v2c[3]);
    uint32_t a2 = bp_pack(v2c[4], v2c[5]);
    uint32_t BP_13_02       = box_plus_half2(a1, a0);
    uint32_t BP_135_024     = box_plus_half2(BP_13_02, a2);
    uint32_t BP_024_135     = bp_swap_hl(BP_135_024);
    uint32_t BP_01234_01235 = box_plus_half2(BP_024_135, BP_13_02);
    uint32_t BP_0245_1345   = box_plus_half2(BP_024_135, a2);
    uint32_t BP_02345_12345 = box_plus_half2(BP_0245_1345, a1);
    uint32_t BP_01245_01345 = box_plus_half2(BP_0245_1345, a0);
    excl[0] = (uint16_t)(BP_02345_12345);
    excl[1] = (uint16_t)(BP_02345_12345 >> 16);
    excl[2] = (uint16_t)(BP_01245_01345);
    excl[3] = (uint16_t)(BP_01245_01345 >> 16);
    excl[4] = (uint16_t)(BP_01234_01235);
    excl[5] = (uint16_t)(BP_01234_01235 >> 16);
}

// Degree 7: 8 box_plus_half2 ops (was 17 scalar ops)
__device__ __forceinline__ void bp_tree_7(const uint16_t* v2c, uint16_t* excl) {
    uint32_t a0 = bp_pack(v2c[0], v2c[1]);
    uint32_t a1 = bp_pack(v2c[2], v2c[3]);
    uint32_t a2 = bp_pack(v2c[4], v2c[5]);
    uint32_t a3 = bp_dup_low(v2c[6]);
    uint32_t BP_13_02           = box_plus_half2(a1, a0);
    uint32_t BP_135_024         = box_plus_half2(BP_13_02, a2);
    uint32_t BP_024_135         = bp_swap_hl(BP_135_024);
    uint32_t BP_0246_1356       = box_plus_half2(BP_024_135, a3);
    uint32_t BP_012345_012345   = box_plus_half2(BP_135_024, BP_024_135);
    uint32_t BP_012346_012356   = box_plus_half2(BP_0246_1356, BP_13_02);
    uint32_t BP_02456_13456     = box_plus_half2(BP_0246_1356, a2);
    uint32_t BP_012456_013456   = box_plus_half2(BP_02456_13456, a0);
    uint32_t BP_023456_123456   = box_plus_half2(BP_02456_13456, a1);
    excl[0] = (uint16_t)(BP_023456_123456);
    excl[1] = (uint16_t)(BP_023456_123456 >> 16);
    excl[2] = (uint16_t)(BP_012456_013456);
    excl[3] = (uint16_t)(BP_012456_013456 >> 16);
    excl[4] = (uint16_t)(BP_012346_012356);
    excl[5] = (uint16_t)(BP_012346_012356 >> 16);
    excl[6] = (uint16_t)(BP_012345_012345);
}

// Degree 8: 9 box_plus_half2 ops (was 20 scalar ops)
__device__ __forceinline__ void bp_tree_8(const uint16_t* v2c, uint16_t* excl) {
    uint32_t a0 = bp_pack(v2c[0], v2c[1]);
    uint32_t a1 = bp_pack(v2c[2], v2c[3]);
    uint32_t a2 = bp_pack(v2c[4], v2c[5]);
    uint32_t a3 = bp_pack(v2c[6], v2c[7]);
    uint32_t BP_13_02             = box_plus_half2(a1, a0);
    uint32_t BP_57_46             = box_plus_half2(a3, a2);
    uint32_t BP_1357_0246         = box_plus_half2(BP_13_02, BP_57_46);
    uint32_t BP_0246_1357         = bp_swap_hl(BP_1357_0246);
    uint32_t BP_012346_012357     = box_plus_half2(BP_0246_1357, BP_13_02);
    uint32_t BP_024567_134567     = box_plus_half2(BP_0246_1357, BP_57_46);
    uint32_t BP_0123467_0123567   = box_plus_half2(BP_012346_012357, a3);
    uint32_t BP_0234567_1234567   = box_plus_half2(BP_024567_134567, a1);
    uint32_t BP_0123456_0123457   = box_plus_half2(BP_012346_012357, a2);
    uint32_t BP_0124567_0134567   = box_plus_half2(BP_024567_134567, a0);
    excl[0] = (uint16_t)(BP_0234567_1234567);
    excl[1] = (uint16_t)(BP_0234567_1234567 >> 16);
    excl[2] = (uint16_t)(BP_0124567_0134567);
    excl[3] = (uint16_t)(BP_0124567_0134567 >> 16);
    excl[4] = (uint16_t)(BP_0123467_0123567);
    excl[5] = (uint16_t)(BP_0123467_0123567 >> 16);
    excl[6] = (uint16_t)(BP_0123456_0123457);
    excl[7] = (uint16_t)(BP_0123456_0123457 >> 16);
}

// Degree 9: 12 box_plus_half2 ops (was 23 scalar ops)
__device__ __forceinline__ void bp_tree_9(const uint16_t* v2c, uint16_t* excl) {
    uint32_t a0 = bp_pack(v2c[0], v2c[1]);
    uint32_t a1 = bp_pack(v2c[2], v2c[3]);
    uint32_t a2 = bp_pack(v2c[4], v2c[5]);
    uint32_t a3 = bp_pack(v2c[6], v2c[7]);
    uint32_t a4 = bp_dup_low(v2c[8]);
    uint32_t BP_13_02                 = box_plus_half2(a1, a0);
    uint32_t BP_57_46                 = box_plus_half2(a3, a2);
    uint32_t BP_1357_0246             = box_plus_half2(BP_13_02, BP_57_46);
    uint32_t BP_0246_1357             = bp_swap_hl(BP_1357_0246);
    uint32_t BP_01234567_01234567     = box_plus_half2(BP_0246_1357, BP_1357_0246);
    uint32_t BP_02468_13578           = box_plus_half2(BP_0246_1357, a4);
    uint32_t BP_0123468_0123578       = box_plus_half2(BP_02468_13578, BP_13_02);
    uint32_t BP_0245678_1345678       = box_plus_half2(BP_02468_13578, BP_57_46);
    uint32_t BP_01234678_01235678     = box_plus_half2(BP_0123468_0123578, a3);
    uint32_t BP_01234568_01234578     = box_plus_half2(BP_0123468_0123578, a2);
    uint32_t BP_02345678_12345678     = box_plus_half2(BP_0245678_1345678, a1);
    uint32_t BP_01245678_01345678     = box_plus_half2(BP_0245678_1345678, a0);
    excl[0] = (uint16_t)(BP_02345678_12345678);
    excl[1] = (uint16_t)(BP_02345678_12345678 >> 16);
    excl[2] = (uint16_t)(BP_01245678_01345678);
    excl[3] = (uint16_t)(BP_01245678_01345678 >> 16);
    excl[4] = (uint16_t)(BP_01234678_01235678);
    excl[5] = (uint16_t)(BP_01234678_01235678 >> 16);
    excl[6] = (uint16_t)(BP_01234568_01234578);
    excl[7] = (uint16_t)(BP_01234568_01234578 >> 16);
    excl[8] = (uint16_t)(BP_01234567_01234567);
}

// Degree 10: 12 box_plus_half2 ops (was 26 scalar ops)
__device__ __forceinline__ void bp_tree_10(const uint16_t* v2c, uint16_t* excl) {
    uint32_t a0 = bp_pack(v2c[0], v2c[1]);
    uint32_t a1 = bp_pack(v2c[2], v2c[3]);
    uint32_t a2 = bp_pack(v2c[4], v2c[5]);
    uint32_t a3 = bp_pack(v2c[6], v2c[7]);
    uint32_t a4 = bp_pack(v2c[8], v2c[9]);
    uint32_t BP_13_02                   = box_plus_half2(a1, a0);
    uint32_t BP_57_46                   = box_plus_half2(a2, a3);
    uint32_t BP_1357_0246               = box_plus_half2(BP_13_02, BP_57_46);
    uint32_t BP_13579_02468             = box_plus_half2(BP_1357_0246, a4);
    uint32_t BP_02468_13579             = bp_swap_hl(BP_13579_02468);
    uint32_t BP_024689_135789           = box_plus_half2(BP_02468_13579, a4);
    uint32_t BP_01234689_01235789       = box_plus_half2(BP_024689_135789, BP_13_02);
    uint32_t BP_02456789_13456789       = box_plus_half2(BP_024689_135789, BP_57_46);
    uint32_t BP_012345689_012345789     = box_plus_half2(BP_01234689_01235789, a2);
    uint32_t BP_012345678_012345679     = box_plus_half2(BP_02468_13579, BP_1357_0246);
    uint32_t BP_012456789_013456789     = box_plus_half2(BP_02456789_13456789, a0);
    uint32_t BP_023456789_123456789     = box_plus_half2(BP_02456789_13456789, a1);
    uint32_t BP_012346789_012356789     = box_plus_half2(BP_01234689_01235789, a3);
    excl[0] = (uint16_t)(BP_023456789_123456789);
    excl[1] = (uint16_t)(BP_023456789_123456789 >> 16);
    excl[2] = (uint16_t)(BP_012456789_013456789);
    excl[3] = (uint16_t)(BP_012456789_013456789 >> 16);
    excl[4] = (uint16_t)(BP_012346789_012356789);
    excl[5] = (uint16_t)(BP_012346789_012356789 >> 16);
    excl[6] = (uint16_t)(BP_012345689_012345789);
    excl[7] = (uint16_t)(BP_012345689_012345789 >> 16);
    excl[8] = (uint16_t)(BP_012345678_012345679);
    excl[9] = (uint16_t)(BP_012345678_012345679 >> 16);
}

// Degree 19: 26 box_plus_half2 ops (was 53 scalar ops)
__device__ __forceinline__ void bp_tree_19(const uint16_t* v2c, uint16_t* excl) {
    uint32_t a0 = bp_pack(v2c[0],  v2c[1]);
    uint32_t a1 = bp_pack(v2c[2],  v2c[3]);
    uint32_t a2 = bp_pack(v2c[4],  v2c[5]);
    uint32_t a3 = bp_pack(v2c[6],  v2c[7]);
    uint32_t a4 = bp_pack(v2c[8],  v2c[9]);
    uint32_t a5 = bp_pack(v2c[10], v2c[11]);
    uint32_t a6 = bp_pack(v2c[12], v2c[13]);
    uint32_t a7 = bp_pack(v2c[14], v2c[15]);
    uint32_t a8 = bp_pack(v2c[16], v2c[17]);
    uint32_t a9 = bp_dup_low(v2c[18]);

    // (1-4) Pair up odds/evens in quads
    uint32_t BP_13_02     = box_plus_half2(a1, a0);
    uint32_t BP_57_46     = box_plus_half2(a2, a3);
    uint32_t BP_911_810   = box_plus_half2(a4, a5);
    uint32_t BP_1315_1214 = box_plus_half2(a6, a7);

    // (5-6) Combine pairs
    uint32_t BP_1357_0246         = box_plus_half2(BP_13_02, BP_57_46);
    uint32_t BP_91113_15_81012_14 = box_plus_half2(BP_911_810, BP_1315_1214);

    // (7) Extend with 17,16
    uint32_t BP_9111315_17_8101214_16 = box_plus_half2(BP_91113_15_81012_14, a8);

    // (8) 9-way cross product
    uint32_t BP_odd9_even9 = box_plus_half2(BP_1357_0246, BP_9111315_17_8101214_16);
    uint32_t BP_even9_odd9 = bp_swap_hl(BP_odd9_even9);

    // (9) output 9 (without 18)
    uint32_t BP_all18_all18 = box_plus_half2(BP_odd9_even9, BP_even9_odd9);

    // (10) Include 18
    uint32_t BP_even9_18_odd9_18 = box_plus_half2(BP_even9_odd9, a9);

    // (11) without [9111315_17, 8101214_16]
    uint32_t BP_wo_hi5_hi = box_plus_half2(BP_even9_18_odd9_18, BP_1357_0246);

    // (12) without [1357, 0246]
    uint32_t BP_wo_lo4    = box_plus_half2(BP_even9_18_odd9_18, BP_9111315_17_8101214_16);

    // (13) without [17, 16] -> output 8
    uint32_t seq8 = box_plus_half2(BP_wo_hi5_hi, BP_91113_15_81012_14);

    // (14) without [91113_15, 81012_14]
    uint32_t BP_wo_hi5_hi_1716 = box_plus_half2(BP_wo_hi5_hi, a8);

    // (15) without [1315, 1214]
    uint32_t BP_wo_1315_1214 = box_plus_half2(BP_wo_hi5_hi_1716, BP_911_810);

    // (16) without [15, 14] -> output 7
    uint32_t seq7 = box_plus_half2(BP_wo_1315_1214, a6);

    // (17) without [13, 12] -> output 6
    uint32_t seq6 = box_plus_half2(BP_wo_1315_1214, a7);

    // (18) without [911, 810]
    uint32_t BP_wo_911_810 = box_plus_half2(BP_wo_hi5_hi_1716, BP_1315_1214);

    // (19) without [11, 10] -> output 5
    uint32_t seq5 = box_plus_half2(BP_wo_911_810, a4);

    // (20) without [9, 8] -> output 4
    uint32_t seq4 = box_plus_half2(BP_wo_911_810, a5);

    // (21) without [57, 46]
    uint32_t BP_wo_57_46 = box_plus_half2(BP_wo_lo4, BP_13_02);

    // (22) without [7, 6] -> output 3
    uint32_t seq3 = box_plus_half2(BP_wo_57_46, a2);

    // (23) without [5, 4] -> output 2
    uint32_t seq2 = box_plus_half2(BP_wo_57_46, a3);

    // (24) without [13, 02]
    uint32_t BP_wo_13_02 = box_plus_half2(BP_wo_lo4, BP_57_46);

    // (25) without [3, 2] -> output 1
    uint32_t seq1 = box_plus_half2(BP_wo_13_02, a0);

    // (26) without [1, 0] -> output 0
    uint32_t seq0 = box_plus_half2(BP_wo_13_02, a1);

    excl[0]  = (uint16_t)(seq0);
    excl[1]  = (uint16_t)(seq0 >> 16);
    excl[2]  = (uint16_t)(seq1);
    excl[3]  = (uint16_t)(seq1 >> 16);
    excl[4]  = (uint16_t)(seq2);
    excl[5]  = (uint16_t)(seq2 >> 16);
    excl[6]  = (uint16_t)(seq3);
    excl[7]  = (uint16_t)(seq3 >> 16);
    excl[8]  = (uint16_t)(seq4);
    excl[9]  = (uint16_t)(seq4 >> 16);
    excl[10] = (uint16_t)(seq5);
    excl[11] = (uint16_t)(seq5 >> 16);
    excl[12] = (uint16_t)(seq6);
    excl[13] = (uint16_t)(seq6 >> 16);
    excl[14] = (uint16_t)(seq7);
    excl[15] = (uint16_t)(seq7 >> 16);
    excl[16] = (uint16_t)(seq8);
    excl[17] = (uint16_t)(seq8 >> 16);
    excl[18] = (uint16_t)(BP_all18_all18);
}

// --- Per-degree binary tree functions for 2-CB kernel ---
// Input/output: uint32_t arrays (half2: [CB1 | CB0])
// Each box_plus_half2 computes exclusion product for both CBs simultaneously.
// Tree structure follows same pattern but no pair-packing trick (half2 already used for dual-CB).

__device__ __forceinline__ void bp_tree_3_h2(const uint32_t* v2c, uint32_t* excl) {
    uint32_t s01 = box_plus_half2(v2c[0], v2c[1]);
    uint32_t s02 = box_plus_half2(v2c[0], v2c[2]);
    uint32_t s12 = box_plus_half2(v2c[1], v2c[2]);
    excl[0] = s12;
    excl[1] = s02;
    excl[2] = s01;
}

__device__ __forceinline__ void bp_tree_4_h2(const uint32_t* v2c, uint32_t* excl) {
    uint32_t s01 = box_plus_half2(v2c[0], v2c[1]);
    uint32_t s23 = box_plus_half2(v2c[2], v2c[3]);
    uint32_t s0123 = box_plus_half2(s01, s23);
    // Use forward/backward prefix for efficiency
    uint32_t s02 = box_plus_half2(v2c[0], v2c[2]);
    uint32_t s13 = box_plus_half2(v2c[1], v2c[3]);
    excl[0] = box_plus_half2(s13, v2c[2]);    // bp(1,2,3)
    excl[1] = box_plus_half2(s02, v2c[3]);    // bp(0,2,3)
    excl[2] = box_plus_half2(s13, v2c[0]);    // bp(0,1,3)
    excl[3] = box_plus_half2(s02, v2c[1]);    // bp(0,1,2)
}

__device__ __forceinline__ void bp_tree_5_h2(const uint32_t* v2c, uint32_t* excl) {
    uint32_t s01 = box_plus_half2(v2c[0], v2c[1]);
    uint32_t s23 = box_plus_half2(v2c[2], v2c[3]);
    uint32_t s0123 = box_plus_half2(s01, s23);
    uint32_t s014 = box_plus_half2(s01, v2c[4]);
    uint32_t s234 = box_plus_half2(s23, v2c[4]);
    excl[0] = box_plus_half2(s234, v2c[1]);    // bp(1,2,3,4)
    excl[1] = box_plus_half2(s234, v2c[0]);    // bp(0,2,3,4)
    excl[2] = box_plus_half2(s014, v2c[3]);    // bp(0,1,3,4)
    excl[3] = box_plus_half2(s014, v2c[2]);    // bp(0,1,2,4)
    excl[4] = s0123;                            // bp(0,1,2,3)
}

__device__ __forceinline__ void bp_tree_6_h2(const uint32_t* v2c, uint32_t* excl) {
    uint32_t s01 = box_plus_half2(v2c[0], v2c[1]);
    uint32_t s23 = box_plus_half2(v2c[2], v2c[3]);
    uint32_t s45 = box_plus_half2(v2c[4], v2c[5]);
    uint32_t s0123 = box_plus_half2(s01, s23);
    uint32_t s2345 = box_plus_half2(s23, s45);
    uint32_t s0145 = box_plus_half2(s01, s45);
    excl[0] = box_plus_half2(s2345, v2c[1]);
    excl[1] = box_plus_half2(s2345, v2c[0]);
    excl[2] = box_plus_half2(s0145, v2c[3]);
    excl[3] = box_plus_half2(s0145, v2c[2]);
    excl[4] = box_plus_half2(s0123, v2c[5]);
    excl[5] = box_plus_half2(s0123, v2c[4]);
}

__device__ __forceinline__ void bp_tree_7_h2(const uint32_t* v2c, uint32_t* excl) {
    uint32_t s01 = box_plus_half2(v2c[0], v2c[1]);
    uint32_t s23 = box_plus_half2(v2c[2], v2c[3]);
    uint32_t s45 = box_plus_half2(v2c[4], v2c[5]);
    uint32_t s0123 = box_plus_half2(s01, s23);
    uint32_t s456  = box_plus_half2(s45, v2c[6]);
    uint32_t s23456 = box_plus_half2(s23, s456);
    uint32_t s01456 = box_plus_half2(s01, s456);
    uint32_t s01236 = box_plus_half2(s0123, v2c[6]);
    uint32_t s012345 = box_plus_half2(s0123, s45);
    excl[0] = box_plus_half2(s23456, v2c[1]);
    excl[1] = box_plus_half2(s23456, v2c[0]);
    excl[2] = box_plus_half2(s01456, v2c[3]);
    excl[3] = box_plus_half2(s01456, v2c[2]);
    excl[4] = box_plus_half2(s01236, v2c[5]);
    excl[5] = box_plus_half2(s01236, v2c[4]);
    excl[6] = s012345;
}

__device__ __forceinline__ void bp_tree_8_h2(const uint32_t* v2c, uint32_t* excl) {
    uint32_t s01 = box_plus_half2(v2c[0], v2c[1]);
    uint32_t s23 = box_plus_half2(v2c[2], v2c[3]);
    uint32_t s45 = box_plus_half2(v2c[4], v2c[5]);
    uint32_t s67 = box_plus_half2(v2c[6], v2c[7]);
    uint32_t s0123 = box_plus_half2(s01, s23);
    uint32_t s4567 = box_plus_half2(s45, s67);
    uint32_t s2345_67 = box_plus_half2(s23, s4567);
    uint32_t s01_4567 = box_plus_half2(s01, s4567);
    uint32_t s0123_67 = box_plus_half2(s0123, s67);
    uint32_t s0123_45 = box_plus_half2(s0123, s45);
    excl[0] = box_plus_half2(s2345_67, v2c[1]);
    excl[1] = box_plus_half2(s2345_67, v2c[0]);
    excl[2] = box_plus_half2(s01_4567, v2c[3]);
    excl[3] = box_plus_half2(s01_4567, v2c[2]);
    excl[4] = box_plus_half2(s0123_67, v2c[5]);
    excl[5] = box_plus_half2(s0123_67, v2c[4]);
    excl[6] = box_plus_half2(s0123_45, v2c[7]);
    excl[7] = box_plus_half2(s0123_45, v2c[6]);
}

__device__ __forceinline__ void bp_tree_9_h2(const uint32_t* v2c, uint32_t* excl) {
    uint32_t s01 = box_plus_half2(v2c[0], v2c[1]);
    uint32_t s23 = box_plus_half2(v2c[2], v2c[3]);
    uint32_t s45 = box_plus_half2(v2c[4], v2c[5]);
    uint32_t s67 = box_plus_half2(v2c[6], v2c[7]);
    uint32_t s0123 = box_plus_half2(s01, s23);
    uint32_t s4567 = box_plus_half2(s45, s67);
    uint32_t s01234567 = box_plus_half2(s0123, s4567);
    uint32_t s45678 = box_plus_half2(s4567, v2c[8]);
    uint32_t s01238 = box_plus_half2(s0123, v2c[8]);
    uint32_t s2345_678 = box_plus_half2(s23, s45678);
    uint32_t s01_45678 = box_plus_half2(s01, s45678);
    uint32_t s0123_678 = box_plus_half2(s01238, s67);
    uint32_t s0123_458 = box_plus_half2(s01238, s45);
    excl[0] = box_plus_half2(s2345_678, v2c[1]);
    excl[1] = box_plus_half2(s2345_678, v2c[0]);
    excl[2] = box_plus_half2(s01_45678, v2c[3]);
    excl[3] = box_plus_half2(s01_45678, v2c[2]);
    excl[4] = box_plus_half2(s0123_678, v2c[5]);
    excl[5] = box_plus_half2(s0123_678, v2c[4]);
    excl[6] = box_plus_half2(s0123_458, v2c[7]);
    excl[7] = box_plus_half2(s0123_458, v2c[6]);
    excl[8] = s01234567;
}

__device__ __forceinline__ void bp_tree_10_h2(const uint32_t* v2c, uint32_t* excl) {
    uint32_t s01 = box_plus_half2(v2c[0], v2c[1]);
    uint32_t s23 = box_plus_half2(v2c[2], v2c[3]);
    uint32_t s45 = box_plus_half2(v2c[4], v2c[5]);
    uint32_t s67 = box_plus_half2(v2c[6], v2c[7]);
    uint32_t s89 = box_plus_half2(v2c[8], v2c[9]);
    uint32_t s0123 = box_plus_half2(s01, s23);
    uint32_t s4567 = box_plus_half2(s45, s67);
    uint32_t s456789 = box_plus_half2(s4567, s89);
    uint32_t s012389 = box_plus_half2(s0123, s89);
    uint32_t s01234567 = box_plus_half2(s0123, s4567);
    uint32_t s23456789 = box_plus_half2(s23, s456789);
    uint32_t s01456789 = box_plus_half2(s01, s456789);
    uint32_t s01236789 = box_plus_half2(s012389, s67);
    uint32_t s01234589 = box_plus_half2(s012389, s45);
    uint32_t s01234567_e8 = box_plus_half2(s01234567, v2c[9]);
    uint32_t s01234567_e9 = box_plus_half2(s01234567, v2c[8]);
    excl[0] = box_plus_half2(s23456789, v2c[1]);
    excl[1] = box_plus_half2(s23456789, v2c[0]);
    excl[2] = box_plus_half2(s01456789, v2c[3]);
    excl[3] = box_plus_half2(s01456789, v2c[2]);
    excl[4] = box_plus_half2(s01236789, v2c[5]);
    excl[5] = box_plus_half2(s01236789, v2c[4]);
    excl[6] = box_plus_half2(s01234589, v2c[7]);
    excl[7] = box_plus_half2(s01234589, v2c[6]);
    excl[8] = s01234567_e8;
    excl[9] = s01234567_e9;
}

__device__ __forceinline__ void bp_tree_19_h2(const uint32_t* v2c, uint32_t* excl) {
    // Layer 1: pairs
    uint32_t s01 = box_plus_half2(v2c[0], v2c[1]);
    uint32_t s23 = box_plus_half2(v2c[2], v2c[3]);
    uint32_t s45 = box_plus_half2(v2c[4], v2c[5]);
    uint32_t s67 = box_plus_half2(v2c[6], v2c[7]);
    uint32_t s89 = box_plus_half2(v2c[8], v2c[9]);
    uint32_t sAB = box_plus_half2(v2c[10], v2c[11]);
    uint32_t sCD = box_plus_half2(v2c[12], v2c[13]);
    uint32_t sEF = box_plus_half2(v2c[14], v2c[15]);
    uint32_t sGH = box_plus_half2(v2c[16], v2c[17]);

    // Layer 2: quads
    uint32_t s0123 = box_plus_half2(s01, s23);
    uint32_t s4567 = box_plus_half2(s45, s67);
    uint32_t s89AB = box_plus_half2(s89, sAB);
    uint32_t sCDEF = box_plus_half2(sCD, sEF);

    // Layer 3: octets
    uint32_t s01234567 = box_plus_half2(s0123, s4567);
    uint32_t s89ABCDEF = box_plus_half2(s89AB, sCDEF);

    // Extend with GH and v[18]
    uint32_t s89ABCDEFGH = box_plus_half2(s89ABCDEF, sGH);
    uint32_t sAll_wo18 = box_plus_half2(s01234567, s89ABCDEFGH);

    uint32_t s89ABCDEFGH_18 = box_plus_half2(s89ABCDEFGH, v2c[18]);
    uint32_t s01234567_18   = box_plus_half2(s01234567, v2c[18]);

    // Exclude pairs from each half
    uint32_t wo_0123 = box_plus_half2(s4567, s89ABCDEFGH_18);
    uint32_t wo_4567 = box_plus_half2(s0123, s89ABCDEFGH_18);
    uint32_t wo_89AB = box_plus_half2(s01234567_18, sCDEF);
    uint32_t wo_89AB_GH = box_plus_half2(wo_89AB, sGH);
    uint32_t wo_CDEF = box_plus_half2(s01234567_18, s89AB);
    uint32_t wo_CDEF_GH = box_plus_half2(wo_CDEF, sGH);
    uint32_t wo_GH = box_plus_half2(s01234567_18, s89ABCDEF);

    // Further exclude sub-pairs
    uint32_t wo_01 = box_plus_half2(wo_0123, s23);
    uint32_t wo_23 = box_plus_half2(wo_0123, s01);
    uint32_t wo_45 = box_plus_half2(wo_4567, s67);
    uint32_t wo_67 = box_plus_half2(wo_4567, s45);
    uint32_t wo_89 = box_plus_half2(wo_89AB_GH, sAB);
    uint32_t wo_AB = box_plus_half2(wo_89AB_GH, s89);
    uint32_t wo_CD = box_plus_half2(wo_CDEF_GH, sEF);
    uint32_t wo_EF = box_plus_half2(wo_CDEF_GH, sCD);

    // Final: exclude individual elements
    excl[0]  = box_plus_half2(wo_01, v2c[1]);
    excl[1]  = box_plus_half2(wo_01, v2c[0]);
    excl[2]  = box_plus_half2(wo_23, v2c[3]);
    excl[3]  = box_plus_half2(wo_23, v2c[2]);
    excl[4]  = box_plus_half2(wo_45, v2c[5]);
    excl[5]  = box_plus_half2(wo_45, v2c[4]);
    excl[6]  = box_plus_half2(wo_67, v2c[7]);
    excl[7]  = box_plus_half2(wo_67, v2c[6]);
    excl[8]  = box_plus_half2(wo_89, v2c[9]);
    excl[9]  = box_plus_half2(wo_89, v2c[8]);
    excl[10] = box_plus_half2(wo_AB, v2c[11]);
    excl[11] = box_plus_half2(wo_AB, v2c[10]);
    excl[12] = box_plus_half2(wo_CD, v2c[13]);
    excl[13] = box_plus_half2(wo_CD, v2c[12]);
    excl[14] = box_plus_half2(wo_EF, v2c[15]);
    excl[15] = box_plus_half2(wo_EF, v2c[14]);
    excl[16] = box_plus_half2(wo_GH, v2c[17]);
    excl[17] = box_plus_half2(wo_GH, v2c[16]);
    excl[18] = sAll_wo18;
}

static inline int compute_shift(int shift_ref, int Z, int Z_ref) {
    // 3GPP TS 38.212 Section 5.3.2: The actual shift for lifting size Z is
    // V(i,j) mod Z, where V(i,j) are the shift coefficients from the base
    // graph table (defined per lifting set, NOT per Z).
    (void)Z_ref;
    if (shift_ref == 0) return 0;
    if (shift_ref < 0) return -1;
    return shift_ref % Z;
}

// Lifting set bases and reference Z values per 3GPP TS 38.212 Table 5.3.2-1
static const int LIFTING_SET_BASES[8] = {2, 3, 5, 7, 9, 11, 13, 15};
static const int LIFTING_SET_Z_REF[8] = {256, 384, 320, 224, 288, 352, 208, 240};

static int get_lifting_set_idx(int Z) {
    for (int i = 0; i < 8; i++) {
        int base = LIFTING_SET_BASES[i];
        if (Z % base == 0) {
            int ratio = Z / base;
            // Check if ratio is a power of 2
            if (ratio > 0 && (ratio & (ratio - 1)) == 0) {
                return i;
            }
        }
    }
    return 1;  // Default to set 1 (Z_ref=384)
}

static int get_Z_ref(int Z) {
    int set_idx = get_lifting_set_idx(Z);
    return LIFTING_SET_Z_REF[set_idx];
}

// ============================================================================
// Decoder Context
// ============================================================================

// Platform detection for adaptive kernel selection
enum class DecoderPlatform {
    GH200,          // 132 SMs, high compute, HBM3
    DGX_SPARK,      // 48 SMs, Grace Blackwell
    RTX_4090,       // 128 SMs, consumer
    RTX_3090,       // 82 SMs, consumer
    DRIVE_THOR,     // 20 SMs, automotive
    DRIVE_ORIN,     // 16 SMs, automotive
    OTHER
};

struct PlatformConfig {
    DecoderPlatform platform;
    int sm_count;
    int max_shmem_per_block;  // Max dynamic shared memory per block (bytes, opt-in)
    int optimal_batch;       // Optimal batch size for this platform
    int kernel_variant;      // 0=x1, 1=x2
    int default_max_iter;    // Platform-aware iteration limit
};

static PlatformConfig detect_platform() {
    cudaDeviceProp prop;
    int device;
    cudaGetDevice(&device);
    cudaGetDeviceProperties(&prop, device);

    PlatformConfig cfg;
    cfg.sm_count = prop.multiProcessorCount;

    // Query max opt-in shared memory per block
    int max_shmem_optin = 0;
    cudaDeviceGetAttribute(&max_shmem_optin,
        cudaDevAttrMaxSharedMemoryPerBlockOptin, device);
    cfg.max_shmem_per_block = max_shmem_optin;

    // Platform detection based on SM count and compute capability
    if (cfg.sm_count >= 100) {
        // GH200 or similar high-end
        cfg.platform = DecoderPlatform::GH200;
        cfg.optimal_batch = 240;  // 4 CBs/block * 60 blocks
        cfg.kernel_variant = 1;   // half2 x2
        cfg.default_max_iter = 6;
    } else if (cfg.sm_count >= 80) {
        // RTX 3090/4090 class or DGX Spark
        if (prop.major >= 9) {
            cfg.platform = DecoderPlatform::DGX_SPARK;
            cfg.optimal_batch = 48;
            cfg.kernel_variant = 1;  // half2 x2
            cfg.default_max_iter = 6;
        } else {
            cfg.platform = DecoderPlatform::RTX_4090;
            cfg.optimal_batch = 16;
            cfg.kernel_variant = 1;
            cfg.default_max_iter = 8;
        }
    } else if (cfg.sm_count >= 40) {
        // Mid-range desktop or DGX Spark
        cfg.platform = DecoderPlatform::DGX_SPARK;
        cfg.optimal_batch = 32;
        cfg.kernel_variant = 1;
        cfg.default_max_iter = 6;
    } else if (cfg.sm_count >= 20) {
        // DRIVE Thor class
        cfg.platform = DecoderPlatform::DRIVE_THOR;
        cfg.optimal_batch = 8;
        cfg.kernel_variant = 1;
        cfg.default_max_iter = 4;  // Power-constrained
    } else {
        // DRIVE Orin or smaller
        cfg.platform = DecoderPlatform::DRIVE_ORIN;
        cfg.optimal_batch = 4;
        cfg.kernel_variant = 0;   // x1 for lowest latency
        cfg.default_max_iter = 3; // Aggressive early termination
    }

    return cfg;
}

struct FlexibleLdpcDecoder {
    nr_ldpc_config_t config;
    ldpc_decoder_params_t params;

    int base_graph;
    int Z;
    int Z_ref;  // Reference Z for shift scaling
    int Kb;
    int N;
    int M;          // Number of parity rows (used for rate-adaptive norm)
    int nnz;
    int max_deg;
    int K_bits;
    int K_words;
    int N_llrs;
    float effective_scale;  // Actual scale factor used (may be rate-adaptive)

    // Platform-specific configuration (queried at creation)
    PlatformConfig platform_cfg;

    // Pre-scaled shifts for current Z (stored on device)
    int16_t* d_scaled_shifts;

    // Working memory (FP32 decoder - single buffer for non-E2E path)
    __half* d_app;      // APP LLRs: N * Z per codeword
    __half* d_c2v;      // C2V messages: M * max_deg * Z per codeword
    size_t workspace_size;
    int max_batch_size;

    // Working memory (FP16 decoder - TRIPLE-BUFFERED for E2E GPU-resident path)
    // This prevents race conditions where decode N+1 clears workspace while decode N is still running
    static constexpr int NUM_WORKSPACE_BUFFERS = 3;
    __half* d_app_half[NUM_WORKSPACE_BUFFERS];      // APP LLRs for FP16 E2E decoder
    __half* d_c2v_half[NUM_WORKSPACE_BUFFERS];      // C2V messages for FP16 E2E decoder
    size_t workspace_size_half;
    int max_batch_size_half;
    int current_workspace_buf;  // Rotating buffer index (0, 1, 2)
    cudaEvent_t workspace_complete[NUM_WORKSPACE_BUFFERS];  // Completion events for each buffer

    // Iteration tracking (shared across all decode modes)
    int* d_iterations;          // Device buffer for per-CB iteration counts
    int* h_iterations;          // Host buffer for per-CB iteration counts
    int iterations_buffer_size; // Current buffer size in elements
    float last_avg_iterations;  // Last computed average iterations

    // CRC results tracking (reuse kernel CRC computation)
    int* d_crc_results;         // Device buffer for per-CB CRC results
    int* h_crc_results;         // Host buffer for per-CB CRC results
    int crc_results_buffer_size; // Current buffer size in elements

    // Deferred iteration stats (async D2H without blocking decode)
    cudaEvent_t iteration_stats_event;  // Event to sync on for deferred stats
    bool iteration_stats_pending;       // True if D2H copy issued but not yet read
    int iteration_stats_count;          // Number of codewords in pending stats
    bool deferred_stats_enabled;        // Whether deferred mode is active

    // OPTIMIZATION: Cache last config to avoid per-slot malloc/free/memcpy
    // The shift table only depends on base_graph and Z
    int cached_base_graph;      // -1 = not cached
    int cached_Z;               // -1 = not cached

    // Cache for layered shmem probes (avoid per-batch cudaFuncSetAttribute)
    bool layered_half2_shmem_ok;      // true if 2-CB FULL_SHMEM kernel fits
    bool layered_half_shmem_ok;       // true if 1-CB FULL_SHMEM kernel fits
    bool boxplus_half2_shmem_ok;      // true if 2-CB boxplus FULL_SHMEM kernel fits
    bool boxplus_half_shmem_ok;       // true if 1-CB boxplus FULL_SHMEM kernel fits
    bool layered_half2_shmem_probed;  // true if we've already probed
    int shmem_mode;                   // -1=auto, 0=force low-shmem, 1=prefer full-shmem
    int one_cb_max_cbs;               // >=0 overrides 1-CB/2-CB switch threshold
    int c2v_mode;                     // -1=auto, 0=force per-edge C2V, 1=force compressed C2V
    int app_cache_cols;               // 0=auto, otherwise cache this many APP columns in 1-CB kernels

};

// ============================================================================
// Optimized Layered Decoding Kernel (processes 2 codewords per block)
// ============================================================================

template<int BG>  // 1 or 2
__global__ void __launch_bounds__(384, 2)
ldpc_decode_layered_x2_kernel(
    const float* __restrict__ d_channel_llrs,
    __half* __restrict__ d_app,
    __half* __restrict__ d_c2v,
    uint32_t* __restrict__ d_output,
    const int16_t* __restrict__ d_scaled_shifts,  // Pre-scaled shifts for current Z
    int Z,
    int N,
    int M,
    int Kb,
    int nnz,
    int max_deg,
    int llr_stride,
    int output_stride,
    int max_iterations,
    __half scale,
    __half offset,  // Offset min-sum parameter
    __half clamp,
    int num_cbs,
    int* __restrict__ d_iterations = nullptr,  // Optional: output iterations per CB
    bool crc_early_termination = true,         // Enable CRC-based early termination
    __half confidence_threshold = __float2half(0.25f),  // Confidence threshold for CRC check
    int crc_check_bits = 0,  // Number of bits to CRC check (K - filler bits). 0 = use Kb*Z
    int crc_type = 3  // CRC type: 0=none, 1=CRC16, 2=CRC24A, 3=CRC24B (LDPC_CRC_24B_INTERNAL)
) {
    // Shared memory for confidence-based early termination
    // s_uncertain[i] = 1 if codeword i has any info bit with |APP| < threshold
    __shared__ uint32_t s_uncertain[2];
    __shared__ int s_final_iter;  // Track when convergence happens
    // CRC results for both codewords (set by thread 0 during CRC computation)
    __shared__ uint32_t s_crc_result[2];

    // Get graph pointers based on template parameter (constant memory)
    const int16_t* row_ptr = (BG == 1) ? d_bg1_row_ptr : d_bg2_row_ptr;
    const int8_t* col_idx = (BG == 1) ? d_bg1_col : d_bg2_col;
    // Use pre-scaled shifts passed as parameter
    const int16_t* shifts = d_scaled_shifts;

    // Each block processes 2 codewords
    int cb_pair_idx = blockIdx.x;
    int cb0_idx = cb_pair_idx * 2;
    int cb1_idx = cb_pair_idx * 2 + 1;

    bool cb0_valid = (cb0_idx < num_cbs);
    bool cb1_valid = (cb1_idx < num_cbs);
    if (!cb0_valid) return;

    int tid = threadIdx.x;
    if (tid >= Z) return;

    // Pointers for codeword 0
    const float* channel0 = d_channel_llrs + cb0_idx * llr_stride;
    __half* app0 = d_app + cb0_idx * N * Z;
    __half* c2v0 = d_c2v + cb0_idx * M * max_deg * Z;
    uint32_t* output0 = d_output + cb0_idx * output_stride;

    // Pointers for codeword 1
    const float* channel1 = cb1_valid ? (d_channel_llrs + cb1_idx * llr_stride) : channel0;
    __half* app1 = cb1_valid ? (d_app + cb1_idx * N * Z) : app0;
    __half* c2v1 = cb1_valid ? (d_c2v + cb1_idx * M * max_deg * Z) : c2v0;
    uint32_t* output1 = cb1_valid ? (d_output + cb1_idx * output_stride) : output0;

    __half zero = __float2half(0.0f);
    __half large = __float2half(1e4f);

    // Initialize APP LLRs from channel
    for (int col = 0; col < N; col++) {
        int idx = col * Z + tid;
        __half llr0 = (idx < llr_stride) ? clamp_half(__float2half(channel0[idx]), clamp) : zero;
        app0[idx] = llr0;
        if (cb1_valid) {
            __half llr1 = (idx < llr_stride) ? clamp_half(__float2half(channel1[idx]), clamp) : zero;
            app1[idx] = llr1;
        }
    }

    // Skip C2V zero-initialization — iteration 0 never reads C2V (see below).

    // Initialize final iteration counter
    if (tid == 0) {
        s_final_iter = max_iterations;
    }
    __syncthreads();

    // Layered decoding iterations with early termination
    int final_iter = max_iterations;
    for (int iter = 0; iter < max_iterations; iter++) {
        for (int row = 0; row < M; row++) {
            int row_start = row_ptr[row];
            int row_end = row_ptr[row + 1];
            int row_deg = row_end - row_start;

            if (row_deg == 0) continue;

            // PASS 1: Compute V2C and find min1/min2/sign for both codewords
            // On iter 0, C2V is zero so V2C = APP directly (skip global reads)
            uint32_t sign_bits0 = 0, sign_bits1 = 0;
            __half min1_0 = large, min2_0 = large, min1_1 = large, min2_1 = large;
            int min1_idx0 = 0, min1_idx1 = 0;

            for (int e = 0; e < row_deg; e++) {
                int col = col_idx[row_start + e];
                int shift = shifts[row_start + e];
                int shifted_z = fast_mod(tid + shift, Z);

                // Codeword 0
                __half app_val0 = app0[col * Z + shifted_z];
                __half v2c_val0;
                if (iter == 0) {
                    v2c_val0 = app_val0;
                } else {
                    int c2v_idx = (row * max_deg + e) * Z + tid;
                    v2c_val0 = __hsub(app_val0, c2v0[c2v_idx]);
                }
                sign_bits0 |= (sign_bit(v2c_val0) << e);
                __half abs_v0 = habs(v2c_val0);

                if (__hlt(abs_v0, min1_0)) {
                    min2_0 = min1_0;
                    min1_0 = abs_v0;
                    min1_idx0 = e;
                } else if (__hlt(abs_v0, min2_0)) {
                    min2_0 = abs_v0;
                }

                // Codeword 1
                if (cb1_valid) {
                    __half app_val1 = app1[col * Z + shifted_z];
                    __half v2c_val1;
                    if (iter == 0) {
                        v2c_val1 = app_val1;
                    } else {
                        int c2v_idx = (row * max_deg + e) * Z + tid;
                        v2c_val1 = __hsub(app_val1, c2v1[c2v_idx]);
                    }
                    sign_bits1 |= (sign_bit(v2c_val1) << e);
                    __half abs_v1 = habs(v2c_val1);

                    if (__hlt(abs_v1, min1_1)) {
                        min2_1 = min1_1;
                        min1_1 = abs_v1;
                        min1_idx1 = e;
                    } else if (__hlt(abs_v1, min2_1)) {
                        min2_1 = abs_v1;
                    }
                }
            }

            // Ensure min2 is valid
            if (__hgt(min2_0, __float2half(1e3f))) min2_0 = min1_0;
            if (__hgt(min2_1, __float2half(1e3f))) min2_1 = min1_1;

            int sign_parity0 = __popc(sign_bits0) & 1;
            int sign_parity1 = __popc(sign_bits1) & 1;

            // PASS 2: Compute new C2V and update APP
            // On iter 0, old C2V is zero so V2C = APP (skip C2V reads)
            for (int e = 0; e < row_deg; e++) {
                int col = col_idx[row_start + e];
                int shift = shifts[row_start + e];
                int shifted_z = fast_mod(tid + shift, Z);
                int c2v_idx = (row * max_deg + e) * Z + tid;

                // Codeword 0
                __half app_val0 = app0[col * Z + shifted_z];
                __half v2c_val0;
                if (iter == 0) {
                    v2c_val0 = app_val0;
                } else {
                    v2c_val0 = __hsub(app_val0, c2v0[c2v_idx]);
                }

                __half mag0 = (e == min1_idx0) ? min2_0 : min1_0;
                int this_sign0 = (sign_bits0 >> e) & 1;
                int result_sign0 = sign_parity0 ^ this_sign0;
                __half scaled_mag0 = __hmax(__hsub(__hmul(scale, mag0), offset), __float2half(0.0f));
                __half new_c2v0 = conditional_neg(scaled_mag0, result_sign0);
                new_c2v0 = clamp_half(new_c2v0, clamp);
                c2v0[c2v_idx] = new_c2v0;
                app0[col * Z + shifted_z] = __hadd(v2c_val0, new_c2v0);

                // Codeword 1
                if (cb1_valid) {
                    __half app_val1 = app1[col * Z + shifted_z];
                    __half v2c_val1;
                    if (iter == 0) {
                        v2c_val1 = app_val1;
                    } else {
                        v2c_val1 = __hsub(app_val1, c2v1[c2v_idx]);
                    }

                    __half mag1 = (e == min1_idx1) ? min2_1 : min1_1;
                    int this_sign1 = (sign_bits1 >> e) & 1;
                    int result_sign1 = sign_parity1 ^ this_sign1;
                    __half scaled_mag1 = __hmax(__hsub(__hmul(scale, mag1), offset), __float2half(0.0f));
                    __half new_c2v1 = conditional_neg(scaled_mag1, result_sign1);
                    new_c2v1 = clamp_half(new_c2v1, clamp);
                    c2v1[c2v_idx] = new_c2v1;
                    app1[col * Z + shifted_z] = __hadd(v2c_val1, new_c2v1);
                }
            }

            // CRITICAL: Sync after each row for proper layered decoding
            // Without this, updates from row N may not be visible to row N+1
            __syncthreads();

        }

        // HYBRID SYNDROME + CRC EARLY TERMINATION
        // Phase 1: Syndrome check (parity verification) - exact convergence detection
        // Phase 2: If converged and CRC enabled, verify with CRC for early exit
        // Check every 4 iterations to reduce overhead
        constexpr int FP16_CHECKPOINT_INTERVAL = 4;
        const bool is_checkpoint = ((iter + 1) % FP16_CHECKPOINT_INTERVAL == 0) || (iter == max_iterations - 1);

        if (is_checkpoint) {
            // Reset syndrome counters and CRC results
            if (tid == 0) {
                s_uncertain[0] = 0;
                s_uncertain[1] = 0;
                s_crc_result[0] = 0xFFFFFFFF;
                s_crc_result[1] = 0xFFFFFFFF;
            }
            __syncthreads();

            // PHASE 1: Syndrome check - verify all parity equations
            // This is the gold standard for convergence detection
            uint32_t local_syndrome0 = 0;
            uint32_t local_syndrome1 = 0;
            for (int row = 0; row < M; row++) {
                int row_start = row_ptr[row];
                int row_end = row_ptr[row + 1];

                uint32_t row_parity0 = 0;
                uint32_t row_parity1 = 0;
                for (int e = row_start; e < row_end; e++) {
                    int col = col_idx[e];
                    int shift = shifts[e];
                    int shifted_z = fast_mod(tid + shift, Z);
                    row_parity0 ^= sign_bit(app0[col * Z + shifted_z]);
                    if (cb1_valid) {
                        row_parity1 ^= sign_bit(app1[col * Z + shifted_z]);
                    }
                }
                local_syndrome0 |= row_parity0;
                local_syndrome1 |= row_parity1;
            }

            // WARP-LEVEL SYNDROME REDUCTION
            const unsigned int warp_mask_fp32 = (Z >= 32) ? 0xFFFFFFFF : ((1u << Z) - 1);
            const int lane_id_fp32 = tid & 31;

            unsigned int warp_syn0 = __ballot_sync(warp_mask_fp32, local_syndrome0);
            unsigned int warp_syn1 = cb1_valid ? __ballot_sync(warp_mask_fp32, local_syndrome1) : 0;

            if (lane_id_fp32 == 0) {
                if (warp_syn0) atomicOr(&s_uncertain[0], 1);
                if (warp_syn1) atomicOr(&s_uncertain[1], 1);
            }
            __syncthreads();

            bool cb0_converged = (s_uncertain[0] == 0);
            bool cb1_converged = !cb1_valid || (s_uncertain[1] == 0);

            // PHASE 2: If syndrome passes and CRC ET enabled, do CRC verification
            if (crc_early_termination && crc_type != LDPC_CRC_NONE_INTERNAL && (cb0_converged || cb1_converged)) {
                const int total_bits = (crc_check_bits > 0) ? crc_check_bits : (Kb * Z);
                const int total_bytes = (total_bits + 7) / 8;

                if (tid == 0) {
                    if (cb0_converged) {
                        uint32_t crc0 = 0;
                        for (int byte_idx = 0; byte_idx < total_bytes; byte_idx++) {
                            uint8_t byte = 0;
                            for (int b = 0; b < 8 && (byte_idx * 8 + b) < total_bits; b++) {
                                int bit_idx = byte_idx * 8 + b;
                                int col = bit_idx / Z;
                                int row = bit_idx % Z;
                                __half app_val = app0[col * Z + row];
                                if (__hlt(app_val, zero)) {
                                    byte |= (1 << b);
                                }
                            }
                            if (crc_type == LDPC_CRC_16_INTERNAL) {
                                crc0 = (crc0 >> 8) ^ d_rcrc16_table_ldpc[(crc0 ^ byte) & 0xFF];
                            } else if (crc_type == LDPC_CRC_24A_INTERNAL) {
                                crc0 = (crc0 >> 8) ^ d_rcrc24a_table_ldpc[(crc0 ^ byte) & 0xFF];
                            } else {
                                crc0 = (crc0 >> 8) ^ d_rcrc24b_table_ldpc[(crc0 ^ byte) & 0xFF];
                            }
                        }
                        s_crc_result[0] = crc0;
                    }

                    if (cb1_converged && cb1_valid) {
                        uint32_t crc1 = 0;
                        for (int byte_idx = 0; byte_idx < total_bytes; byte_idx++) {
                            uint8_t byte = 0;
                            for (int b = 0; b < 8 && (byte_idx * 8 + b) < total_bits; b++) {
                                int bit_idx = byte_idx * 8 + b;
                                int col = bit_idx / Z;
                                int row = bit_idx % Z;
                                __half app_val = app1[col * Z + row];
                                if (__hlt(app_val, zero)) {
                                    byte |= (1 << b);
                                }
                            }
                            if (crc_type == LDPC_CRC_16_INTERNAL) {
                                crc1 = (crc1 >> 8) ^ d_rcrc16_table_ldpc[(crc1 ^ byte) & 0xFF];
                            } else if (crc_type == LDPC_CRC_24A_INTERNAL) {
                                crc1 = (crc1 >> 8) ^ d_rcrc24a_table_ldpc[(crc1 ^ byte) & 0xFF];
                            } else {
                                crc1 = (crc1 >> 8) ^ d_rcrc24b_table_ldpc[(crc1 ^ byte) & 0xFF];
                            }
                        }
                        s_crc_result[1] = crc1;
                    }
                }
                __syncthreads();

                // Only terminate if BOTH syndrome AND CRC pass
                cb0_converged = cb0_converged && (s_crc_result[0] == 0);
                cb1_converged = !cb1_valid || (cb1_converged && (s_crc_result[1] == 0));
            }

            // Terminate if all codewords converged (syndrome-only or syndrome+CRC)
            if (cb0_converged && cb1_converged) {
                final_iter = iter + 1;
                if (tid == 0) {
                    s_final_iter = final_iter;
                }
                break;
            }
        }
    }

    // Ensure all threads see the final iteration count
    __syncthreads();
    final_iter = s_final_iter;

    // Hard decision using atomicOr (works for any Z value)
    // Writes MSB-first-per-byte directly (no separate reformat kernel needed).
    for (int col = 0; col < Kb; col++) {
        int bit_idx = col * Z + tid;
        int word_idx = bit_idx / 32;
        int bit_pos = msb_first_bit_pos(bit_idx);

        // Codeword 0
        __half llr0 = app0[col * Z + tid];
        int bit0 = __hlt(llr0, zero) ? 1 : 0;
        if (word_idx < output_stride && bit0) {
            atomicOr(&output0[word_idx], 1u << bit_pos);
        }

        // Codeword 1
        if (cb1_valid) {
            __half llr1 = app1[col * Z + tid];
            int bit1 = __hlt(llr1, zero) ? 1 : 0;
            if (word_idx < output_stride && bit1) {
                atomicOr(&output1[word_idx], 1u << bit_pos);
            }
        }
    }

    // Write iteration counts if requested
    if (d_iterations != nullptr && tid == 0) {
        d_iterations[cb0_idx] = final_iter;
        if (cb1_valid) {
            d_iterations[cb1_idx] = final_iter;
        }
    }
}

// ============================================================================
// 1-CB Scalar Kernel: Higher occupancy for small batch sizes
// Processes 1 codeword per block with scalar __half arithmetic.
// Half the shared memory of the 2-CB kernel → more blocks per SM.
// No index caches — recomputes from __constant__ memory.
// ============================================================================

template<int BG, bool FULL_SHMEM = true>
__global__ void __launch_bounds__(384, 2)
ldpc_decode_layered_half_kernel(
    const __half* __restrict__ d_channel_llrs,
    __half* __restrict__ d_app,
    __half* __restrict__ d_c2v,
    uint32_t* __restrict__ d_output,
    const int16_t* __restrict__ d_scaled_shifts,
    int Z,
    int N,
    int M,
    int Kb,
    int nnz,
    int max_deg,
    int llr_stride,
    int output_stride,
    int max_iterations,
    __half scale,
    __half offset,
    __half clamp,
    int num_cbs,
    int* __restrict__ d_iterations = nullptr,
    bool crc_early_termination = true,
    __half confidence_threshold = __float2half(0.25f),
    int crc_check_bits = 0,
    int crc_type = 3,
    int* __restrict__ d_crc_results = nullptr,
    int filler_start = 0,
    int filler_count = 0,
    int app_cache_cols = 0
) {
    __shared__ int s_final_iter;
    __shared__ uint32_t s_crc_result;

    extern __shared__ char s_dynamic[];
    int shmem_cols = FULL_SHMEM ? N : app_cache_cols;
    if (!FULL_SHMEM) {
        if (shmem_cols < Kb) shmem_cols = Kb;
        if (shmem_cols > N) shmem_cols = N;
    }
    __half* s_app = reinterpret_cast<__half*>(s_dynamic);

    const int16_t* row_ptr = (BG == 1) ? d_bg1_row_ptr : d_bg2_row_ptr;
    const int8_t* col_idx = (BG == 1) ? d_bg1_col : d_bg2_col;
    const int16_t* shifts = d_scaled_shifts;

    int cb_idx = blockIdx.x;
    if (cb_idx >= num_cbs) return;

    int tid = threadIdx.x;
    if (tid >= Z) return;

    const __half* channel = d_channel_llrs + cb_idx * llr_stride;
    __half* c2v = d_c2v + cb_idx * M * max_deg * Z;
    uint32_t* output = d_output + cb_idx * output_stride;
    __half* app_global = d_app + cb_idx * N * Z;

    __half zero = __float2half(0.0f);
    __half large = __float2half(1e4f);

    // Initialize APP values from channel LLRs
    for (int col = 0; col < N; col++) {
        int idx = col * Z + tid;
        __half llr = (idx < llr_stride) ? clamp_half(__ldg(&channel[idx]), clamp) : zero;

        if (filler_count > 0 && idx >= filler_start && idx < filler_start + filler_count) {
            llr = large;
        }

        if (FULL_SHMEM || col < shmem_cols) {
            s_app[idx] = llr;
        } else {
            app_global[idx] = llr;
        }
    }

    __syncthreads();

    if (tid == 0) {
        s_final_iter = max_iterations;
    }

    // The ballot hard-decision path below overwrites every output word when Z
    // is word-aligned. Only clear for the atomicOr fallback, and clear each
    // word once instead of once per bit lane.
    if ((Z & 31) != 0) {
        for (int col = 0; col < Kb; col++) {
            int flat_bit = col * Z + tid;
            int word_idx = flat_bit / 32;
            if ((word_idx < output_stride) && ((flat_bit & 31) == 0)) {
                output[word_idx] = 0;
            }
        }
        __syncthreads();
    }

    // Layered min-sum decoding iterations
    int final_iter = max_iterations;
    for (int iter = 0; iter < max_iterations; iter++) {
        bool check_syndrome = true;

        for (int row = 0; row < M; row++) {
            int row_start = row_ptr[row];
            int row_end = row_ptr[row + 1];
            int degree = row_end - row_start;

            // PASS 1: Compute V2C and find min1/min2/sign
            constexpr int H_MAX_DEG = (BG == 1) ? 19 : 10;
            uint32_t v2c_cache_raw[H_MAX_DEG];  // Store __half as uint16_t in low bits

            uint32_t sign_bits = 0;
            __half min1 = large, min2 = large;
            int min1_idx = -1;

            #pragma unroll 8
            for (int e = 0; e < degree; e++) {
                int col = col_idx[row_start + e];
                int shift = shifts[row_start + e];
                int shifted_z = tid + shift;
                if (shifted_z >= Z) shifted_z -= Z;
                int c2v_idx = (row * max_deg + e) * Z + tid;
                int llr_pos = col * Z + shifted_z;

                __half app_val;
                if (FULL_SHMEM || col < shmem_cols) {
                    app_val = s_app[llr_pos];
                } else {
                    app_val = app_global[llr_pos];
                }

                __half v2c_val;
                if (iter == 0) {
                    v2c_val = app_val;
                } else {
                    __half old_c2v = c2v[c2v_idx];
                    v2c_val = __hsub(app_val, old_c2v);
                }

                // Cache V2C as raw bits
                v2c_cache_raw[e] = *reinterpret_cast<uint16_t*>(&v2c_val);

                sign_bits |= (sign_bit(v2c_val) << e);

                __half abs_v = __habs(v2c_val);
                if (__hlt(abs_v, min1)) {
                    min2 = min1;
                    min1 = abs_v;
                    min1_idx = e;
                } else if (__hlt(abs_v, min2)) {
                    min2 = abs_v;
                }
            }

            if (__hgt(min2, __float2half(1e3f))) min2 = min1;

            int sign_parity = __popc(sign_bits) & 1;

            // PASS 2: Compute C2V and update APP
            #pragma unroll 8
            for (int e = 0; e < degree; e++) {
                int col = col_idx[row_start + e];
                int shift = shifts[row_start + e];
                int shifted_z = tid + shift;
                if (shifted_z >= Z) shifted_z -= Z;
                int app_idx = col * Z + shifted_z;
                int c2v_idx = (row * max_deg + e) * Z + tid;

                __half v2c_val = *reinterpret_cast<__half*>(&v2c_cache_raw[e]);

                __half mag = (e == min1_idx) ? min2 : min1;

                int this_sign = (sign_bits >> e) & 1;
                int result_sign = sign_parity ^ this_sign;

                __half scaled_mag = __hsub(__hmul(scale, mag), offset);
                scaled_mag = __hmax(scaled_mag, zero);

                __half new_c2v = result_sign ? __hneg(scaled_mag) : scaled_mag;
                new_c2v = __hmax(__hmin(new_c2v, clamp), __hneg(clamp));

                __half new_app = __hadd(v2c_val, new_c2v);

                c2v[c2v_idx] = new_c2v;

                if (FULL_SHMEM || col < shmem_cols) {
                    s_app[app_idx] = new_app;
                } else {
                    app_global[app_idx] = new_app;
                }
            }

            if (!FULL_SHMEM) __threadfence_block();
            __syncthreads();
        }

        // CRC EARLY TERMINATION
        if (check_syndrome && crc_early_termination && crc_type != LDPC_CRC_NONE_INTERNAL) {
            if (tid == 0) {
                s_crc_result = 0xFFFFFFFF;
            }
            __syncthreads();

            const int total_bits = (crc_check_bits > 0) ? crc_check_bits : (Kb * Z);

            uint32_t polynomial;
            uint32_t crc_highbit;
            uint32_t crc_mask;
            int crc_order;
            if (crc_type == LDPC_CRC_16_INTERNAL) {
                polynomial = 0x11021u;
                crc_highbit = 1u << 16;
                crc_mask = 0xFFFFu;
                crc_order = 16;
            } else if (crc_type == LDPC_CRC_24A_INTERNAL) {
                polynomial = 0x1864CFBu;
                crc_highbit = 1u << 24;
                crc_mask = 0xFFFFFFu;
                crc_order = 24;
            } else {
                polynomial = 0x1800063u;
                crc_highbit = 1u << 24;
                crc_mask = 0xFFFFFFu;
                crc_order = 24;
            }

            constexpr int WARP_CRC_THRESHOLD = 4096;

            if (total_bits < WARP_CRC_THRESHOLD) {
                // Serial CRC: thread 0 only
                if (tid == 0) {
                    uint32_t crc = 0;
                    int col = 0, row = 0;
                    for (int i = 0; i < total_bits; i++) {
                        uint32_t bit = __hlt(s_app[col * Z + row], zero) ? 1u : 0u;
                        crc = (crc << 1) | bit;
                        if (crc & crc_highbit) crc ^= polynomial;
                        if (++row >= Z) { row = 0; col++; }
                    }
                    s_crc_result = crc & crc_mask;
                }
            } else {
                // Warp-cooperative CRC
                if (tid < 32) {
                    const int lane_id = tid;
                    uint32_t crc_val = 0;
                    const int total_rounds = (total_bits + 31) / 32;

                    for (int round = 0; round < total_rounds; round++) {
                        int my_bit = round * 32 + lane_id;
                        bool sign = false;
                        if (my_bit < total_bits) {
                            int col = my_bit / Z;
                            int row = my_bit % Z;
                            sign = __hlt(s_app[col * Z + row], zero);
                        }
                        uint32_t ballot = __ballot_sync(0xFFFFFFFF, sign);
                        uint32_t word = __brev(ballot);
                        int bits_this_round = min(32, total_bits - round * 32);

                        if (lane_id == 0) {
                            int full_bytes = bits_this_round / 8;
                            int remaining = bits_this_round % 8;
                            for (int b = 0; b < full_bytes; b++) {
                                uint8_t byte_val = (word >> (24 - b * 8)) & 0xFF;
                                if (crc_order == 16) {
                                    crc_val = (crc_val << 8) ^ d_crc16_table_ldpc[((crc_val >> 8) ^ byte_val) & 0xFF];
                                } else if (crc_type == LDPC_CRC_24A_INTERNAL) {
                                    crc_val = (crc_val << 8) ^ d_crc24a_table_ldpc[((crc_val >> 16) ^ byte_val) & 0xFF];
                                } else {
                                    crc_val = (crc_val << 8) ^ d_crc24b_table_ldpc[((crc_val >> 16) ^ byte_val) & 0xFF];
                                }
                            }
                            if (remaining > 0) {
                                int shift = 24 - full_bytes * 8;
                                for (int r = 0; r < remaining; r++) {
                                    uint32_t bit = (word >> (shift + 7 - r)) & 1u;
                                    crc_val = (crc_val << 1) | bit;
                                    if (crc_val & crc_highbit) crc_val ^= polynomial;
                                }
                            }
                        }
                    }
                    if (lane_id == 0) s_crc_result = crc_val & crc_mask;
                }
            }
            __syncthreads();

            if (s_crc_result == 0) {
                final_iter = iter + 1;
                if (tid == 0) {
                    s_final_iter = final_iter;
                }
                break;
            }
        }
    }

    __syncthreads();
    final_iter = s_final_iter;

    // Hard decision
    if ((Z & 31) == 0) {
        int lane_id = tid & 31;
        for (int col = 0; col < Kb; col++) {
            int flat_bit = col * Z + tid;
            int word_idx = flat_bit / 32;

            if (word_idx < output_stride) {
                int bit = __hlt(s_app[col * Z + tid], zero) ? 1 : 0;
                unsigned int ballot = __ballot_sync(0xFFFFFFFF, bit);
                if (lane_id == 0) {
                    ballot = ((ballot & 0xF0F0F0F0) >> 4) | ((ballot & 0x0F0F0F0F) << 4);
                    ballot = ((ballot & 0xCCCCCCCC) >> 2) | ((ballot & 0x33333333) << 2);
                    ballot = ((ballot & 0xAAAAAAAA) >> 1) | ((ballot & 0x55555555) << 1);
                    output[word_idx] = ballot;
                }
            }
        }
    } else {
        for (int col = 0; col < Kb; col++) {
            int flat_bit = col * Z + tid;
            int word_idx = flat_bit / 32;
            int bit_pos = msb_first_bit_pos(flat_bit);

            if (word_idx < output_stride) {
                int bit = __hlt(s_app[col * Z + tid], zero) ? 1 : 0;
                if (bit) atomicOr(&output[word_idx], 1u << bit_pos);
            }
        }
    }

    if (d_iterations != nullptr && tid == 0) {
        d_iterations[cb_idx] = final_iter;
    }

    if (d_crc_results != nullptr && tid == 0) {
        d_crc_results[cb_idx] = s_crc_result;
    }
}

// ============================================================================
// OPTIMIZED: half2 Vectorized Kernel (2x throughput for arithmetic ops)
// Packs cb0 and cb1 values into half2 for vectorized processing
// ============================================================================

template<int BG, bool FULL_SHMEM = true>
__global__ void __launch_bounds__(384, 2)
ldpc_decode_layered_half2_kernel(
    const __half* __restrict__ d_channel_llrs,
    __half* __restrict__ d_app,
    __half* __restrict__ d_c2v,
    uint32_t* __restrict__ d_output,
    const int16_t* __restrict__ d_scaled_shifts,
    int Z,
    int N,
    int M,
    int Kb,
    int nnz,
    int max_deg,
    int llr_stride,
    int output_stride,
    int max_iterations,
    __half scale,
    __half offset,
    __half clamp,
    int num_cbs,
    int* __restrict__ d_iterations = nullptr,  // Optional: output iterations per CB
    bool crc_early_termination = true,         // Enable CRC-based early termination
    __half confidence_threshold = __float2half(0.25f),  // Confidence threshold for CRC check
    int crc_check_bits = 0,  // Number of bits to CRC check (K - filler bits). 0 = use Kb*Z
    int crc_type = 3,  // CRC type: 0=none, 1=CRC16, 2=CRC24A, 3=CRC24B (LDPC_CRC_24B_INTERNAL)
    int* __restrict__ d_crc_results = nullptr,  // Optional: output CRC results per CB
    int filler_start = 0,  // Start position of filler bits in buffer (= num_info_bits = K)
    int filler_count = 0   // Number of filler bits (= F = Kb*Z - K). 0 = no filler
) {
    // Shared memory for CRC early termination
    __shared__ int s_final_iter;
    __shared__ uint32_t s_crc_result[2];

    // Dynamic shared memory for APP values.
    // FULL_SHMEM=true:  ALL columns (N * Z) — no global APP access during iteration
    // FULL_SHMEM=false: Info columns only (Kb * Z) — parity columns use global d_app
    extern __shared__ char s_dynamic[];
    const int shmem_cols = FULL_SHMEM ? N : Kb;
    __half* s_app_0 = reinterpret_cast<__half*>(s_dynamic);
    __half* s_app_1 = reinterpret_cast<__half*>(s_dynamic + shmem_cols * Z * sizeof(__half));

    const int16_t* row_ptr = (BG == 1) ? d_bg1_row_ptr : d_bg2_row_ptr;
    const int8_t* col_idx = (BG == 1) ? d_bg1_col : d_bg2_col;
    const int16_t* shifts = d_scaled_shifts;

    // Each block processes 2 codewords
    int cb_pair_idx = blockIdx.x;
    int cb0_idx = cb_pair_idx * 2;
    int cb1_idx = cb_pair_idx * 2 + 1;

    bool cb0_valid = (cb0_idx < num_cbs);
    bool cb1_valid = (cb1_idx < num_cbs);
    if (!cb0_valid) return;

    int tid = threadIdx.x;
    if (tid >= Z) return;

    // Pointers for both codewords
    const __half* channel0 = d_channel_llrs + cb0_idx * llr_stride;
    const __half* channel1 = cb1_valid ? (d_channel_llrs + cb1_idx * llr_stride) : channel0;
    __half* c2v0 = d_c2v + cb0_idx * M * max_deg * Z;
    __half* c2v1 = cb1_valid ? (d_c2v + cb1_idx * M * max_deg * Z) : c2v0;
    uint32_t* output0 = d_output + cb0_idx * output_stride;
    uint32_t* output1 = cb1_valid ? (d_output + cb1_idx * output_stride) : output0;

    // Global APP pointers (used for parity columns when !FULL_SHMEM)
    __half* app0 = d_app + cb0_idx * N * Z;
    __half* app1 = cb1_valid ? (d_app + cb1_idx * N * Z) : app0;

    // half2 constants
    half2 zero2 = __float2half2_rn(0.0f);
    half2 large2 = __float2half2_rn(1e4f);
    half2 clamp2 = __halves2half2(clamp, clamp);
    half2 scale2 = __halves2half2(scale, scale);
    half2 offset2 = __halves2half2(offset, offset);
    __half zero = __float2half(0.0f);
    __half large = __float2half(1e4f);

    // Initialize APP values from channel LLRs.
    // Filler bit positions [filler_start, filler_start + filler_count) are set to large (1e4)
    // to force the decoder to treat them as known bits (replacing separate filler kernel).
    // FULL_SHMEM=true:  all columns go to shared memory only
    // FULL_SHMEM=false: all columns go to global, info columns (col < Kb) also to shared
    for (int col = 0; col < N; col++) {
        int idx = col * Z + tid;
        __half llr0 = (idx < llr_stride) ? clamp_half(__ldg(&channel0[idx]), clamp) : zero;
        __half llr1 = cb1_valid ? ((idx < llr_stride) ? clamp_half(__ldg(&channel1[idx]), clamp) : zero) : zero;

        // Override filler bit positions with large LLR
        if (filler_count > 0 && idx >= filler_start && idx < filler_start + filler_count) {
            llr0 = large;
            llr1 = large;
        }

        if (FULL_SHMEM) {
            // All columns in shared memory
            s_app_0[idx] = llr0;
            if (cb1_valid) s_app_1[idx] = llr1;
        } else {
            // All columns to global memory
            app0[idx] = llr0;
            if (cb1_valid) app1[idx] = llr1;
            // Info columns also to shared memory for fast access
            if (col < Kb) {
                s_app_0[idx] = llr0;
                if (cb1_valid) s_app_1[idx] = llr1;
            }
        }
    }

    // Sync to ensure all threads see shared memory APP initialization
    __syncthreads();

    // Skip C2V zero-initialization — iteration 0 never reads C2V (see below).

    // Initialize final iteration counter
    if (tid == 0) {
        s_final_iter = max_iterations;
    }

    // The ballot hard-decision path below overwrites every output word when Z
    // is word-aligned. Only clear for the atomicOr fallback, and clear each
    // word once instead of once per bit lane.
    if ((Z & 31) != 0) {
        for (int col = 0; col < Kb; col++) {
            int flat_bit = col * Z + tid;
            int word_idx = flat_bit / 32;
            if ((word_idx < output_stride) && ((flat_bit & 31) == 0)) {
                output0[word_idx] = 0;
                if (cb1_valid) output1[word_idx] = 0;
            }
        }
        __syncthreads();
    }

    // Layered min-sum decoding iterations with memory fence optimization
    int final_iter = max_iterations;
    for (int iter = 0; iter < max_iterations; iter++) {
        // Check syndrome every iteration for early termination
        bool check_syndrome = true;

        // Layered decoding: process rows sequentially, each row sees updated APP from previous rows
        for (int row = 0; row < M; row++) {

            int row_start = row_ptr[row];
            int row_end = row_ptr[row + 1];
            int degree = row_end - row_start;

            // PASS 1: Compute V2C and find min1/min2/sign using half2
            // On iter 0, C2V is zero so V2C = APP directly (skip global reads)
            // Cache V2C values in registers to avoid reloading in pass 2
            constexpr int H2_MAX_DEG = (BG == 1) ? 19 : 10;
            uint32_t v2c_cache[H2_MAX_DEG];  // Packed half2 V2C values

            uint32_t sign_bits0 = 0, sign_bits1 = 0;
            __half min1_0 = large, min2_0 = large, min1_1 = large, min2_1 = large;
            int min1_idx0 = -1, min1_idx1 = -1;

            #pragma unroll 8
            for (int e = 0; e < degree; e++) {
                int col = col_idx[row_start + e];
                int shift = shifts[row_start + e];
                int shifted_z = tid + shift;
                if (shifted_z >= Z) shifted_z -= Z;
                int c2v_idx = (row * max_deg + e) * Z + tid;
                int llr_pos = col * Z + shifted_z;

                // Read APP: shared memory for all cols (FULL_SHMEM) or info only (!FULL_SHMEM)
                __half app_val0, app_val1;
                if (FULL_SHMEM) {
                    app_val0 = s_app_0[llr_pos];
                    app_val1 = cb1_valid ? s_app_1[llr_pos] : zero;
                } else {
                    app_val0 = (col < Kb) ? s_app_0[llr_pos] : app0[llr_pos];
                    app_val1 = cb1_valid ? ((col < Kb) ? s_app_1[llr_pos] : app1[llr_pos]) : zero;
                }

                half2 app_packed = __halves2half2(app_val0, app_val1);
                half2 v2c_packed;
                if (iter == 0) {
                    v2c_packed = app_packed;
                } else {
                    __half old_c2v0_val = c2v0[c2v_idx];
                    __half old_c2v1_val = cb1_valid ? c2v1[c2v_idx] : zero;
                    half2 c2v_packed = __halves2half2(old_c2v0_val, old_c2v1_val);
                    v2c_packed = __hsub2(app_packed, c2v_packed);
                }

                // Cache V2C for pass 2 (indices recomputed from __constant__ memory)
                v2c_cache[e] = *reinterpret_cast<uint32_t*>(&v2c_packed);

                __half v2c_val0 = __low2half(v2c_packed);
                __half v2c_val1 = __high2half(v2c_packed);

                sign_bits0 |= (sign_bit(v2c_val0) << e);
                if (cb1_valid) sign_bits1 |= (sign_bit(v2c_val1) << e);

                half2 abs_v = habs2(v2c_packed);
                __half abs_v0 = __low2half(abs_v);
                __half abs_v1 = __high2half(abs_v);

                if (__hlt(abs_v0, min1_0)) {
                    min2_0 = min1_0;
                    min1_0 = abs_v0;
                    min1_idx0 = e;
                } else if (__hlt(abs_v0, min2_0)) {
                    min2_0 = abs_v0;
                }

                if (cb1_valid) {
                    if (__hlt(abs_v1, min1_1)) {
                        min2_1 = min1_1;
                        min1_1 = abs_v1;
                        min1_idx1 = e;
                    } else if (__hlt(abs_v1, min2_1)) {
                        min2_1 = abs_v1;
                    }
                }
            }

            if (__hgt(min2_0, __float2half(1e3f))) min2_0 = min1_0;
            if (__hgt(min2_1, __float2half(1e3f))) min2_1 = min1_1;

            int sign_parity0 = __popc(sign_bits0) & 1;
            int sign_parity1 = __popc(sign_bits1) & 1;

            // PASS 2: Compute C2V and update APP using cached V2C from pass 1
            #pragma unroll 8
            for (int e = 0; e < degree; e++) {
                int col = col_idx[row_start + e];
                int shift = shifts[row_start + e];
                int shifted_z = tid + shift;
                if (shifted_z >= Z) shifted_z -= Z;
                int app_idx = col * Z + shifted_z;
                int c2v_idx = (row * max_deg + e) * Z + tid;

                half2 v2c_packed = *reinterpret_cast<half2*>(&v2c_cache[e]);

                __half mag0 = (e == min1_idx0) ? min2_0 : min1_0;
                __half mag1 = (e == min1_idx1) ? min2_1 : min1_1;

                int this_sign0 = (sign_bits0 >> e) & 1;
                int this_sign1 = (sign_bits1 >> e) & 1;
                int result_sign0 = sign_parity0 ^ this_sign0;
                int result_sign1 = sign_parity1 ^ this_sign1;

                half2 mag_packed = __halves2half2(mag0, mag1);
                half2 scaled = __hsub2(__hmul2(scale2, mag_packed), offset2);
                scaled = __hmax2(scaled, zero2);

                half2 new_c2v = conditional_neg2(scaled, result_sign0, result_sign1);
                new_c2v = clamp_half2(new_c2v, clamp2);

                half2 new_app = __hadd2(v2c_packed, new_c2v);

                __half new_c2v0 = __low2half(new_c2v);
                __half new_c2v1 = __high2half(new_c2v);
                __half new_app0 = __low2half(new_app);
                __half new_app1 = __high2half(new_app);

                c2v0[c2v_idx] = new_c2v0;

                if (FULL_SHMEM) {
                    // All columns in shared memory — no global writes during iteration
                    s_app_0[app_idx] = new_app0;
                    if (cb1_valid) s_app_1[app_idx] = new_app1;
                } else {
                    // Info columns: update both shared and global
                    // Parity columns: global only
                    if (col < Kb) {
                        s_app_0[app_idx] = new_app0;
                        if (cb1_valid) s_app_1[app_idx] = new_app1;
                    }
                    app0[app_idx] = new_app0;
                    if (cb1_valid) app1[app_idx] = new_app1;
                }

                if (cb1_valid) {
                    c2v1[c2v_idx] = new_c2v1;
                }
            }

                    // CRITICAL FIX: Layered decoding requires BOTH fence and sync!
            // 1. Fence ensures memory writes are visible across threads
            // 2. Sync ensures ALL threads finish current row before ANY start next row
            __threadfence_block();
            __syncthreads();

        }

        // CRC EARLY TERMINATION
        // Two paths: serial (small blocks) and warp-cooperative (large blocks).
        // Warp-cooperative uses __ballot_sync + byte CRC table, ~8x faster for BG1 Z=384
        // but has overhead that hurts small blocks. Threshold: 2048 bits (~64 ballot rounds).
        if (check_syndrome && crc_early_termination && crc_type != LDPC_CRC_NONE_INTERNAL) {
            if (tid == 0) {
                s_crc_result[0] = 0xFFFFFFFF;
                s_crc_result[1] = 0xFFFFFFFF;
            }
            __syncthreads();

            const int total_bits = (crc_check_bits > 0) ? crc_check_bits : (Kb * Z);

            // Select CRC polynomial, order, and mask based on CRC type.
            uint32_t polynomial;
            uint32_t crc_highbit;
            uint32_t crc_mask;
            int crc_order;
            if (crc_type == LDPC_CRC_16_INTERNAL) {
                polynomial = 0x11021u;
                crc_highbit = 1u << 16;
                crc_mask = 0xFFFFu;
                crc_order = 16;
            } else if (crc_type == LDPC_CRC_24A_INTERNAL) {
                polynomial = 0x1864CFBu;
                crc_highbit = 1u << 24;
                crc_mask = 0xFFFFFFu;
                crc_order = 24;
            } else {
                polynomial = 0x1800063u;
                crc_highbit = 1u << 24;
                crc_mask = 0xFFFFFFu;
                crc_order = 24;
            }

            constexpr int WARP_CRC_THRESHOLD = 4096;

            if (total_bits < WARP_CRC_THRESHOLD) {
                // Serial CRC: thread 0 does CB0, thread 1 does CB1.
                // Faster for small blocks where warp coordination overhead dominates.
                if (tid == 0 || (tid == 1 && cb1_valid)) {
                    const __half* s_app = (tid == 0) ? s_app_0 : s_app_1;
                    uint32_t crc = 0;
                    int col = 0, row = 0;
                    for (int i = 0; i < total_bits; i++) {
                        uint32_t bit = __hlt(s_app[col * Z + row], zero) ? 1u : 0u;
                        crc = (crc << 1) | bit;
                        if (crc & crc_highbit) crc ^= polynomial;
                        if (++row >= Z) { row = 0; col++; }
                    }
                    s_crc_result[tid] = crc & crc_mask;
                }
            } else {
                // Warp-cooperative CRC: first warp (32 threads) participates.
                // Each thread reads one APP value per ballot round; ballot packs 32 sign bits.
                // __brev() converts lane-0-in-LSB to lane-0-in-MSB for MSB-first CRC.
                if (tid < 32) {
                    const int lane_id = tid;
                    uint32_t crc0 = 0, crc1 = 0;
                    const int total_rounds = (total_bits + 31) / 32;

                    for (int round = 0; round < total_rounds; round++) {
                        int my_bit = round * 32 + lane_id;
                        bool sign0 = false, sign1 = false;
                        if (my_bit < total_bits) {
                            int col = my_bit / Z;
                            int row = my_bit % Z;
                            sign0 = __hlt(s_app_0[col * Z + row], zero);
                            if (cb1_valid) sign1 = __hlt(s_app_1[col * Z + row], zero);
                        }
                        uint32_t ballot0 = __ballot_sync(0xFFFFFFFF, sign0);
                        uint32_t ballot1 = cb1_valid ? __ballot_sync(0xFFFFFFFF, sign1) : 0;

                        uint32_t word0 = __brev(ballot0);
                        uint32_t word1 = __brev(ballot1);
                        int bits_this_round = min(32, total_bits - round * 32);

                        if (lane_id == 0) {
                            int full_bytes = bits_this_round / 8;
                            int remaining = bits_this_round % 8;
                            for (int b = 0; b < full_bytes; b++) {
                                uint8_t byte_val = (word0 >> (24 - b * 8)) & 0xFF;
                                if (crc_order == 16) {
                                    crc0 = (crc0 << 8) ^ d_crc16_table_ldpc[((crc0 >> 8) ^ byte_val) & 0xFF];
                                } else if (crc_type == LDPC_CRC_24A_INTERNAL) {
                                    crc0 = (crc0 << 8) ^ d_crc24a_table_ldpc[((crc0 >> 16) ^ byte_val) & 0xFF];
                                } else {
                                    crc0 = (crc0 << 8) ^ d_crc24b_table_ldpc[((crc0 >> 16) ^ byte_val) & 0xFF];
                                }
                            }
                            if (remaining > 0) {
                                int shift = 24 - full_bytes * 8;
                                for (int r = 0; r < remaining; r++) {
                                    uint32_t bit = (word0 >> (shift + 7 - r)) & 1u;
                                    crc0 = (crc0 << 1) | bit;
                                    if (crc0 & crc_highbit) crc0 ^= polynomial;
                                }
                            }
                        }
                        if (lane_id == 1 && cb1_valid) {
                            int full_bytes = bits_this_round / 8;
                            int remaining = bits_this_round % 8;
                            for (int b = 0; b < full_bytes; b++) {
                                uint8_t byte_val = (word1 >> (24 - b * 8)) & 0xFF;
                                if (crc_order == 16) {
                                    crc1 = (crc1 << 8) ^ d_crc16_table_ldpc[((crc1 >> 8) ^ byte_val) & 0xFF];
                                } else if (crc_type == LDPC_CRC_24A_INTERNAL) {
                                    crc1 = (crc1 << 8) ^ d_crc24a_table_ldpc[((crc1 >> 16) ^ byte_val) & 0xFF];
                                } else {
                                    crc1 = (crc1 << 8) ^ d_crc24b_table_ldpc[((crc1 >> 16) ^ byte_val) & 0xFF];
                                }
                            }
                            if (remaining > 0) {
                                int shift = 24 - full_bytes * 8;
                                for (int r = 0; r < remaining; r++) {
                                    uint32_t bit = (word1 >> (shift + 7 - r)) & 1u;
                                    crc1 = (crc1 << 1) | bit;
                                    if (crc1 & crc_highbit) crc1 ^= polynomial;
                                }
                            }
                        }
                    }
                    if (lane_id == 0) s_crc_result[0] = crc0 & crc_mask;
                    if (lane_id == 1 && cb1_valid) s_crc_result[1] = crc1 & crc_mask;
                }
            }
            __syncthreads();

            bool cb0_converged = (s_crc_result[0] == 0);
            bool cb1_converged = !cb1_valid || (s_crc_result[1] == 0);

            if (cb0_converged && cb1_converged) {
                final_iter = iter + 1;
                if (tid == 0) {
                    s_final_iter = final_iter;
                }
                break;
            }
        }
    }

    // Ensure all threads see the final iteration count
    __syncthreads();
    final_iter = s_final_iter;

    // Hard decision from shared memory (MSB-first-per-byte directly)
    if ((Z & 31) == 0) {
        // Fast path: Z is a multiple of 32, use warp ballot for word-aligned writes
        // Apply byte-reversal to ballot result for MSB-first-per-byte format.
        int lane_id = tid & 31;
        for (int col = 0; col < Kb; col++) {
            int flat_bit = col * Z + tid;
            int word_idx = flat_bit / 32;

            if (word_idx < output_stride) {
                int bit0 = __hlt(s_app_0[col * Z + tid], zero) ? 1 : 0;
                unsigned int ballot0 = __ballot_sync(0xFFFFFFFF, bit0);
                if (lane_id == 0) {
                    // Reverse bits within each byte (same as reformat_bits_kernel)
                    ballot0 = ((ballot0 & 0xF0F0F0F0) >> 4) | ((ballot0 & 0x0F0F0F0F) << 4);
                    ballot0 = ((ballot0 & 0xCCCCCCCC) >> 2) | ((ballot0 & 0x33333333) << 2);
                    ballot0 = ((ballot0 & 0xAAAAAAAA) >> 1) | ((ballot0 & 0x55555555) << 1);
                    output0[word_idx] = ballot0;
                }

                if (cb1_valid) {
                    int bit1 = __hlt(s_app_1[col * Z + tid], zero) ? 1 : 0;
                    unsigned int ballot1 = __ballot_sync(0xFFFFFFFF, bit1);
                    if (lane_id == 0) {
                        ballot1 = ((ballot1 & 0xF0F0F0F0) >> 4) | ((ballot1 & 0x0F0F0F0F) << 4);
                        ballot1 = ((ballot1 & 0xCCCCCCCC) >> 2) | ((ballot1 & 0x33333333) << 2);
                        ballot1 = ((ballot1 & 0xAAAAAAAA) >> 1) | ((ballot1 & 0x55555555) << 1);
                        output1[word_idx] = ballot1;
                    }
                }
            }
        }
    } else {
        // Fallback: per-thread atomicOr (correct for any Z value)
        // MSB-first-per-byte directly
        for (int col = 0; col < Kb; col++) {
            int flat_bit = col * Z + tid;
            int word_idx = flat_bit / 32;
            int bit_pos = msb_first_bit_pos(flat_bit);

            if (word_idx < output_stride) {
                int bit0 = __hlt(s_app_0[col * Z + tid], zero) ? 1 : 0;
                if (bit0) atomicOr(&output0[word_idx], 1u << bit_pos);

                if (cb1_valid) {
                    int bit1 = __hlt(s_app_1[col * Z + tid], zero) ? 1 : 0;
                    if (bit1) atomicOr(&output1[word_idx], 1u << bit_pos);
                }
            }
        }
    }

    if (d_iterations != nullptr && tid == 0) {
        d_iterations[cb0_idx] = final_iter;
        if (cb1_valid) {
            d_iterations[cb1_idx] = final_iter;
        }
    }

    // Write CRC results if requested
    if (d_crc_results != nullptr && tid == 0) {
        d_crc_results[cb0_idx] = s_crc_result[0];
        if (cb1_valid) {
            d_crc_results[cb1_idx] = s_crc_result[1];
        }
    }

}

// ============================================================================
// BOX-PLUS 1-CB Kernel: Higher occupancy for small batch sizes
// Processes 1 codeword per block with scalar box-plus arithmetic.
// Half the shared memory of the 2-CB kernel → more blocks per SM.
// ============================================================================

template<int BG, bool FULL_SHMEM = true, bool OFFSET_ZERO = true>
__global__ void __launch_bounds__(384, 2)
ldpc_decode_boxplus_half_kernel(
    const __half* __restrict__ d_channel_llrs,
    __half* __restrict__ d_app,
    __half* __restrict__ d_c2v,
    uint32_t* __restrict__ d_output,
    const int16_t* __restrict__ d_scaled_shifts,
    int Z,
    int N,
    int M,
    int Kb,
    int nnz,
    int max_deg,
    int llr_stride,
    int output_stride,
    int max_iterations,
    __half scale,
    __half offset,
    __half clamp,
    int num_cbs,
    int* __restrict__ d_iterations = nullptr,
    bool crc_early_termination = true,
    __half confidence_threshold = __float2half(0.25f),
    int crc_check_bits = 0,
    int crc_type = 3,
    int* __restrict__ d_crc_results = nullptr,
    int filler_start = 0,
    int filler_count = 0,
    int app_cache_cols = 0
) {
    __shared__ int s_final_iter;
    __shared__ uint32_t s_crc_result;

    extern __shared__ char s_dynamic[];
    int shmem_cols = FULL_SHMEM ? N : app_cache_cols;
    if (!FULL_SHMEM) {
        if (shmem_cols < Kb) shmem_cols = Kb;
        if (shmem_cols > N) shmem_cols = N;
    }
    __half* s_app = reinterpret_cast<__half*>(s_dynamic);

    const int16_t* row_ptr = (BG == 1) ? d_bg1_row_ptr : d_bg2_row_ptr;
    const int8_t* col_idx = (BG == 1) ? d_bg1_col : d_bg2_col;
    const int16_t* shifts = d_scaled_shifts;

    int cb_idx = blockIdx.x;
    if (cb_idx >= num_cbs) return;

    int tid = threadIdx.x;
    if (tid >= Z) return;

    const __half* channel = d_channel_llrs + cb_idx * llr_stride;
    // Compressed C2V: reinterpret __half* buffer as c2v_compressed_half* (M*Z per CB)
    c2v_compressed_half* c2v_comp = reinterpret_cast<c2v_compressed_half*>(d_c2v) + cb_idx * M * Z;
    uint32_t* output = d_output + cb_idx * output_stride;
    __half* app_global = d_app + cb_idx * N * Z;

    __half zero = __float2half(0.0f);
    __half large = __float2half(1e4f);

    // Initialize APP values from channel LLRs
    for (int col = 0; col < N; col++) {
        int idx = col * Z + tid;
        __half llr = (idx < llr_stride) ? clamp_half(__ldg(&channel[idx]), clamp) : zero;

        if (filler_count > 0 && idx >= filler_start && idx < filler_start + filler_count) {
            llr = large;
        }

        if (FULL_SHMEM || col < shmem_cols) {
            s_app[idx] = llr;
        } else {
            app_global[idx] = llr;
        }
    }

    __syncthreads();

    if (tid == 0) {
        s_final_iter = max_iterations;
    }

    // The ballot hard-decision path below overwrites every output word when Z
    // is word-aligned. Only clear for the atomicOr fallback, and clear each
    // word once instead of once per bit lane.
    if ((Z & 31) != 0) {
        for (int col = 0; col < Kb; col++) {
            int flat_bit = col * Z + tid;
            int word_idx = flat_bit / 32;
            if ((word_idx < output_stride) && ((flat_bit & 31) == 0)) {
                output[word_idx] = 0;
            }
        }
        __syncthreads();
    }

    // V2C cache arrays for compressed C2V min-sum
    constexpr int BP_MAX_DEG = (BG == 1) ? 19 : 10;
    uint16_t v2c_cache_raw[BP_MAX_DEG]; // Cached V2C as raw uint16_t bits

    // Layered box-plus (min.xorsign.abs) decoding iterations
    int final_iter = max_iterations;
    for (int iter = 0; iter < max_iterations; iter++) {
        bool check_syndrome = true;

        for (int row = 0; row < M; row++) {
            int row_start = row_ptr[row];
            int row_end = row_ptr[row + 1];
            int degree = row_end - row_start;

            // Load compressed C2V summary for this row (iter > 0 only)
            c2v_compressed_half old_summary;
            if (iter > 0) {
                old_summary = c2v_comp[row * Z + tid];
            }

            // PASS 1: Compute V2C, cache it, track min1/min2/sign — all fused
            __half v2c_min1_abs = __float2half(65504.0f);
            __half v2c_min2_abs = __float2half(65504.0f);
            int v2c_min1_idx = 0;
            uint32_t v2c_sign_bits = 0;

    #pragma unroll 8
            for (int e = 0; e < degree; e++) {
                int col = col_idx[row_start + e];
                int shift = shifts[row_start + e];
                int shifted_z = tid + shift;
                if (shifted_z >= Z) shifted_z -= Z;

                int llr_pos = col * Z + shifted_z;

                __half app_val;
                if (FULL_SHMEM || col < shmem_cols) {
                    app_val = s_app[llr_pos];
                } else {
                    app_val = app_global[llr_pos];
                }

                __half v2c_val;
                if (iter == 0) {
                    v2c_val = app_val;
                } else {
                    // Reconstruct old C2V from compressed summary
                    uint32_t old_meta = old_summary.meta;
                    uint32_t old_sign_bits = c2v_meta_sign_bits(old_meta);
                    int old_min1_idx = c2v_meta_min1_idx(old_meta);
                    int old_sign_parity = c2v_meta_sign_parity(old_meta);
                    __half old_mag = (e == old_min1_idx) ? old_summary.min2 : old_summary.min1;
                    int old_sign = old_sign_parity ^ ((old_sign_bits >> e) & 1);
                    uint16_t mag_raw = *reinterpret_cast<uint16_t*>(&old_mag);
                    uint16_t old_c2v_raw = old_sign ? (mag_raw | 0x8000) : mag_raw;
                    __half old_c2v = *reinterpret_cast<__half*>(&old_c2v_raw);
                    v2c_val = __hsub(app_val, old_c2v);
                }

                // Cache V2C and track min1/min2/sign inline
                uint16_t raw = *reinterpret_cast<uint16_t*>(&v2c_val);
                v2c_cache_raw[e] = raw;
                v2c_sign_bits |= ((raw >> 15) << e);
                __half v2c_abs = __habs(v2c_val);
                if (__hlt(v2c_abs, v2c_min1_abs)) {
                    v2c_min2_abs = v2c_min1_abs;
                    v2c_min1_abs = v2c_abs;
                    v2c_min1_idx = e;
                } else if (__hlt(v2c_abs, v2c_min2_abs)) {
                    v2c_min2_abs = v2c_abs;
                }
            }
            if (__heq(v2c_min2_abs, __float2half(65504.0f))) v2c_min2_abs = v2c_min1_abs;
            int v2c_sign_parity = __popc(v2c_sign_bits) & 1;

            // PASS 2: Apply NMS, compute compressed C2V summary, and update APP
            // NMS-scale the min values once (shared across all edges)
            __half scaled_min1, scaled_min2;
            if constexpr (OFFSET_ZERO) {
                scaled_min1 = __hmul(scale, v2c_min1_abs);
                scaled_min2 = __hmul(scale, v2c_min2_abs);
            } else {
                scaled_min1 = __hmax(__hsub(__hmul(scale, v2c_min1_abs), offset), zero);
                scaled_min2 = __hmax(__hsub(__hmul(scale, v2c_min2_abs), offset), zero);
                scaled_min1 = __hmin(scaled_min1, clamp);
                scaled_min2 = __hmin(scaled_min2, clamp);
            }

            // Store compressed C2V summary
            c2v_compressed_half new_summary;
            new_summary.min1 = scaled_min1;
            new_summary.min2 = scaled_min2;
            new_summary.meta = c2v_pack_meta(v2c_sign_bits, v2c_min1_idx, v2c_sign_parity);
            c2v_comp[row * Z + tid] = new_summary;

    #pragma unroll 8
            for (int e = 0; e < degree; e++) {
                int col = col_idx[row_start + e];
                int shift = shifts[row_start + e];
                int shifted_z = tid + shift;
                if (shifted_z >= Z) shifted_z -= Z;
                int app_idx = col * Z + shifted_z;

                __half v2c_val = *reinterpret_cast<__half*>(&v2c_cache_raw[e]);

                // Reconstruct new_c2v from compressed representation
                __half new_c2v;
                if (degree == 1) {
                    new_c2v = zero;
                } else {
                    __half mag = (e == v2c_min1_idx) ? scaled_min2 : scaled_min1;
                    int result_sign = v2c_sign_parity ^ ((v2c_sign_bits >> e) & 1);
                    uint16_t mag_raw = *reinterpret_cast<uint16_t*>(&mag);
                    uint16_t c2v_raw = result_sign ? (mag_raw | 0x8000) : mag_raw;
                    new_c2v = *reinterpret_cast<__half*>(&c2v_raw);
                }

                __half new_app = __hadd(v2c_val, new_c2v);

                if (FULL_SHMEM || col < shmem_cols) {
                    s_app[app_idx] = new_app;
                } else {
                    app_global[app_idx] = new_app;
                }
            }

            // Fence only needed for !FULL_SHMEM (app_global cross-thread deps).
            // FULL_SHMEM: __syncthreads() provides full shared memory fence.
            if (!FULL_SHMEM) __threadfence_block();
            __syncthreads();
        }

        // CRC EARLY TERMINATION
        if (check_syndrome && crc_early_termination && crc_type != LDPC_CRC_NONE_INTERNAL) {
            if (tid == 0) {
                s_crc_result = 0xFFFFFFFF;
            }
            __syncthreads();

            const int total_bits = (crc_check_bits > 0) ? crc_check_bits : (Kb * Z);

            uint32_t polynomial;
            uint32_t crc_highbit;
            uint32_t crc_mask;
            int crc_order;
            if (crc_type == LDPC_CRC_16_INTERNAL) {
                polynomial = 0x11021u;
                crc_highbit = 1u << 16;
                crc_mask = 0xFFFFu;
                crc_order = 16;
            } else if (crc_type == LDPC_CRC_24A_INTERNAL) {
                polynomial = 0x1864CFBu;
                crc_highbit = 1u << 24;
                crc_mask = 0xFFFFFFu;
                crc_order = 24;
            } else {
                polynomial = 0x1800063u;
                crc_highbit = 1u << 24;
                crc_mask = 0xFFFFFFu;
                crc_order = 24;
            }

            constexpr int WARP_CRC_THRESHOLD = 4096;

            if (total_bits < WARP_CRC_THRESHOLD) {
                if (tid == 0) {
                    uint32_t crc = 0;
                    int col = 0, row = 0;
                    for (int i = 0; i < total_bits; i++) {
                        uint32_t bit = __hlt(s_app[col * Z + row], zero) ? 1u : 0u;
                        crc = (crc << 1) | bit;
                        if (crc & crc_highbit) crc ^= polynomial;
                        if (++row >= Z) { row = 0; col++; }
                    }
                    s_crc_result = crc & crc_mask;
                }
            } else {
                // True warp-parallel CRC: each lane processes its own chunk
                if (tid < 32) {
                    const int lane_id = tid;

                    // Divide bits evenly across 32 lanes, round up to byte boundary
                    int bits_per_lane = ((total_bits + 31) / 32 + 7) & ~7;
                    int my_start = lane_id * bits_per_lane;
                    int my_end = min(my_start + bits_per_lane, total_bits);
                    int my_bits = max(my_end - my_start, 0);
                    int my_bytes = (my_bits + 7) / 8;

                    // Each lane computes CRC over its chunk
                    uint32_t my_crc = 0;
                    int bit_pos = my_start;
                    int bits_left = my_bits;

                    while (bits_left >= 8) {
                        uint8_t byte_val = 0;
                        #pragma unroll
                        for (int b = 0; b < 8; b++) {
                            int col = bit_pos / Z;
                            int row = bit_pos % Z;
                            uint32_t bit = __hlt(s_app[col * Z + row], zero) ? 1u : 0u;
                            byte_val = (byte_val << 1) | bit;
                            bit_pos++;
                        }
                        if (crc_type == LDPC_CRC_24B_INTERNAL) {
                            my_crc = (my_crc << 8) ^ d_crc24b_table_ldpc[((my_crc >> 16) ^ byte_val) & 0xFF];
                        } else if (crc_type == LDPC_CRC_24A_INTERNAL) {
                            my_crc = (my_crc << 8) ^ d_crc24a_table_ldpc[((my_crc >> 16) ^ byte_val) & 0xFF];
                        } else {
                            my_crc = (my_crc << 8) ^ d_crc16_table_ldpc[((my_crc >> 8) ^ byte_val) & 0xFF];
                        }
                        bits_left -= 8;
                    }
                    // Handle remaining bits (< 8)
                    while (bits_left > 0) {
                        int col = bit_pos / Z;
                        int row = bit_pos % Z;
                        uint32_t bit = __hlt(s_app[col * Z + row], zero) ? 1u : 0u;
                        my_crc = (my_crc << 1) | bit;
                        if (my_crc & crc_highbit) my_crc ^= polynomial;
                        bit_pos++;
                        bits_left--;
                    }
                    my_crc &= crc_mask;

                    // Warp-shuffle tree reduction: combine partial CRCs
                    // CRC(A||B) = shift(CRC(A), len(B)) ^ CRC(B)
                    #pragma unroll
                    for (int offset = 1; offset < 32; offset *= 2) {
                        uint32_t right_crc = __shfl_down_sync(0xFFFFFFFF, my_crc, offset);
                        int right_bytes = __shfl_down_sync(0xFFFFFFFF, my_bytes, offset);
                        if ((lane_id & (2 * offset - 1)) == 0) {
                            if (crc_type == LDPC_CRC_24B_INTERNAL) {
                                my_crc = crc24b_shift_bytes(my_crc, right_bytes) ^ right_crc;
                            } else if (crc_type == LDPC_CRC_24A_INTERNAL) {
                                my_crc = crc24a_shift_bytes_ldpc(my_crc, right_bytes) ^ right_crc;
                            } else {
                                my_crc = crc16_shift_bytes_ldpc(my_crc, right_bytes) ^ right_crc;
                            }
                            my_bytes += right_bytes;
                        }
                    }

                    if (lane_id == 0) s_crc_result = my_crc & crc_mask;
                }
            }
            __syncthreads();

            if (s_crc_result == 0) {
                final_iter = iter + 1;
                if (tid == 0) {
                    s_final_iter = final_iter;
                }
                break;
            }
        }
    }

    __syncthreads();
    final_iter = s_final_iter;

    // Hard decision
    if ((Z & 31) == 0) {
        int lane_id = tid & 31;
        for (int col = 0; col < Kb; col++) {
            int flat_bit = col * Z + tid;
            int word_idx = flat_bit / 32;

            if (word_idx < output_stride) {
                int bit = __hlt(s_app[col * Z + tid], zero) ? 1 : 0;
                unsigned int ballot = __ballot_sync(0xFFFFFFFF, bit);
                if (lane_id == 0) {
                    ballot = ((ballot & 0xF0F0F0F0) >> 4) | ((ballot & 0x0F0F0F0F) << 4);
                    ballot = ((ballot & 0xCCCCCCCC) >> 2) | ((ballot & 0x33333333) << 2);
                    ballot = ((ballot & 0xAAAAAAAA) >> 1) | ((ballot & 0x55555555) << 1);
                    output[word_idx] = ballot;
                }
            }
        }
    } else {
        for (int col = 0; col < Kb; col++) {
            int flat_bit = col * Z + tid;
            int word_idx = flat_bit / 32;
            int bit_pos = msb_first_bit_pos(flat_bit);

            if (word_idx < output_stride) {
                int bit = __hlt(s_app[col * Z + tid], zero) ? 1 : 0;
                if (bit) atomicOr(&output[word_idx], 1u << bit_pos);
            }
        }
    }

    if (d_iterations != nullptr && tid == 0) {
        d_iterations[cb_idx] = final_iter;
    }

    if (d_crc_results != nullptr && tid == 0) {
        d_crc_results[cb_idx] = s_crc_result;
    }
}

__device__ __forceinline__ __half load_direct_rm_llr_bg1_z384(
    const __half* __restrict__ d_rate_matched_llrs,
    const int* __restrict__ d_rm_lengths,
    const unsigned int* __restrict__ d_rm_offsets,
    const unsigned int* __restrict__ d_scramble_seq,
    int scramble_offset,
    int cb_idx,
    int idx,
    int Q_m,
    int N_cb,
    int k0,
    int filler_start,
    int filler_count,
    __half zero,
    __half large,
    __half clamp)
{
    constexpr int Z = 384;
    constexpr int puncture_offset = 2 * Z;

    if (filler_count > 0 && idx >= filler_start && idx < filler_start + filler_count) {
        return large;
    }

    int cb_pos = idx - puncture_offset;
    if (cb_pos < 0 || cb_pos >= N_cb) {
        return zero;
    }

    int Kd_cb = filler_start - puncture_offset;
    if (filler_count > 0 && cb_pos >= Kd_cb && cb_pos < Kd_cb + filler_count) {
        return large;
    }

    int Ncb_eff = N_cb - filler_count;
    if (Ncb_eff <= 0) {
        return zero;
    }

    int k0_eff;
    if (k0 < Kd_cb) {
        k0_eff = k0;
    } else if (k0 >= Kd_cb + filler_count) {
        k0_eff = k0 - filler_count;
    } else {
        k0_eff = Kd_cb;
    }

    int eff_pos = (cb_pos < Kd_cb) ? cb_pos : (cb_pos - filler_count);
    int recv_idx = eff_pos - k0_eff;
    if (recv_idx < 0) {
        recv_idx += Ncb_eff;
    }

    int E = d_rm_lengths[cb_idx];
    if (recv_idx >= E) {
        return zero;
    }

    int K = (Q_m > 1) ? (E / Q_m) : E;
    int src_pos;
    if (Q_m > 1) {
        int j = recv_idx / K;
        int i = recv_idx - j * K;
        src_pos = i * Q_m + j;
    } else {
        src_pos = recv_idx;
    }

    unsigned int cb_offset = d_rm_offsets[cb_idx];
    __half llr = d_rate_matched_llrs[cb_offset + src_pos];

    if (d_scramble_seq != nullptr) {
        int global_pos = scramble_offset + static_cast<int>(cb_offset) + src_pos;
        int word_idx = global_pos >> 5;
        int bit_pos = 31 - (global_pos & 31);
        uint32_t seq_bit = (d_scramble_seq[word_idx] >> bit_pos) & 1u;
        if (seq_bit) {
            llr = __ushort_as_half(__half_as_ushort(llr) ^ 0x8000u);
        }
    }

    return clamp_half(llr, clamp);
}

__device__ __forceinline__ uint32_t reverse_bits_within_bytes_u32(uint32_t v)
{
    v = ((v & 0xF0F0F0F0u) >> 4) | ((v & 0x0F0F0F0Fu) << 4);
    v = ((v & 0xCCCCCCCCu) >> 2) | ((v & 0x33333333u) << 2);
    v = ((v & 0xAAAAAAAAu) >> 1) | ((v & 0x55555555u) << 1);
    return v;
}

// BG1/Z384 direct-rate-match 1-CB compressed-C2V kernel.
// Fuses APP initialization with no-repetition deinterleave/descramble/rate-dematch.
template<bool OFFSET_ZERO = true>
__global__ void __launch_bounds__(384, 2)
ldpc_decode_boxplus_bg1_z384_direct_kernel(
    const __half* __restrict__ d_rate_matched_llrs,
    __half* __restrict__ d_app,
    __half* __restrict__ d_c2v,
    uint32_t* __restrict__ d_output,
    int output_stride,
    int max_iterations,
    __half scale,
    __half offset,
    __half clamp,
    int num_cbs,
    int Q_m,
    int N_cb,
    int k0,
    const int* __restrict__ d_rm_lengths,
    const unsigned int* __restrict__ d_rm_offsets,
    const unsigned int* __restrict__ d_scramble_seq,
    int scramble_offset,
    int* __restrict__ d_iterations,
    bool crc_early_termination,
    int crc_check_bits,
    int crc_type,
    int* __restrict__ d_crc_results,
    int filler_start,
    int filler_count,
    int app_cache_cols)
{
    constexpr int Z = 384;
    constexpr int N = BG1_N;
    constexpr int M = BG1_M;
    constexpr int Kb = BG1_KB;

    __shared__ int s_final_iter;
    __shared__ uint32_t s_crc_result;

    extern __shared__ char s_dynamic[];
    int shmem_cols = app_cache_cols;
    if (shmem_cols < Kb) shmem_cols = Kb;
    if (shmem_cols > N) shmem_cols = N;
    __half* s_app = reinterpret_cast<__half*>(s_dynamic);

    int cb_idx = blockIdx.x;
    if (cb_idx >= num_cbs) return;

    int tid = threadIdx.x;
    if (tid >= Z) return;

    c2v_compressed_half* c2v_comp = reinterpret_cast<c2v_compressed_half*>(d_c2v) + cb_idx * M * Z;
    uint32_t* output = d_output + cb_idx * output_stride;
    __half* app_global = d_app + cb_idx * N * Z;

    __half zero = __float2half(0.0f);
    __half large = __float2half(1e4f);

    for (int col = 0; col < N; col++) {
        int idx = col * Z + tid;
        __half llr = load_direct_rm_llr_bg1_z384(d_rate_matched_llrs,
                                                 d_rm_lengths,
                                                 d_rm_offsets,
                                                 d_scramble_seq,
                                                 scramble_offset,
                                                 cb_idx,
                                                 idx,
                                                 Q_m,
                                                 N_cb,
                                                 k0,
                                                 filler_start,
                                                 filler_count,
                                                 zero,
                                                 large,
                                                 clamp);

        if (col < shmem_cols) {
            s_app[idx] = llr;
        } else {
            app_global[idx] = llr;
        }
    }

    __syncthreads();

    if (tid == 0) {
        s_final_iter = max_iterations;
    }

    constexpr int BP_MAX_DEG = BG1_MAX_DEG;
    uint16_t v2c_cache_raw[BP_MAX_DEG];

    int final_iter = max_iterations;
    for (int iter = 0; iter < max_iterations; iter++) {
        for (int row = 0; row < M; row++) {
            int row_start = d_bg1_row_ptr[row];
            int row_end = d_bg1_row_ptr[row + 1];
            int degree = row_end - row_start;

            c2v_compressed_half old_summary;
            if (iter > 0) {
                old_summary = c2v_comp[row * Z + tid];
            }

            __half v2c_min1_abs = __float2half(65504.0f);
            __half v2c_min2_abs = __float2half(65504.0f);
            int v2c_min1_idx = 0;
            uint32_t v2c_sign_bits = 0;

            #pragma unroll 8
            for (int e = 0; e < degree; e++) {
                int col = d_bg1_col[row_start + e];
                int shift = d_bg1_shifts_z384[row_start + e];
                int shifted_z = tid + shift;
                if (shifted_z >= Z) shifted_z -= Z;
                int llr_pos = col * Z + shifted_z;

                __half app_val = (col < shmem_cols) ? s_app[llr_pos] : app_global[llr_pos];
                __half v2c_val;
                if (iter == 0) {
                    v2c_val = app_val;
                } else {
                    uint32_t old_meta = old_summary.meta;
                    uint32_t old_sign_bits = c2v_meta_sign_bits(old_meta);
                    int old_min1_idx = c2v_meta_min1_idx(old_meta);
                    int old_sign_parity = c2v_meta_sign_parity(old_meta);
                    __half old_mag = (e == old_min1_idx) ? old_summary.min2 : old_summary.min1;
                    int old_sign = old_sign_parity ^ ((old_sign_bits >> e) & 1);
                    uint16_t mag_raw = *reinterpret_cast<uint16_t*>(&old_mag);
                    uint16_t old_c2v_raw = old_sign ? (mag_raw | 0x8000) : mag_raw;
                    __half old_c2v = *reinterpret_cast<__half*>(&old_c2v_raw);
                    v2c_val = __hsub(app_val, old_c2v);
                }

                uint16_t raw = *reinterpret_cast<uint16_t*>(&v2c_val);
                v2c_cache_raw[e] = raw;
                v2c_sign_bits |= ((raw >> 15) << e);
                __half v2c_abs = __habs(v2c_val);
                if (__hlt(v2c_abs, v2c_min1_abs)) {
                    v2c_min2_abs = v2c_min1_abs;
                    v2c_min1_abs = v2c_abs;
                    v2c_min1_idx = e;
                } else if (__hlt(v2c_abs, v2c_min2_abs)) {
                    v2c_min2_abs = v2c_abs;
                }
            }
            if (__heq(v2c_min2_abs, __float2half(65504.0f))) v2c_min2_abs = v2c_min1_abs;
            int v2c_sign_parity = __popc(v2c_sign_bits) & 1;

            __half scaled_min1, scaled_min2;
            if constexpr (OFFSET_ZERO) {
                scaled_min1 = __hmul(scale, v2c_min1_abs);
                scaled_min2 = __hmul(scale, v2c_min2_abs);
            } else {
                scaled_min1 = __hmax(__hsub(__hmul(scale, v2c_min1_abs), offset), zero);
                scaled_min2 = __hmax(__hsub(__hmul(scale, v2c_min2_abs), offset), zero);
                scaled_min1 = __hmin(scaled_min1, clamp);
                scaled_min2 = __hmin(scaled_min2, clamp);
            }

            c2v_compressed_half new_summary;
            new_summary.min1 = scaled_min1;
            new_summary.min2 = scaled_min2;
            new_summary.meta = c2v_pack_meta(v2c_sign_bits, v2c_min1_idx, v2c_sign_parity);
            c2v_comp[row * Z + tid] = new_summary;

            #pragma unroll 8
            for (int e = 0; e < degree; e++) {
                int col = d_bg1_col[row_start + e];
                int shift = d_bg1_shifts_z384[row_start + e];
                int shifted_z = tid + shift;
                if (shifted_z >= Z) shifted_z -= Z;
                int app_idx = col * Z + shifted_z;

                __half v2c_val = *reinterpret_cast<__half*>(&v2c_cache_raw[e]);
                __half new_c2v;
                if (degree == 1) {
                    new_c2v = zero;
                } else {
                    __half mag = (e == v2c_min1_idx) ? scaled_min2 : scaled_min1;
                    int result_sign = v2c_sign_parity ^ ((v2c_sign_bits >> e) & 1);
                    uint16_t mag_raw = *reinterpret_cast<uint16_t*>(&mag);
                    uint16_t c2v_raw = result_sign ? (mag_raw | 0x8000) : mag_raw;
                    new_c2v = *reinterpret_cast<__half*>(&c2v_raw);
                }

                __half new_app = __hadd(v2c_val, new_c2v);
                if (col < shmem_cols) {
                    s_app[app_idx] = new_app;
                } else {
                    app_global[app_idx] = new_app;
                }
            }

            __threadfence_block();
            __syncthreads();
        }

        if (crc_early_termination && crc_type != LDPC_CRC_NONE_INTERNAL) {
            if (tid == 0) {
                s_crc_result = 0xFFFFFFFF;
            }
            __syncthreads();

            const int total_bits = (crc_check_bits > 0) ? crc_check_bits : (Kb * Z);
            uint32_t polynomial;
            uint32_t crc_highbit;
            uint32_t crc_mask;
            int crc_order;
            if (crc_type == LDPC_CRC_16_INTERNAL) {
                polynomial = 0x11021u;
                crc_highbit = 1u << 16;
                crc_mask = 0xFFFFu;
                crc_order = 16;
            } else if (crc_type == LDPC_CRC_24A_INTERNAL) {
                polynomial = 0x1864CFBu;
                crc_highbit = 1u << 24;
                crc_mask = 0xFFFFFFu;
                crc_order = 24;
            } else {
                polynomial = 0x1800063u;
                crc_highbit = 1u << 24;
                crc_mask = 0xFFFFFFu;
                crc_order = 24;
            }

            constexpr int WARP_CRC_THRESHOLD = 4096;
            if (total_bits < WARP_CRC_THRESHOLD) {
                if (tid == 0) {
                    uint32_t crc = 0;
                    int col = 0, row = 0;
                    for (int i = 0; i < total_bits; i++) {
                        uint32_t bit = __hlt(s_app[col * Z + row], zero) ? 1u : 0u;
                        crc = (crc << 1) | bit;
                        if (crc & crc_highbit) crc ^= polynomial;
                        if (++row >= Z) { row = 0; col++; }
                    }
                    s_crc_result = crc & crc_mask;
                }
            } else {
                if (tid < 32) {
                    const int lane_id = tid;
                    int bits_per_lane = ((total_bits + 31) / 32 + 7) & ~7;
                    int my_start = lane_id * bits_per_lane;
                    int my_end = min(my_start + bits_per_lane, total_bits);
                    int my_bits = max(my_end - my_start, 0);
                    int my_bytes = (my_bits + 7) / 8;

                    uint32_t my_crc = 0;
                    int bit_pos = my_start;
                    int bits_left = my_bits;
                    while (bits_left >= 8) {
                        uint8_t byte_val = 0;
                        #pragma unroll
                        for (int b = 0; b < 8; b++) {
                            int col = bit_pos / Z;
                            int row = bit_pos % Z;
                            uint32_t bit = __hlt(s_app[col * Z + row], zero) ? 1u : 0u;
                            byte_val = (byte_val << 1) | bit;
                            bit_pos++;
                        }
                        if (crc_type == LDPC_CRC_24B_INTERNAL) {
                            my_crc = (my_crc << 8) ^ d_crc24b_table_ldpc[((my_crc >> 16) ^ byte_val) & 0xFF];
                        } else if (crc_type == LDPC_CRC_24A_INTERNAL) {
                            my_crc = (my_crc << 8) ^ d_crc24a_table_ldpc[((my_crc >> 16) ^ byte_val) & 0xFF];
                        } else {
                            my_crc = (my_crc << 8) ^ d_crc16_table_ldpc[((my_crc >> 8) ^ byte_val) & 0xFF];
                        }
                        bits_left -= 8;
                    }
                    while (bits_left > 0) {
                        int col = bit_pos / Z;
                        int row = bit_pos % Z;
                        uint32_t bit = __hlt(s_app[col * Z + row], zero) ? 1u : 0u;
                        my_crc = (my_crc << 1) | bit;
                        if (my_crc & crc_highbit) my_crc ^= polynomial;
                        bit_pos++;
                        bits_left--;
                    }
                    my_crc &= crc_mask;

                    #pragma unroll
                    for (int offset_lane = 1; offset_lane < 32; offset_lane *= 2) {
                        uint32_t right_crc = __shfl_down_sync(0xFFFFFFFF, my_crc, offset_lane);
                        int right_bytes = __shfl_down_sync(0xFFFFFFFF, my_bytes, offset_lane);
                        if ((lane_id & (2 * offset_lane - 1)) == 0) {
                            if (crc_type == LDPC_CRC_24B_INTERNAL) {
                                my_crc = crc24b_shift_bytes(my_crc, right_bytes) ^ right_crc;
                            } else if (crc_type == LDPC_CRC_24A_INTERNAL) {
                                my_crc = crc24a_shift_bytes_ldpc(my_crc, right_bytes) ^ right_crc;
                            } else {
                                my_crc = crc16_shift_bytes_ldpc(my_crc, right_bytes) ^ right_crc;
                            }
                            my_bytes += right_bytes;
                        }
                    }

                    if (lane_id == 0) s_crc_result = my_crc & crc_mask;
                }
            }
            __syncthreads();

            if (s_crc_result == 0) {
                final_iter = iter + 1;
                if (tid == 0) {
                    s_final_iter = final_iter;
                }
                break;
            }
        }
    }

    __syncthreads();
    final_iter = s_final_iter;

    int lane_id = tid & 31;
    for (int col = 0; col < Kb; col++) {
        int flat_bit = col * Z + tid;
        int word_idx = flat_bit / 32;
        if (word_idx < output_stride) {
            int bit = __hlt(s_app[col * Z + tid], zero) ? 1 : 0;
            unsigned int ballot = __ballot_sync(0xFFFFFFFF, bit);
            if (lane_id == 0) {
                output[word_idx] = reverse_bits_within_bytes_u32(ballot);
            }
        }
    }

    if (d_iterations != nullptr && tid == 0) {
        d_iterations[cb_idx] = final_iter;
    }

    if (d_crc_results != nullptr && tid == 0) {
        d_crc_results[cb_idx] = s_crc_result;
    }
}

// ============================================================================
// BOX-PLUS 2-CB compressed-C2V kernel.
// Stores one min-sum summary per row/Z lane/CB instead of per-edge C2V values.
// ============================================================================

template<int BG, bool FULL_SHMEM = true, bool OFFSET_ZERO = true>
__global__ void __launch_bounds__(384, 2)
ldpc_decode_boxplus_half2_compressed_kernel(
    const __half* __restrict__ d_channel_llrs,
    __half* __restrict__ d_app,
    __half* __restrict__ d_c2v,
    uint32_t* __restrict__ d_output,
    const int16_t* __restrict__ d_scaled_shifts,
    int Z,
    int N,
    int M,
    int Kb,
    int nnz,
    int max_deg,
    int llr_stride,
    int output_stride,
    int max_iterations,
    __half scale,
    __half offset,
    __half clamp,
    int num_cbs,
    int* __restrict__ d_iterations = nullptr,
    int syndrome_tolerance = 0,
    bool crc_early_termination = true,
    __half confidence_threshold = __float2half(0.25f),
    int crc_check_bits = 0,
    int crc_type = 3,
    int* __restrict__ d_crc_results = nullptr,
    int filler_start = 0,
    int filler_count = 0
) {
    __shared__ uint32_t s_crc_result[2];
    __shared__ int s_final_iter;

    extern __shared__ char s_dynamic[];
    const int shmem_cols = FULL_SHMEM ? N : Kb;
    __half* s_app_0 = reinterpret_cast<__half*>(s_dynamic);
    __half* s_app_1 = reinterpret_cast<__half*>(s_dynamic + shmem_cols * Z * sizeof(__half));

    const int16_t* row_ptr = (BG == 1) ? d_bg1_row_ptr : d_bg2_row_ptr;
    const int8_t* col_idx = (BG == 1) ? d_bg1_col : d_bg2_col;
    const int16_t* shifts = d_scaled_shifts;

    int cb_pair_idx = blockIdx.x;
    int cb0_idx = cb_pair_idx * 2;
    int cb1_idx = cb_pair_idx * 2 + 1;

    bool cb0_valid = (cb0_idx < num_cbs);
    bool cb1_valid = (cb1_idx < num_cbs);
    if (!cb0_valid) return;

    int tid = threadIdx.x;
    if (tid >= Z) return;

    const __half* channel0 = d_channel_llrs + cb0_idx * llr_stride;
    const __half* channel1 = cb1_valid ? (d_channel_llrs + cb1_idx * llr_stride) : channel0;
    __half* app0 = d_app + cb0_idx * N * Z;
    __half* app1 = cb1_valid ? (d_app + cb1_idx * N * Z) : app0;
    c2v_compressed_half* c2v0 = reinterpret_cast<c2v_compressed_half*>(d_c2v) + cb0_idx * M * Z;
    c2v_compressed_half* c2v1 = cb1_valid ? (reinterpret_cast<c2v_compressed_half*>(d_c2v) + cb1_idx * M * Z) : c2v0;
    uint32_t* output0 = d_output + cb0_idx * output_stride;
    uint32_t* output1 = cb1_valid ? (d_output + cb1_idx * output_stride) : output0;

    const __half zero = __float2half(0.0f);
    const __half large = __float2half(1e4f);
    const __half2 scale2 = __halves2half2(scale, scale);
    const __half2 offset2 = __halves2half2(offset, offset);
    const __half2 zero2 = __float2half2_rn(0.0f);
    const __half2 clamp2 = __halves2half2(clamp, clamp);

    for (int col = 0; col < N; col++) {
        int idx = col * Z + tid;
        __half llr0 = (idx < llr_stride) ? clamp_half(__ldg(&channel0[idx]), clamp) : zero;
        __half llr1 = cb1_valid ? ((idx < llr_stride) ? clamp_half(__ldg(&channel1[idx]), clamp) : zero) : zero;

        if (filler_count > 0 && idx >= filler_start && idx < filler_start + filler_count) {
            llr0 = large;
            llr1 = large;
        }

        if (FULL_SHMEM) {
            s_app_0[idx] = llr0;
            if (cb1_valid) s_app_1[idx] = llr1;
        } else {
            app0[idx] = llr0;
            if (cb1_valid) app1[idx] = llr1;
            if (col < Kb) {
                s_app_0[idx] = llr0;
                if (cb1_valid) s_app_1[idx] = llr1;
            }
        }
    }

    __syncthreads();

    if (tid == 0) {
        s_final_iter = max_iterations;
    }

    if ((Z & 31) != 0) {
        for (int col = 0; col < Kb; col++) {
            int flat_bit = col * Z + tid;
            int word_idx = flat_bit / 32;
            if ((word_idx < output_stride) && ((flat_bit & 31) == 0)) {
                output0[word_idx] = 0;
                if (cb1_valid) output1[word_idx] = 0;
            }
        }
        __syncthreads();
    }

    constexpr int BP_MAX_DEG = (BG == 1) ? 19 : 10;
    uint32_t v2c_cache[BP_MAX_DEG];

    int final_iter = max_iterations;
    for (int iter = 0; iter < max_iterations; iter++) {
        for (int row = 0; row < M; row++) {
            int row_start = row_ptr[row];
            int row_end = row_ptr[row + 1];
            int degree = row_end - row_start;

            c2v_compressed_half old_summary0;
            c2v_compressed_half old_summary1;
            if (iter > 0) {
                old_summary0 = c2v0[row * Z + tid];
                if (cb1_valid) old_summary1 = c2v1[row * Z + tid];
            }

            __half v2c_min1_abs0 = __float2half(65504.0f);
            __half v2c_min2_abs0 = __float2half(65504.0f);
            __half v2c_min1_abs1 = __float2half(65504.0f);
            __half v2c_min2_abs1 = __float2half(65504.0f);
            int v2c_min1_idx0 = 0;
            int v2c_min1_idx1 = 0;
            uint32_t v2c_sign_bits0 = 0;
            uint32_t v2c_sign_bits1 = 0;

            #pragma unroll 8
            for (int e = 0; e < degree; e++) {
                int col = col_idx[row_start + e];
                int shift = shifts[row_start + e];
                int shifted_z = tid + shift;
                if (shifted_z >= Z) shifted_z -= Z;

                int llr_pos = col * Z + shifted_z;
                __half app_val0;
                __half app_val1;
                if (FULL_SHMEM) {
                    app_val0 = s_app_0[llr_pos];
                    app_val1 = cb1_valid ? s_app_1[llr_pos] : zero;
                } else {
                    app_val0 = (col < Kb) ? s_app_0[llr_pos] : app0[llr_pos];
                    app_val1 = cb1_valid ? ((col < Kb) ? s_app_1[llr_pos] : app1[llr_pos]) : zero;
                }

                __half v2c_val0;
                __half v2c_val1 = zero;
                if (iter == 0) {
                    v2c_val0 = app_val0;
                    if (cb1_valid) v2c_val1 = app_val1;
                } else {
                    uint32_t old_meta0 = old_summary0.meta;
                    uint32_t old_sign_bits0 = c2v_meta_sign_bits(old_meta0);
                    int old_min1_idx0 = c2v_meta_min1_idx(old_meta0);
                    int old_sign_parity0 = c2v_meta_sign_parity(old_meta0);
                    __half old_mag0 = (e == old_min1_idx0) ? old_summary0.min2 : old_summary0.min1;
                    int old_sign0 = old_sign_parity0 ^ ((old_sign_bits0 >> e) & 1);
                    uint16_t mag_raw0 = *reinterpret_cast<uint16_t*>(&old_mag0);
                    uint16_t old_c2v_raw0 = old_sign0 ? (mag_raw0 | 0x8000) : mag_raw0;
                    __half old_c2v0 = *reinterpret_cast<__half*>(&old_c2v_raw0);
                    v2c_val0 = __hsub(app_val0, old_c2v0);

                    if (cb1_valid) {
                        uint32_t old_meta1 = old_summary1.meta;
                        uint32_t old_sign_bits1 = c2v_meta_sign_bits(old_meta1);
                        int old_min1_idx1 = c2v_meta_min1_idx(old_meta1);
                        int old_sign_parity1 = c2v_meta_sign_parity(old_meta1);
                        __half old_mag1 = (e == old_min1_idx1) ? old_summary1.min2 : old_summary1.min1;
                        int old_sign1 = old_sign_parity1 ^ ((old_sign_bits1 >> e) & 1);
                        uint16_t mag_raw1 = *reinterpret_cast<uint16_t*>(&old_mag1);
                        uint16_t old_c2v_raw1 = old_sign1 ? (mag_raw1 | 0x8000) : mag_raw1;
                        __half old_c2v1 = *reinterpret_cast<__half*>(&old_c2v_raw1);
                        v2c_val1 = __hsub(app_val1, old_c2v1);
                    }
                }

                uint16_t raw0 = *reinterpret_cast<uint16_t*>(&v2c_val0);
                uint16_t raw1 = cb1_valid ? *reinterpret_cast<uint16_t*>(&v2c_val1) : 0;
                v2c_cache[e] = static_cast<uint32_t>(raw0) | (static_cast<uint32_t>(raw1) << 16);

                v2c_sign_bits0 |= ((raw0 >> 15) << e);
                __half v2c_abs0 = __habs(v2c_val0);
                if (__hlt(v2c_abs0, v2c_min1_abs0)) {
                    v2c_min2_abs0 = v2c_min1_abs0;
                    v2c_min1_abs0 = v2c_abs0;
                    v2c_min1_idx0 = e;
                } else if (__hlt(v2c_abs0, v2c_min2_abs0)) {
                    v2c_min2_abs0 = v2c_abs0;
                }

                if (cb1_valid) {
                    v2c_sign_bits1 |= ((raw1 >> 15) << e);
                    __half v2c_abs1 = __habs(v2c_val1);
                    if (__hlt(v2c_abs1, v2c_min1_abs1)) {
                        v2c_min2_abs1 = v2c_min1_abs1;
                        v2c_min1_abs1 = v2c_abs1;
                        v2c_min1_idx1 = e;
                    } else if (__hlt(v2c_abs1, v2c_min2_abs1)) {
                        v2c_min2_abs1 = v2c_abs1;
                    }
                }
            }
            if (__heq(v2c_min2_abs0, __float2half(65504.0f))) v2c_min2_abs0 = v2c_min1_abs0;
            if (cb1_valid && __heq(v2c_min2_abs1, __float2half(65504.0f))) v2c_min2_abs1 = v2c_min1_abs1;

            int v2c_sign_parity0 = __popc(v2c_sign_bits0) & 1;
            int v2c_sign_parity1 = __popc(v2c_sign_bits1) & 1;

            __half2 min1_pair = __halves2half2(v2c_min1_abs0, v2c_min1_abs1);
            __half2 min2_pair = __halves2half2(v2c_min2_abs0, v2c_min2_abs1);
            __half2 scaled_min1_pair;
            __half2 scaled_min2_pair;
            if constexpr (OFFSET_ZERO) {
                scaled_min1_pair = __hmul2(scale2, min1_pair);
                scaled_min2_pair = __hmul2(scale2, min2_pair);
            } else {
                scaled_min1_pair = __hmin2(__hmax2(__hsub2(__hmul2(scale2, min1_pair), offset2), zero2), clamp2);
                scaled_min2_pair = __hmin2(__hmax2(__hsub2(__hmul2(scale2, min2_pair), offset2), zero2), clamp2);
            }
            __half scaled_min10 = __low2half(scaled_min1_pair);
            __half scaled_min20 = __low2half(scaled_min2_pair);
            __half scaled_min11 = __high2half(scaled_min1_pair);
            __half scaled_min21 = __high2half(scaled_min2_pair);

            c2v_compressed_half new_summary0;
            new_summary0.min1 = scaled_min10;
            new_summary0.min2 = scaled_min20;
            new_summary0.meta = c2v_pack_meta(v2c_sign_bits0, v2c_min1_idx0, v2c_sign_parity0);
            c2v0[row * Z + tid] = new_summary0;
            if (cb1_valid) {
                c2v_compressed_half new_summary1;
                new_summary1.min1 = scaled_min11;
                new_summary1.min2 = scaled_min21;
                new_summary1.meta = c2v_pack_meta(v2c_sign_bits1, v2c_min1_idx1, v2c_sign_parity1);
                c2v1[row * Z + tid] = new_summary1;
            }

            #pragma unroll 8
            for (int e = 0; e < degree; e++) {
                int col = col_idx[row_start + e];
                int shift = shifts[row_start + e];
                int shifted_z = tid + shift;
                if (shifted_z >= Z) shifted_z -= Z;
                int app_idx = col * Z + shifted_z;

                uint32_t packed_raw = v2c_cache[e];
                uint16_t raw0 = static_cast<uint16_t>(packed_raw & 0xffffu);
                uint16_t raw1 = static_cast<uint16_t>(packed_raw >> 16);
                __half v2c_val0 = *reinterpret_cast<__half*>(&raw0);
                __half v2c_val1 = *reinterpret_cast<__half*>(&raw1);

                __half new_c2v0;
                __half new_c2v1 = zero;
                if (degree == 1) {
                    new_c2v0 = zero;
                    new_c2v1 = zero;
                } else {
                    __half mag0 = (e == v2c_min1_idx0) ? scaled_min20 : scaled_min10;
                    int result_sign0 = v2c_sign_parity0 ^ ((v2c_sign_bits0 >> e) & 1);
                    uint16_t mag_raw0 = *reinterpret_cast<uint16_t*>(&mag0);
                    uint16_t c2v_raw0 = result_sign0 ? (mag_raw0 | 0x8000) : mag_raw0;
                    new_c2v0 = *reinterpret_cast<__half*>(&c2v_raw0);

                    if (cb1_valid) {
                        __half mag1 = (e == v2c_min1_idx1) ? scaled_min21 : scaled_min11;
                        int result_sign1 = v2c_sign_parity1 ^ ((v2c_sign_bits1 >> e) & 1);
                        uint16_t mag_raw1 = *reinterpret_cast<uint16_t*>(&mag1);
                        uint16_t c2v_raw1 = result_sign1 ? (mag_raw1 | 0x8000) : mag_raw1;
                        new_c2v1 = *reinterpret_cast<__half*>(&c2v_raw1);
                    }
                }

                __half new_app0 = __hadd(v2c_val0, new_c2v0);
                __half new_app1 = cb1_valid ? __hadd(v2c_val1, new_c2v1) : zero;

                if (FULL_SHMEM) {
                    s_app_0[app_idx] = new_app0;
                    if (cb1_valid) s_app_1[app_idx] = new_app1;
                } else {
                    if (col < Kb) {
                        s_app_0[app_idx] = new_app0;
                        if (cb1_valid) s_app_1[app_idx] = new_app1;
                    }
                    app0[app_idx] = new_app0;
                    if (cb1_valid) app1[app_idx] = new_app1;
                }
            }
            if (!FULL_SHMEM) __threadfence_block();
            __syncthreads();
        }

        if (crc_early_termination && crc_type != LDPC_CRC_NONE_INTERNAL) {
            if (tid == 0) {
                s_crc_result[0] = 0xFFFFFFFF;
                s_crc_result[1] = 0xFFFFFFFF;
            }
            __syncthreads();

            const int total_bits = (crc_check_bits > 0) ? crc_check_bits : (Kb * Z);

            uint32_t polynomial;
            uint32_t crc_highbit;
            uint32_t crc_mask;
            int crc_order;
            if (crc_type == LDPC_CRC_16_INTERNAL) {
                polynomial = 0x11021u;
                crc_highbit = 1u << 16;
                crc_mask = 0xFFFFu;
                crc_order = 16;
            } else if (crc_type == LDPC_CRC_24A_INTERNAL) {
                polynomial = 0x1864CFBu;
                crc_highbit = 1u << 24;
                crc_mask = 0xFFFFFFu;
                crc_order = 24;
            } else {
                polynomial = 0x1800063u;
                crc_highbit = 1u << 24;
                crc_mask = 0xFFFFFFu;
                crc_order = 24;
            }

            constexpr int WARP_CRC_THRESHOLD = 4096;

            if (total_bits < WARP_CRC_THRESHOLD) {
                if (tid == 0 || (tid == 1 && cb1_valid)) {
                    const __half* s_app = (tid == 0) ? s_app_0 : s_app_1;
                    uint32_t crc = 0;
                    int col = 0, row = 0;
                    for (int i = 0; i < total_bits; i++) {
                        uint32_t bit = __hlt(s_app[col * Z + row], zero) ? 1u : 0u;
                        crc = (crc << 1) | bit;
                        if (crc & crc_highbit) crc ^= polynomial;
                        if (++row >= Z) { row = 0; col++; }
                    }
                    s_crc_result[tid] = crc & crc_mask;
                }
            } else {
                if (tid < 32) {
                    const int lane_id = tid;
                    uint32_t crc0 = 0, crc1 = 0;
                    const int total_rounds = (total_bits + 31) / 32;

                    for (int round = 0; round < total_rounds; round++) {
                        int my_bit = round * 32 + lane_id;
                        bool sign0 = false, sign1 = false;
                        if (my_bit < total_bits) {
                            int col = my_bit / Z;
                            int row = my_bit % Z;
                            sign0 = __hlt(s_app_0[col * Z + row], zero);
                            if (cb1_valid) sign1 = __hlt(s_app_1[col * Z + row], zero);
                        }
                        uint32_t ballot0 = __ballot_sync(0xFFFFFFFF, sign0);
                        uint32_t ballot1 = cb1_valid ? __ballot_sync(0xFFFFFFFF, sign1) : 0;

                        uint32_t word0 = __brev(ballot0);
                        uint32_t word1 = __brev(ballot1);
                        int bits_this_round = min(32, total_bits - round * 32);

                        if (lane_id == 0) {
                            int full_bytes = bits_this_round / 8;
                            int remaining = bits_this_round % 8;
                            for (int b = 0; b < full_bytes; b++) {
                                uint8_t byte_val = (word0 >> (24 - b * 8)) & 0xFF;
                                if (crc_order == 16) {
                                    crc0 = (crc0 << 8) ^ d_crc16_table_ldpc[((crc0 >> 8) ^ byte_val) & 0xFF];
                                } else if (crc_type == LDPC_CRC_24A_INTERNAL) {
                                    crc0 = (crc0 << 8) ^ d_crc24a_table_ldpc[((crc0 >> 16) ^ byte_val) & 0xFF];
                                } else {
                                    crc0 = (crc0 << 8) ^ d_crc24b_table_ldpc[((crc0 >> 16) ^ byte_val) & 0xFF];
                                }
                            }
                            if (remaining > 0) {
                                int shift = 24 - full_bytes * 8;
                                for (int r = 0; r < remaining; r++) {
                                    uint32_t bit = (word0 >> (shift + 7 - r)) & 1u;
                                    crc0 = (crc0 << 1) | bit;
                                    if (crc0 & crc_highbit) crc0 ^= polynomial;
                                }
                            }
                        }
                        if (lane_id == 1 && cb1_valid) {
                            int full_bytes = bits_this_round / 8;
                            int remaining = bits_this_round % 8;
                            for (int b = 0; b < full_bytes; b++) {
                                uint8_t byte_val = (word1 >> (24 - b * 8)) & 0xFF;
                                if (crc_order == 16) {
                                    crc1 = (crc1 << 8) ^ d_crc16_table_ldpc[((crc1 >> 8) ^ byte_val) & 0xFF];
                                } else if (crc_type == LDPC_CRC_24A_INTERNAL) {
                                    crc1 = (crc1 << 8) ^ d_crc24a_table_ldpc[((crc1 >> 16) ^ byte_val) & 0xFF];
                                } else {
                                    crc1 = (crc1 << 8) ^ d_crc24b_table_ldpc[((crc1 >> 16) ^ byte_val) & 0xFF];
                                }
                            }
                            if (remaining > 0) {
                                int shift = 24 - full_bytes * 8;
                                for (int r = 0; r < remaining; r++) {
                                    uint32_t bit = (word1 >> (shift + 7 - r)) & 1u;
                                    crc1 = (crc1 << 1) | bit;
                                    if (crc1 & crc_highbit) crc1 ^= polynomial;
                                }
                            }
                        }
                    }
                    if (lane_id == 0) s_crc_result[0] = crc0 & crc_mask;
                    if (lane_id == 1 && cb1_valid) s_crc_result[1] = crc1 & crc_mask;
                }
            }
            __syncthreads();

            bool cb0_converged = (s_crc_result[0] == 0);
            bool cb1_converged = !cb1_valid || (s_crc_result[1] == 0);

            if (cb0_converged && cb1_converged) {
                final_iter = iter + 1;
                if (tid == 0) {
                    s_final_iter = final_iter;
                }
                break;
            }
        }
    }

    __syncthreads();
    final_iter = s_final_iter;

    if ((Z & 31) == 0) {
        int lane_id = tid & 31;
        for (int col = 0; col < Kb; col++) {
            int flat_bit = col * Z + tid;
            int word_idx = flat_bit / 32;

            if (word_idx < output_stride) {
                int bit0 = __hlt(s_app_0[col * Z + tid], zero) ? 1 : 0;
                unsigned int ballot0 = __ballot_sync(0xFFFFFFFF, bit0);
                if (lane_id == 0) {
                    ballot0 = ((ballot0 & 0xF0F0F0F0) >> 4) | ((ballot0 & 0x0F0F0F0F) << 4);
                    ballot0 = ((ballot0 & 0xCCCCCCCC) >> 2) | ((ballot0 & 0x33333333) << 2);
                    ballot0 = ((ballot0 & 0xAAAAAAAA) >> 1) | ((ballot0 & 0x55555555) << 1);
                    output0[word_idx] = ballot0;
                }

                if (cb1_valid) {
                    int bit1 = __hlt(s_app_1[col * Z + tid], zero) ? 1 : 0;
                    unsigned int ballot1 = __ballot_sync(0xFFFFFFFF, bit1);
                    if (lane_id == 0) {
                        ballot1 = ((ballot1 & 0xF0F0F0F0) >> 4) | ((ballot1 & 0x0F0F0F0F) << 4);
                        ballot1 = ((ballot1 & 0xCCCCCCCC) >> 2) | ((ballot1 & 0x33333333) << 2);
                        ballot1 = ((ballot1 & 0xAAAAAAAA) >> 1) | ((ballot1 & 0x55555555) << 1);
                        output1[word_idx] = ballot1;
                    }
                }
            }
        }
    } else {
        for (int col = 0; col < Kb; col++) {
            int flat_bit = col * Z + tid;
            int word_idx = flat_bit / 32;
            int bit_pos = msb_first_bit_pos(flat_bit);

            if (word_idx < output_stride) {
                int bit0 = __hlt(s_app_0[col * Z + tid], zero) ? 1 : 0;
                if (bit0) atomicOr(&output0[word_idx], 1u << bit_pos);

                if (cb1_valid) {
                    int bit1 = __hlt(s_app_1[col * Z + tid], zero) ? 1 : 0;
                    if (bit1) atomicOr(&output1[word_idx], 1u << bit_pos);
                }
            }
        }
    }

    if (d_iterations != nullptr && tid == 0) {
        d_iterations[cb0_idx] = final_iter;
        if (cb1_valid) {
            d_iterations[cb1_idx] = final_iter;
        }
    }

    if (d_crc_results != nullptr && tid == 0) {
        d_crc_results[cb0_idx] = s_crc_result[0];
        if (cb1_valid) {
            d_crc_results[cb1_idx] = s_crc_result[1];
        }
    }
}

// ============================================================================
// BOX-PLUS 2-CB Kernel: min.xorsign.abs check-node update for 2 codewords per block
// Packs both CBs into half2 for 2x throughput via vectorized box_plus_half2().
// ============================================================================

template<int BG, bool FULL_SHMEM = true>
__global__ void __launch_bounds__(384, 2)
ldpc_decode_boxplus_half2_kernel(
    const __half* __restrict__ d_channel_llrs,
    __half* __restrict__ d_app,
    __half* __restrict__ d_c2v,
    uint32_t* __restrict__ d_output,
    const int16_t* __restrict__ d_scaled_shifts,
    int Z,
    int N,
    int M,
    int Kb,
    int nnz,
    int max_deg,
    int llr_stride,
    int output_stride,
    int max_iterations,
    __half scale,
    __half offset,
    __half clamp,
    int num_cbs,
    int* __restrict__ d_iterations = nullptr,
    int syndrome_tolerance = 0,
    bool crc_early_termination = true,
    __half confidence_threshold = __float2half(0.25f),
    int crc_check_bits = 0,
    int crc_type = 3,  // CRC type: 0=none, 1=CRC16, 2=CRC24A, 3=CRC24B (LDPC_CRC_24B_INTERNAL)
    int* __restrict__ d_crc_results = nullptr,
    int filler_start = 0,  // Start position of filler bits in buffer (= num_info_bits = K)
    int filler_count = 0   // Number of filler bits (= F = Kb*Z - K). 0 = no filler
) {
    // Shared memory for CRC early termination
    __shared__ uint32_t s_crc_result[2];
    __shared__ int s_final_iter;

    // Dynamic shared memory for APP values.
    // FULL_SHMEM=true:  ALL columns (N * Z) — no global APP access during iteration
    // FULL_SHMEM=false: Info columns only (Kb * Z) — parity columns use global d_app
    extern __shared__ char s_dynamic[];
    const int shmem_cols = FULL_SHMEM ? N : Kb;
    __half* s_app_0 = reinterpret_cast<__half*>(s_dynamic);
    __half* s_app_1 = reinterpret_cast<__half*>(s_dynamic + shmem_cols * Z * sizeof(__half));

    const int16_t* row_ptr = (BG == 1) ? d_bg1_row_ptr : d_bg2_row_ptr;
    const int8_t* col_idx = (BG == 1) ? d_bg1_col : d_bg2_col;
    const int16_t* shifts = d_scaled_shifts;

    // Each block processes 2 codewords (packed as half2)
    int cb_pair_idx = blockIdx.x;
    int cb0_idx = cb_pair_idx * 2;
    int cb1_idx = cb_pair_idx * 2 + 1;

    bool cb0_valid = (cb0_idx < num_cbs);
    bool cb1_valid = (cb1_idx < num_cbs);
    if (!cb0_valid) return;

    int tid = threadIdx.x;
    if (tid >= Z) return;

    // Pointers for both codewords
    const __half* channel0 = d_channel_llrs + cb0_idx * llr_stride;
    const __half* channel1 = cb1_valid ? (d_channel_llrs + cb1_idx * llr_stride) : channel0;
    __half* app0 = d_app + cb0_idx * N * Z;
    __half* app1 = cb1_valid ? (d_app + cb1_idx * N * Z) : app0;
    __half* c2v0 = d_c2v + cb0_idx * M * max_deg * Z;
    __half* c2v1 = cb1_valid ? (d_c2v + cb1_idx * M * max_deg * Z) : c2v0;
    uint32_t* output0 = d_output + cb0_idx * output_stride;
    uint32_t* output1 = cb1_valid ? (d_output + cb1_idx * output_stride) : output0;

    // Constants
    const __half zero = __float2half(0.0f);
    const __half large = __float2half(1e4f);
    const __half2 scale2 = __halves2half2(scale, scale);
    const __half2 offset2 = __halves2half2(offset, offset);
    const __half2 zero2 = __float2half2_rn(0.0f);
    const __half2 clamp2 = __halves2half2(clamp, clamp);

    // Initialize APP LLRs from channel
    // FULL_SHMEM=true:  all columns go to shared memory only
    // FULL_SHMEM=false: all columns go to global, info columns (col < Kb) also to shared
    for (int col = 0; col < N; col++) {
        int idx = col * Z + tid;
        __half llr0 = (idx < llr_stride) ? clamp_half(__ldg(&channel0[idx]), clamp) : zero;
        __half llr1 = cb1_valid ? ((idx < llr_stride) ? clamp_half(__ldg(&channel1[idx]), clamp) : zero) : zero;

        // Override filler bit positions with large LLR
        if (filler_count > 0 && idx >= filler_start && idx < filler_start + filler_count) {
            llr0 = large;
            llr1 = large;
        }

        if (FULL_SHMEM) {
            s_app_0[idx] = llr0;
            if (cb1_valid) s_app_1[idx] = llr1;
        } else {
            app0[idx] = llr0;
            if (cb1_valid) app1[idx] = llr1;
            if (col < Kb) {
                s_app_0[idx] = llr0;
                if (cb1_valid) s_app_1[idx] = llr1;
            }
        }
    }

    // Sync to ensure all threads see shared memory APP initialization
    __syncthreads();

    if (tid == 0) {
        s_final_iter = max_iterations;
    }

    // The ballot hard-decision path below overwrites every output word when Z
    // is word-aligned. Only clear for the atomicOr fallback, and clear each
    // word once instead of once per bit lane.
    if ((Z & 31) != 0) {
        for (int col = 0; col < Kb; col++) {
            int flat_bit = col * Z + tid;
            int word_idx = flat_bit / 32;
            if ((word_idx < output_stride) && ((flat_bit & 31) == 0)) {
                output0[word_idx] = 0;
                if (cb1_valid) output1[word_idx] = 0;
            }
        }
        __syncthreads();
    }

    // V2C cache (packed half2: CB0 in low, CB1 in high) and exclusion product
    constexpr int BP_MAX_DEG = (BG == 1) ? 19 : 10;
    uint32_t v2c_cache[BP_MAX_DEG];   // packed V2C as half2
    uint32_t excl_h2[BP_MAX_DEG];     // exclusion products from binary tree as half2
    int8_t cached_col[BP_MAX_DEG];        // Cached column indices from pass 1
    int16_t cached_shifted_z[BP_MAX_DEG]; // Cached shifted Z indices from pass 1

    // Layered box-plus (min.xorsign.abs) decoding iterations
    int final_iter = max_iterations;
    for (int iter = 0; iter < max_iterations; iter++) {

        for (int row = 0; row < M; row++) {
            int row_start = row_ptr[row];
            int row_end = row_ptr[row + 1];
            int degree = row_end - row_start;

            // PASS 1: Compute V2C, cache it, cache indices
            #pragma unroll 8
            for (int e = 0; e < degree; e++) {
                int col = col_idx[row_start + e];
                int shift = shifts[row_start + e];
                int shifted_z = tid + shift;
                if (shifted_z >= Z) shifted_z -= Z;
                cached_col[e] = (int8_t)col;
                cached_shifted_z[e] = (int16_t)shifted_z;

                int c2v_idx = (row * max_deg + e) * Z + tid;
                int llr_pos = col * Z + shifted_z;

                __half app_val0, app_val1;
                if (FULL_SHMEM) {
                    app_val0 = s_app_0[llr_pos];
                    app_val1 = cb1_valid ? s_app_1[llr_pos] : zero;
                } else {
                    app_val0 = (col < Kb) ? s_app_0[llr_pos] : app0[llr_pos];
                    app_val1 = cb1_valid ? ((col < Kb) ? s_app_1[llr_pos] : app1[llr_pos]) : zero;
                }

                __half v2c0, v2c1;
                if (iter == 0) {
                    v2c0 = app_val0;
                    v2c1 = cb1_valid ? app_val1 : zero;
                } else {
                    __half old_c2v0 = c2v0[c2v_idx];
                    __half old_c2v1 = cb1_valid ? c2v1[c2v_idx] : zero;
                    v2c0 = __hsub(app_val0, old_c2v0);
                    v2c1 = __hsub(app_val1, old_c2v1);
                }

                // Pack V2C as half2 and cache
                __half2 v2c_packed = __halves2half2(v2c0, v2c1);
                uint32_t v2c_raw = *reinterpret_cast<uint32_t*>(&v2c_packed);
                v2c_cache[e] = v2c_raw;
            }

            // Binary tree exclusion product: excl_h2[e] = box_plus of all v2c[j] for j != e
            if (degree > 1) {
                switch (degree) {
                    case 3:  bp_tree_3_h2(v2c_cache, excl_h2);  break;
                    case 4:  bp_tree_4_h2(v2c_cache, excl_h2);  break;
                    case 5:  bp_tree_5_h2(v2c_cache, excl_h2);  break;
                    case 6:  bp_tree_6_h2(v2c_cache, excl_h2);  break;
                    case 7:  bp_tree_7_h2(v2c_cache, excl_h2);  break;
                    case 8:  bp_tree_8_h2(v2c_cache, excl_h2);  break;
                    case 9:  bp_tree_9_h2(v2c_cache, excl_h2);  break;
                    case 10: bp_tree_10_h2(v2c_cache, excl_h2); break;
                    case 19: bp_tree_19_h2(v2c_cache, excl_h2); break;
                }
            }

            // PASS 2: Apply NMS and update APP values
            bool nms_mul_only = __heq(offset, zero);

            #pragma unroll 8
            for (int e = 0; e < degree; e++) {
                int col = cached_col[e];
                int app_idx = col * Z + cached_shifted_z[e];
                int c2v_idx = (row * max_deg + e) * Z + tid;

                __half2 v2c_packed = *reinterpret_cast<__half2*>(&v2c_cache[e]);
                __half v2c0_val = __low2half(v2c_packed);
                __half v2c1_val = __high2half(v2c_packed);

                uint32_t c2v_packed;
                if (degree == 1) {
                    c2v_packed = *reinterpret_cast<const uint32_t*>(&zero2);
                } else {
                    c2v_packed = excl_h2[e];
                }

                // Apply NMS — fast path: single multiply, skip clamp (scale ≤ 1.0)
                __half2 new_c2v_h2;
                if (nms_mul_only) {
                    __half2 c2v_h2 = *reinterpret_cast<__half2*>(&c2v_packed);
                    new_c2v_h2 = __hmul2(scale2, c2v_h2);
                } else {
                    __half2 c2v_h2 = *reinterpret_cast<__half2*>(&c2v_packed);
                    __half2 c2v_abs2 = __habs2(c2v_h2);
                    __half2 scaled2 = __hmax2(__hsub2(__hmul2(scale2, c2v_abs2), offset2), zero2);
                    uint32_t c2v_u32 = c2v_packed;
                    uint32_t scaled_u32 = *reinterpret_cast<uint32_t*>(&scaled2);
                    scaled_u32 |= (c2v_u32 & 0x80008000);
                    new_c2v_h2 = *reinterpret_cast<__half2*>(&scaled_u32);
                    new_c2v_h2 = __hmax2(__hmin2(new_c2v_h2, clamp2), __hneg2(clamp2));
                }

                __half new_c2v0 = __low2half(new_c2v_h2);
                __half new_c2v1 = __high2half(new_c2v_h2);

                __half new_app0 = __hadd(v2c0_val, new_c2v0);
                __half new_app1 = cb1_valid ? __hadd(v2c1_val, new_c2v1) : zero;

                c2v0[c2v_idx] = new_c2v0;
                if (cb1_valid) c2v1[c2v_idx] = new_c2v1;

                if (FULL_SHMEM) {
                    s_app_0[app_idx] = new_app0;
                    if (cb1_valid) s_app_1[app_idx] = new_app1;
                } else {
                    if (col < Kb) {
                        s_app_0[app_idx] = new_app0;
                        if (cb1_valid) s_app_1[app_idx] = new_app1;
                    }
                    app0[app_idx] = new_app0;
                    if (cb1_valid) app1[app_idx] = new_app1;
                }
            }
            // Fence only needed for !FULL_SHMEM (app_global cross-thread deps).
            if (!FULL_SHMEM) __threadfence_block();
            __syncthreads();

        }

        // CRC EARLY TERMINATION
        // Two paths: serial (small blocks) and warp-cooperative (large blocks).
        // Warp-cooperative uses __ballot_sync + byte CRC table, ~8x faster for BG1 Z=384
        // but has overhead that hurts small blocks. Threshold: 4096 bits.
        if (crc_early_termination && crc_type != LDPC_CRC_NONE_INTERNAL) {
            if (tid == 0) {
                s_crc_result[0] = 0xFFFFFFFF;
                s_crc_result[1] = 0xFFFFFFFF;
            }
            __syncthreads();

            const int total_bits = (crc_check_bits > 0) ? crc_check_bits : (Kb * Z);

            // Select CRC polynomial, order, and mask based on CRC type.
            uint32_t polynomial;
            uint32_t crc_highbit;
            uint32_t crc_mask;
            int crc_order;
            if (crc_type == LDPC_CRC_16_INTERNAL) {
                polynomial = 0x11021u;
                crc_highbit = 1u << 16;
                crc_mask = 0xFFFFu;
                crc_order = 16;
            } else if (crc_type == LDPC_CRC_24A_INTERNAL) {
                polynomial = 0x1864CFBu;
                crc_highbit = 1u << 24;
                crc_mask = 0xFFFFFFu;
                crc_order = 24;
            } else {
                polynomial = 0x1800063u;
                crc_highbit = 1u << 24;
                crc_mask = 0xFFFFFFu;
                crc_order = 24;
            }

            constexpr int WARP_CRC_THRESHOLD = 4096;

            if (total_bits < WARP_CRC_THRESHOLD) {
                // Serial CRC: thread 0 does CB0, thread 1 does CB1.
                if (tid == 0 || (tid == 1 && cb1_valid)) {
                    const __half* s_app = (tid == 0) ? s_app_0 : s_app_1;
                    uint32_t crc = 0;
                    int col = 0, row = 0;
                    for (int i = 0; i < total_bits; i++) {
                        uint32_t bit = __hlt(s_app[col * Z + row], zero) ? 1u : 0u;
                        crc = (crc << 1) | bit;
                        if (crc & crc_highbit) crc ^= polynomial;
                        if (++row >= Z) { row = 0; col++; }
                    }
                    s_crc_result[tid] = crc & crc_mask;
                }
            } else {
                // Warp-cooperative CRC: first warp (32 threads) participates.
                if (tid < 32) {
                    const int lane_id = tid;
                    uint32_t crc0 = 0, crc1 = 0;
                    const int total_rounds = (total_bits + 31) / 32;

                    for (int round = 0; round < total_rounds; round++) {
                        int my_bit = round * 32 + lane_id;
                        bool sign0 = false, sign1 = false;
                        if (my_bit < total_bits) {
                            int col = my_bit / Z;
                            int row = my_bit % Z;
                            sign0 = __hlt(s_app_0[col * Z + row], zero);
                            if (cb1_valid) sign1 = __hlt(s_app_1[col * Z + row], zero);
                        }
                        uint32_t ballot0 = __ballot_sync(0xFFFFFFFF, sign0);
                        uint32_t ballot1 = cb1_valid ? __ballot_sync(0xFFFFFFFF, sign1) : 0;

                        uint32_t word0 = __brev(ballot0);
                        uint32_t word1 = __brev(ballot1);
                        int bits_this_round = min(32, total_bits - round * 32);

                        if (lane_id == 0) {
                            int full_bytes = bits_this_round / 8;
                            int remaining = bits_this_round % 8;
                            for (int b = 0; b < full_bytes; b++) {
                                uint8_t byte_val = (word0 >> (24 - b * 8)) & 0xFF;
                                if (crc_order == 16) {
                                    crc0 = (crc0 << 8) ^ d_crc16_table_ldpc[((crc0 >> 8) ^ byte_val) & 0xFF];
                                } else if (crc_type == LDPC_CRC_24A_INTERNAL) {
                                    crc0 = (crc0 << 8) ^ d_crc24a_table_ldpc[((crc0 >> 16) ^ byte_val) & 0xFF];
                                } else {
                                    crc0 = (crc0 << 8) ^ d_crc24b_table_ldpc[((crc0 >> 16) ^ byte_val) & 0xFF];
                                }
                            }
                            if (remaining > 0) {
                                int shift = 24 - full_bytes * 8;
                                for (int r = 0; r < remaining; r++) {
                                    uint32_t bit = (word0 >> (shift + 7 - r)) & 1u;
                                    crc0 = (crc0 << 1) | bit;
                                    if (crc0 & crc_highbit) crc0 ^= polynomial;
                                }
                            }
                        }
                        if (lane_id == 1 && cb1_valid) {
                            int full_bytes = bits_this_round / 8;
                            int remaining = bits_this_round % 8;
                            for (int b = 0; b < full_bytes; b++) {
                                uint8_t byte_val = (word1 >> (24 - b * 8)) & 0xFF;
                                if (crc_order == 16) {
                                    crc1 = (crc1 << 8) ^ d_crc16_table_ldpc[((crc1 >> 8) ^ byte_val) & 0xFF];
                                } else if (crc_type == LDPC_CRC_24A_INTERNAL) {
                                    crc1 = (crc1 << 8) ^ d_crc24a_table_ldpc[((crc1 >> 16) ^ byte_val) & 0xFF];
                                } else {
                                    crc1 = (crc1 << 8) ^ d_crc24b_table_ldpc[((crc1 >> 16) ^ byte_val) & 0xFF];
                                }
                            }
                            if (remaining > 0) {
                                int shift = 24 - full_bytes * 8;
                                for (int r = 0; r < remaining; r++) {
                                    uint32_t bit = (word1 >> (shift + 7 - r)) & 1u;
                                    crc1 = (crc1 << 1) | bit;
                                    if (crc1 & crc_highbit) crc1 ^= polynomial;
                                }
                            }
                        }
                    }
                    if (lane_id == 0) s_crc_result[0] = crc0 & crc_mask;
                    if (lane_id == 1 && cb1_valid) s_crc_result[1] = crc1 & crc_mask;
                }
            }
            __syncthreads();

            bool cb0_converged = (s_crc_result[0] == 0);
            bool cb1_converged = !cb1_valid || (s_crc_result[1] == 0);

            if (cb0_converged && cb1_converged) {
                final_iter = iter + 1;
                if (tid == 0) {
                    s_final_iter = final_iter;
                }
                break;
            }
        }
    }

    __syncthreads();
    final_iter = s_final_iter;

    // Hard decision from shared memory (MSB-first-per-byte directly)
    if ((Z & 31) == 0) {
        int lane_id = tid & 31;
        for (int col = 0; col < Kb; col++) {
            int flat_bit = col * Z + tid;
            int word_idx = flat_bit / 32;

            if (word_idx < output_stride) {
                int bit0 = __hlt(s_app_0[col * Z + tid], zero) ? 1 : 0;
                unsigned int ballot0 = __ballot_sync(0xFFFFFFFF, bit0);
                if (lane_id == 0) {
                    ballot0 = ((ballot0 & 0xF0F0F0F0) >> 4) | ((ballot0 & 0x0F0F0F0F) << 4);
                    ballot0 = ((ballot0 & 0xCCCCCCCC) >> 2) | ((ballot0 & 0x33333333) << 2);
                    ballot0 = ((ballot0 & 0xAAAAAAAA) >> 1) | ((ballot0 & 0x55555555) << 1);
                    output0[word_idx] = ballot0;
                }

                if (cb1_valid) {
                    int bit1 = __hlt(s_app_1[col * Z + tid], zero) ? 1 : 0;
                    unsigned int ballot1 = __ballot_sync(0xFFFFFFFF, bit1);
                    if (lane_id == 0) {
                        ballot1 = ((ballot1 & 0xF0F0F0F0) >> 4) | ((ballot1 & 0x0F0F0F0F) << 4);
                        ballot1 = ((ballot1 & 0xCCCCCCCC) >> 2) | ((ballot1 & 0x33333333) << 2);
                        ballot1 = ((ballot1 & 0xAAAAAAAA) >> 1) | ((ballot1 & 0x55555555) << 1);
                        output1[word_idx] = ballot1;
                    }
                }
            }
        }
    } else {
        for (int col = 0; col < Kb; col++) {
            int flat_bit = col * Z + tid;
            int word_idx = flat_bit / 32;
            int bit_pos = msb_first_bit_pos(flat_bit);

            if (word_idx < output_stride) {
                int bit0 = __hlt(s_app_0[col * Z + tid], zero) ? 1 : 0;
                if (bit0) atomicOr(&output0[word_idx], 1u << bit_pos);

                if (cb1_valid) {
                    int bit1 = __hlt(s_app_1[col * Z + tid], zero) ? 1 : 0;
                    if (bit1) atomicOr(&output1[word_idx], 1u << bit_pos);
                }
            }
        }
    }

    if (d_iterations != nullptr && tid == 0) {
        d_iterations[cb0_idx] = final_iter;
        if (cb1_valid) {
            d_iterations[cb1_idx] = final_iter;
        }
    }

    // Write CRC results if requested
    if (d_crc_results != nullptr && tid == 0) {
        d_crc_results[cb0_idx] = s_crc_result[0];
        if (cb1_valid) {
            d_crc_results[cb1_idx] = s_crc_result[1];
        }
    }
}

// ============================================================================
// API Implementation
// ============================================================================

extern "C" {

void ldpc_decoder_params_init(ldpc_decoder_params_t* params) {
    params->max_iterations = 10;
    params->early_termination = true;
    params->llr_clamp = 32.0f;
    params->min_sum_scale = 0.75f;   // Fallback if auto_scale=false
    params->min_sum_offset = 0.0f;   // No offset
    params->auto_scale = true;       // Use rate-adaptive scaling (per cuPHY)
    params->output_soft = false;
    params->skip_iteration_stats = true;   // DEPRECATED: skip by default for compat
    params->deferred_iteration_stats = false;  // Async iteration tracking disabled by default
    params->syndrome_tolerance = 0;  // Strict parity check by default
    params->crc_early_termination = true;    // Enable CRC-based early termination
    params->crc_type = LDPC_CRC_24B;         // Default to CRC24B (multi-CB case)
    params->confidence_threshold = 0.25f;    // Low threshold for fast filter before CRC
    params->use_boxplus = false;             // Default to min-sum (well-tested)
}

nr_ldpc_status_t ldpc_decoder_create(ldpc_decoder_handle_t* handle) {
    FlexibleLdpcDecoder* dec = new (std::nothrow) FlexibleLdpcDecoder;
    if (!dec) return NR_LDPC_ERROR_ALLOC_FAILED;

    memset(dec, 0, sizeof(*dec));

    // Initialize CRC24B table for early termination (one-time init, thread-safe)
    init_crc24b_table_ldpc();

    // Initialize Φ LUT for true box-plus (sum-product) decoding
    init_phi_lut();

    // Initialize cache to "not cached" state
    dec->cached_base_graph = -1;
    dec->cached_Z = -1;

    // Detect platform for adaptive kernel selection
    dec->platform_cfg = detect_platform();

    dec->shmem_mode = -1;
    if (const char* env = std::getenv("OCUDU_LDPC_SHMEM")) {
        if (std::strcmp(env, "low") == 0 || std::strcmp(env, "0") == 0) {
            dec->shmem_mode = 0;
        } else if (std::strcmp(env, "full") == 0 || std::strcmp(env, "1") == 0) {
            dec->shmem_mode = 1;
        }
    }

    dec->one_cb_max_cbs = -1;
    if (const char* env = std::getenv("OCUDU_LDPC_1CB_MAX_CBS")) {
        char* end = nullptr;
        long value = std::strtol(env, &end, 10);
        if (end != env && value >= 0 && value <= 1000000L) {
            dec->one_cb_max_cbs = static_cast<int>(value);
        }
    }

    dec->c2v_mode = -1;
    if (const char* env = std::getenv("OCUDU_LDPC_C2V")) {
        if (std::strcmp(env, "compressed") == 0 || std::strcmp(env, "compact") == 0 ||
            std::strcmp(env, "1") == 0) {
            dec->c2v_mode = 1;
        } else if (std::strcmp(env, "full") == 0 || std::strcmp(env, "edge") == 0 ||
                   std::strcmp(env, "0") == 0) {
            dec->c2v_mode = 0;
        } else if (std::strcmp(env, "auto") == 0) {
            dec->c2v_mode = -1;
        }
    }

    dec->app_cache_cols = 0;
    if (const char* env = std::getenv("OCUDU_LDPC_APP_CACHE_COLS")) {
        if (std::strcmp(env, "low") == 0 || std::strcmp(env, "kb") == 0) {
            dec->app_cache_cols = 1; // Clamped to Kb after configuration is known.
        } else if (std::strcmp(env, "mid") == 0) {
            dec->app_cache_cols = 48;
        } else if (std::strcmp(env, "full") == 0) {
            dec->app_cache_cols = 1000000; // Clamped to N after configuration is known.
        } else {
            char* end = nullptr;
            long value = std::strtol(env, &end, 10);
            if (end != env && value > 0 && value <= 1000000L) {
                dec->app_cache_cols = static_cast<int>(value);
            }
        }
    }

    // Create event for deferred iteration stats
    cudaEventCreateWithFlags(&dec->iteration_stats_event, cudaEventDisableTiming);
    dec->iteration_stats_pending = false;
    dec->iteration_stats_count = 0;
    dec->deferred_stats_enabled = false;

    // PHASE 0 FIX: Create completion events for triple-buffered workspaces
    for (int i = 0; i < FlexibleLdpcDecoder::NUM_WORKSPACE_BUFFERS; i++) {
        cudaError_t err = cudaEventCreateWithFlags(&dec->workspace_complete[i], cudaEventDisableTiming);
        if (err != cudaSuccess) {
            // Cleanup on error
            for (int j = 0; j < i; j++) {
                cudaEventDestroy(dec->workspace_complete[j]);
            }
            cudaEventDestroy(dec->iteration_stats_event);
            delete dec;
            return NR_LDPC_ERROR_CUDA_FAILED;
        }
    }

    *handle = reinterpret_cast<ldpc_decoder_handle_t>(dec);
    return NR_LDPC_SUCCESS;
}

nr_ldpc_status_t ldpc_decoder_configure(
    ldpc_decoder_handle_t handle,
    const nr_ldpc_config_t* cfg,
    const ldpc_decoder_params_t* params
) {
    FlexibleLdpcDecoder* dec = reinterpret_cast<FlexibleLdpcDecoder*>(handle);
    if (!dec || !cfg || !params) return NR_LDPC_ERROR_INVALID_CONFIG;

    dec->config = *cfg;
    dec->params = *params;
    dec->deferred_stats_enabled = params->deferred_iteration_stats;
    dec->base_graph = cfg->base_graph;
    dec->Z = cfg->lifting_size;

    // Set parameters based on base graph
    int M_full;
    if (dec->base_graph == 1) {
        dec->Kb = BG1_KB;
        dec->N = BG1_N;
        M_full = BG1_M;
        dec->nnz = BG1_NNZ;
        dec->max_deg = BG1_MAX_DEG;
    } else if (dec->base_graph == 2) {
        dec->Kb = BG2_KB;
        dec->N = BG2_N;
        M_full = BG2_M;
        dec->nnz = BG2_NNZ;
        dec->max_deg = BG2_MAX_DEG;
    } else {
        fprintf(stderr, "ERROR: Invalid base graph %d\n", dec->base_graph);
        return NR_LDPC_ERROR_INVALID_BG;
    }

    // Use config's max_parity_nodes if set (per srsRAN n_layers formula)
    // This limits decoder to rows that have received LLRs, avoiding
    // pollution from rows with all-zero parity columns
    if (cfg->max_parity_nodes > 0 && cfg->max_parity_nodes < M_full) {
        dec->M = cfg->max_parity_nodes;
    } else {
        dec->M = M_full;
    }

    dec->K_bits = dec->Kb * dec->Z;
    dec->K_words = (dec->K_bits + 31) / 32;
    dec->N_llrs = dec->N * dec->Z;

    // Compute effective scale factor
    if (params->auto_scale) {
        // Use rate-adaptive normalization based on number of parity rows (cuPHY tables)
        dec->effective_scale = get_optimal_norm(dec->base_graph, dec->M);
    } else {
        // Use user-specified scale
        dec->effective_scale = params->min_sum_scale;
    }

    // OPTIMIZATION: Skip shift table reallocation if graph parameters haven't changed.
    // The shift table only depends on base_graph and Z.
    if (dec->cached_base_graph == dec->base_graph && dec->cached_Z == dec->Z) {
        return NR_LDPC_SUCCESS;
    }

    // Graph parameters changed - reset layered half2 shmem probe (shmem depends on N and Z)
    dec->layered_half2_shmem_probed = false;

    // Graph parameters changed - need to reallocate and copy
    // Allocate scaled shifts
    if (dec->d_scaled_shifts) cudaFree(dec->d_scaled_shifts);
    cudaMalloc(&dec->d_scaled_shifts, dec->nnz * sizeof(int16_t));

    // Compute lifting set index from Z (like encoder does for consistency)
    int iLS = get_lifting_set_idx(dec->Z);
    if (iLS < 0) {
        fprintf(stderr, "ERROR: Invalid lifting size Z=%d\n", dec->Z);
        return NR_LDPC_ERROR_INVALID_Z;
    }

    // Select correct shift table based on base graph and lifting set index
    // Each lifting set has its own reference shifts per 3GPP TS 38.212
    const int16_t* h_shifts_ref;
    if (dec->base_graph == 1) {
        h_shifts_ref = h_bg1_shifts[iLS];
    } else {
        h_shifts_ref = h_bg2_shifts[iLS];
    }
    dec->Z_ref = LIFTING_SET_Z_REF[iLS];
    std::vector<int16_t> h_scaled_shifts(dec->nnz);

    for (int i = 0; i < dec->nnz; i++) {
        h_scaled_shifts[i] = (int16_t)compute_shift(h_shifts_ref[i], dec->Z, dec->Z_ref);
    }

    // Copy pre-scaled shifts to device
    cudaMemcpy(dec->d_scaled_shifts, h_scaled_shifts.data(),
               dec->nnz * sizeof(int16_t), cudaMemcpyHostToDevice);

    // Update cache
    dec->cached_base_graph = dec->base_graph;
    dec->cached_Z = dec->Z;

    return NR_LDPC_SUCCESS;
}

nr_ldpc_status_t ldpc_decoder_decode_batch(
    ldpc_decoder_handle_t handle,
    const float* d_llr_input,
    uint32_t* d_output,
    int num_codewords,
    cudaStream_t stream
) {
    FlexibleLdpcDecoder* dec = reinterpret_cast<FlexibleLdpcDecoder*>(handle);
    if (!dec || !d_llr_input || !d_output || num_codewords <= 0) {
        return NR_LDPC_ERROR_INVALID_CONFIG;
    }

    // Allocate workspace if needed
    size_t app_size = num_codewords * dec->N * dec->Z * sizeof(__half);
    size_t c2v_size = num_codewords * dec->M * dec->max_deg * dec->Z * sizeof(__half);
    size_t needed = app_size + c2v_size;

    if (needed > dec->workspace_size || num_codewords > dec->max_batch_size) {
        if (dec->d_app) cudaFree(dec->d_app);
        if (dec->d_c2v) cudaFree(dec->d_c2v);
        cudaMalloc(&dec->d_app, app_size);
        cudaMalloc(&dec->d_c2v, c2v_size);
        dec->workspace_size = needed;
        dec->max_batch_size = num_codewords;
    }

    // Allocate iteration tracking buffers if needed
    if (num_codewords > dec->iterations_buffer_size) {
        if (dec->d_iterations) cudaFree(dec->d_iterations);
        if (dec->h_iterations) cudaFreeHost(dec->h_iterations);
        cudaMalloc(&dec->d_iterations, num_codewords * sizeof(int));
        cudaMallocHost(&dec->h_iterations, num_codewords * sizeof(int));
        dec->iterations_buffer_size = num_codewords;
    }

    // Clear output
    cudaMemsetAsync(d_output, 0, num_codewords * dec->K_words * sizeof(uint32_t), stream);

    __half scale = __float2half(dec->effective_scale);  // Use rate-adaptive or user-specified scale
    __half offset = __float2half(dec->params.min_sum_offset);
    __half clamp = __float2half(dec->params.llr_clamp);

    // Use x2 kernel (process 2 codewords per block)
    int num_pairs = (num_codewords + 1) / 2;

    __half conf_thresh = __float2half(dec->params.confidence_threshold);
    bool crc_et = dec->params.crc_early_termination;
    // CRC check bits = num_info_bits (= Kb*Z - filler_bits)
    int crc_bits = dec->config.num_info_bits;
    // CRC type from params (0=none, 1=CRC16, 2=CRC24A, 3=CRC24B)
    int crc_type = static_cast<int>(dec->params.crc_type);

    if (dec->base_graph == 1) {
        ldpc_decode_layered_x2_kernel<1><<<num_pairs, dec->Z, 0, stream>>>(
            d_llr_input,
            dec->d_app,
            dec->d_c2v,
            d_output,
            dec->d_scaled_shifts,  // Pre-scaled shifts
            dec->Z,
            dec->N,
            dec->M,
            dec->Kb,
            dec->nnz,
            dec->max_deg,
            dec->N_llrs,
            dec->K_words,
            dec->params.max_iterations,
            scale,
            offset,
            clamp,
            num_codewords,
            dec->d_iterations,  // Pass iteration tracking buffer
            crc_et,             // CRC-based early termination
            conf_thresh,        // Confidence threshold for CRC check
            crc_bits,           // Actual info bits (excludes filler)
            crc_type            // CRC type (16, 24A, 24B)
        );
    } else {
        ldpc_decode_layered_x2_kernel<2><<<num_pairs, dec->Z, 0, stream>>>(
            d_llr_input,
            dec->d_app,
            dec->d_c2v,
            d_output,
            dec->d_scaled_shifts,  // Pre-scaled shifts
            dec->Z,
            dec->N,
            dec->M,
            dec->Kb,
            dec->nnz,
            dec->max_deg,
            dec->N_llrs,
            dec->K_words,
            dec->params.max_iterations,
            scale,
            offset,
            clamp,
            num_codewords,
            dec->d_iterations,  // Pass iteration tracking buffer
            crc_et,             // CRC-based early termination
            conf_thresh,        // Confidence threshold for CRC check
            crc_bits,           // Actual info bits (excludes filler)
            crc_type            // CRC type (16, 24A, 24B)
        );
    }

    // Handle iteration stats based on mode
    if (dec->deferred_stats_enabled) {
        // Deferred mode: issue async D2H, record event, don't block
        cudaMemcpyAsync(dec->h_iterations, dec->d_iterations,
                        num_codewords * sizeof(int), cudaMemcpyDeviceToHost, stream);
        cudaEventRecord(dec->iteration_stats_event, stream);
        dec->iteration_stats_pending = true;
        dec->iteration_stats_count = num_codewords;
    } else if (!dec->params.skip_iteration_stats) {
        // Legacy blocking mode (deprecated)
        cudaMemcpyAsync(dec->h_iterations, dec->d_iterations,
                        num_codewords * sizeof(int), cudaMemcpyDeviceToHost, stream);
        cudaStreamSynchronize(stream);

        int total_iterations = 0;
        for (int i = 0; i < num_codewords; i++) {
            total_iterations += dec->h_iterations[i];
        }
        dec->last_avg_iterations = (float)total_iterations / num_codewords;
    }

    return NR_LDPC_SUCCESS;
}

nr_ldpc_status_t ldpc_decoder_decode(
    ldpc_decoder_handle_t handle,
    const float* d_llr_input,
    uint32_t* d_output,
    cudaStream_t stream
) {
    return ldpc_decoder_decode_batch(handle, d_llr_input, d_output, 1, stream);
}

nr_ldpc_status_t ldpc_decoder_decode_batch_half(
    ldpc_decoder_handle_t handle,
    const void* d_llr_input_half,
    uint32_t* d_output,
    int num_codewords,
    cudaStream_t stream,
    int workspace_buffer_index
) {
    FlexibleLdpcDecoder* dec = reinterpret_cast<FlexibleLdpcDecoder*>(handle);
    if (!dec || !d_llr_input_half || !d_output || num_codewords <= 0) {
        return NR_LDPC_ERROR_INVALID_CONFIG;
    }

    const __half* d_llr_half = static_cast<const __half*>(d_llr_input_half);

    // Use workspace_buffer_index from caller for synchronized triple-buffering.
    // If not provided (-1), fall back to internal counter.
    int ws_buf_idx;
    if (workspace_buffer_index >= 0 && workspace_buffer_index < FlexibleLdpcDecoder::NUM_WORKSPACE_BUFFERS) {
        ws_buf_idx = workspace_buffer_index;
    } else {
        ws_buf_idx = dec->current_workspace_buf;
        dec->current_workspace_buf = (dec->current_workspace_buf + 1) % FlexibleLdpcDecoder::NUM_WORKSPACE_BUFFERS;
    }

    // Allocate FP16 triple-buffered workspace if needed
    size_t app_size = num_codewords * dec->N * dec->Z * sizeof(__half);
    size_t c2v_size = num_codewords * dec->M * dec->max_deg * dec->Z * sizeof(__half);
    size_t needed = app_size + c2v_size;

    if (needed > dec->workspace_size_half || num_codewords > dec->max_batch_size_half) {
        for (int i = 0; i < FlexibleLdpcDecoder::NUM_WORKSPACE_BUFFERS; i++) {
            if (dec->d_app_half[i]) cudaFree(dec->d_app_half[i]);
            if (dec->d_c2v_half[i]) cudaFree(dec->d_c2v_half[i]);
            cudaMalloc(&dec->d_app_half[i], app_size);
            cudaMalloc(&dec->d_c2v_half[i], c2v_size);
        }
        if (cudaStreamSynchronize(stream) != cudaSuccess) return NR_LDPC_ERROR_CUDA_FAILED;
        dec->workspace_size_half = needed;
        dec->max_batch_size_half = num_codewords;
    }

    // Allocate iteration tracking buffers if needed
    if (num_codewords > dec->iterations_buffer_size) {
        if (dec->d_iterations) cudaFree(dec->d_iterations);
        if (dec->h_iterations) cudaFreeHost(dec->h_iterations);
        cudaMalloc(&dec->d_iterations, num_codewords * sizeof(int));
        cudaMallocHost(&dec->h_iterations, num_codewords * sizeof(int));
        dec->iterations_buffer_size = num_codewords;
    }

    // Allocate CRC results buffers if CRC early termination is enabled
    if (dec->params.crc_early_termination && num_codewords > dec->crc_results_buffer_size) {
        if (dec->d_crc_results) cudaFree(dec->d_crc_results);
        if (dec->h_crc_results) cudaFreeHost(dec->h_crc_results);
        cudaMalloc(&dec->d_crc_results, num_codewords * sizeof(int));
        cudaMallocHost(&dec->h_crc_results, num_codewords * sizeof(int));
        dec->crc_results_buffer_size = num_codewords;
    }

    // Note: Output buffer is zeroed inside the kernel (before atomicOr hard decisions).
    // Note: d_iterations and d_crc_results are written unconditionally by thread 0
    // in every kernel variant, so no pre-zeroing is needed.
    // Note: APP and C2V buffers are initialized inside the kernel (APP from channel LLRs,
    // C2V to zero), so host-side zeroing is redundant.

    // Wait for previous decode using this buffer to complete (triple-buffering).
    cudaStreamWaitEvent(stream, dec->workspace_complete[ws_buf_idx], 0);

    bool use_boxplus = dec->params.use_boxplus;

    // Both min-sum and box-plus kernels use the same NMS (normalized min-sum) correction.
    // Box-plus uses forward/backward prefix scan of min.xorsign.abs — mathematically
    // equivalent to min-sum, so the same scale/offset correction applies.
    __half scale = __float2half(dec->effective_scale);
    __half offset = __float2half(dec->params.min_sum_offset);
    __half clamp = __float2half(dec->params.llr_clamp);

    int num_pairs = (num_codewords + 1) / 2;
    __half conf_thresh = __float2half(dec->params.confidence_threshold);
    bool crc_et = dec->params.crc_early_termination;
    int crc_bits = dec->config.num_info_bits;
    int crc_type = static_cast<int>(dec->params.crc_type);
    int filler_start = dec->config.num_info_bits;  // K = actual info bits (filler starts here)
    int filler_count = dec->config.num_filler_bits; // F = Kb*Z - K
    bool offset_zero_nms = (dec->params.min_sum_offset == 0.0f);

    { // FP16 dispatch scope (braces needed for goto to skip over local declarations)

    // Dynamic shared memory sizes
    // 2-CB kernel: 2 APP buffers (one per CB)
    size_t shmem_kb_2cb = 2 * dec->Kb * dec->Z * sizeof(__half);
    size_t shmem_all_2cb = 2 * dec->N * dec->Z * sizeof(__half);
    // 1-CB kernel: 1 APP buffer
    size_t shmem_kb_1cb = dec->Kb * dec->Z * sizeof(__half);
    size_t shmem_all_1cb = dec->N * dec->Z * sizeof(__half);

    // One-time probe: which FULL_SHMEM variants fit on this GPU?
    if (!dec->layered_half2_shmem_probed) {
        // Helper lambda to probe a kernel for FULL_SHMEM support
        auto probe_shmem = [&](const void* kernel_ptr, size_t shmem_size) -> bool {
            if (shmem_size <= 48 * 1024) return true;
            if ((int)shmem_size <= dec->platform_cfg.max_shmem_per_block) {
                cudaError_t err = cudaFuncSetAttribute(
                    kernel_ptr, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)shmem_size);
                if (err != cudaSuccess) { cudaGetLastError(); return false; }
                return true;
            }
            return false;
        };

        // Probe min-sum kernels
        dec->layered_half2_shmem_ok = probe_shmem(
            (dec->base_graph == 1)
                ? (const void*)ldpc_decode_layered_half2_kernel<1, true>
                : (const void*)ldpc_decode_layered_half2_kernel<2, true>,
            shmem_all_2cb);
        dec->layered_half_shmem_ok = probe_shmem(
            (dec->base_graph == 1)
                ? (const void*)ldpc_decode_layered_half_kernel<1, true>
                : (const void*)ldpc_decode_layered_half_kernel<2, true>,
            shmem_all_1cb);

        // Probe box-plus kernels
        dec->boxplus_half2_shmem_ok = probe_shmem(
            (dec->base_graph == 1)
                ? (const void*)ldpc_decode_boxplus_half2_kernel<1, true>
                : (const void*)ldpc_decode_boxplus_half2_kernel<2, true>,
            shmem_all_2cb);
        dec->boxplus_half_shmem_ok = probe_shmem(
            (dec->base_graph == 1)
                ? (offset_zero_nms
                       ? (const void*)ldpc_decode_boxplus_half_kernel<1, true, true>
                       : (const void*)ldpc_decode_boxplus_half_kernel<1, true, false>)
                : (offset_zero_nms
                       ? (const void*)ldpc_decode_boxplus_half_kernel<2, true, true>
                       : (const void*)ldpc_decode_boxplus_half_kernel<2, true, false>),
            shmem_all_1cb);

        dec->layered_half2_shmem_probed = true;

        if (!dec->layered_half2_shmem_ok && !dec->layered_half_shmem_ok) {
            fprintf(stderr, "OCUDU PHY CUDA: GPU max shared memory (%d KB) < full-shmem needs "
                    "(%.1f KB / %.1f KB). Using low-shmem (%.1f KB) for BG%d Z=%d.\n",
                    dec->platform_cfg.max_shmem_per_block / 1024,
                    shmem_all_2cb / 1024.0, shmem_all_1cb / 1024.0,
                    shmem_kb_2cb / 1024.0,
                    dec->base_graph, dec->Z);
        }
    }

    auto use_full_shmem = [&](bool full_shmem_ok) {
        if (dec->shmem_mode == 0) return false;
        return full_shmem_ok;
    };

    // Adaptive kernel selection: 1-CB kernel wins for small/medium batches
    // due to independent CRC early termination per CB.
    // The 1-CB kernels have more block-level independence and lower latency on
    // GB10-class wideband PUSCH batches even beyond 2x SM count. Keep 2-CB as
    // the fallback for very large batches, but bias the default for slot latency.
    int default_one_cb_threshold = 2 * dec->platform_cfg.sm_count;
    if (default_one_cb_threshold < 192) default_one_cb_threshold = 192;
    int one_cb_threshold = (dec->one_cb_max_cbs >= 0) ? dec->one_cb_max_cbs : default_one_cb_threshold;
    bool use_1cb = (num_codewords < one_cb_threshold);
    bool use_compressed_c2v = false;
    if (dec->c2v_mode > 0) {
        use_compressed_c2v = true;
    } else if (dec->c2v_mode < 0) {
        use_compressed_c2v = use_boxplus;
    }

    struct AppCacheChoice {
        bool full_shmem;
        int cols;
        size_t shmem_bytes;
    };

    auto choose_1cb_app_cache = [&](bool full_shmem_ok) {
        AppCacheChoice choice{};
        if (dec->app_cache_cols > 0) {
            int cols = dec->app_cache_cols;
            if (cols < dec->Kb) cols = dec->Kb;
            if (cols > dec->N) cols = dec->N;

            choice.full_shmem = (cols == dec->N) && use_full_shmem(full_shmem_ok);
            if (!choice.full_shmem && cols == dec->N) {
                cols = dec->Kb;
            }
            choice.cols = cols;
            choice.shmem_bytes = choice.full_shmem ? shmem_all_1cb : (size_t)cols * dec->Z * sizeof(__half);
            return choice;
        }

        if (use_boxplus && dec->base_graph == 1 && dec->Z == 384 && num_codewords >= 63 &&
            use_full_shmem(full_shmem_ok) && dec->N > 65 && dec->Kb <= 65) {
            choice.full_shmem = false;
            choice.cols = 65;
            choice.shmem_bytes = (size_t)choice.cols * dec->Z * sizeof(__half);
            return choice;
        }

	    choice.full_shmem = use_full_shmem(full_shmem_ok);
	    choice.cols = choice.full_shmem ? dec->N : dec->Kb;
	    choice.shmem_bytes = choice.full_shmem ? shmem_all_1cb : shmem_kb_1cb;
	    return choice;
	};

    auto prepare_dynamic_shmem = [&](const void* kernel_ptr, size_t shmem_bytes) -> bool {
        // Leave margin for static __shared__ state in the kernel. At exactly
        // 48 KiB dynamic shmem, launches can otherwise fail silently until the
        // next CUDA error check.
        if (shmem_bytes < 48 * 1024) {
            return true;
        }
        if ((int)shmem_bytes <= dec->platform_cfg.max_shmem_per_block) {
            cudaError_t err = cudaFuncSetAttribute(
                kernel_ptr, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)shmem_bytes);
            if (err == cudaSuccess) {
                return true;
            }
            cudaGetLastError();
        }
        return false;
    };

    if (use_compressed_c2v && use_1cb) {
        // 1-CB compressed-C2V min-sum kernel
        AppCacheChoice cache_1cb = choose_1cb_app_cache(dec->boxplus_half_shmem_ok);
        bool full_shmem_1cb = cache_1cb.full_shmem;
        size_t shmem_1cb = cache_1cb.shmem_bytes;
        if (!full_shmem_1cb) {
            const void* kernel_ptr = (dec->base_graph == 1)
                ? (offset_zero_nms
                       ? (const void*)ldpc_decode_boxplus_half_kernel<1, false, true>
                       : (const void*)ldpc_decode_boxplus_half_kernel<1, false, false>)
                : (offset_zero_nms
                       ? (const void*)ldpc_decode_boxplus_half_kernel<2, false, true>
                       : (const void*)ldpc_decode_boxplus_half_kernel<2, false, false>);
            if (!prepare_dynamic_shmem(kernel_ptr, shmem_1cb)) {
                cache_1cb.cols = dec->Kb;
                shmem_1cb = shmem_kb_1cb;
            }
        }

        #define LAUNCH_1CB_BP(BG_VAL, FSHMEM, OFFSET_ZERO_VAL) \
            ldpc_decode_boxplus_half_kernel<BG_VAL, FSHMEM, OFFSET_ZERO_VAL><<<num_codewords, dec->Z, shmem_1cb, stream>>>( \
                d_llr_half, dec->d_app_half[ws_buf_idx], dec->d_c2v_half[ws_buf_idx], \
                d_output, dec->d_scaled_shifts, dec->Z, dec->N, dec->M, dec->Kb, \
                dec->nnz, dec->max_deg, dec->N_llrs, dec->K_words, \
                dec->params.max_iterations, scale, offset, clamp, num_codewords, \
                dec->d_iterations, crc_et, conf_thresh, crc_bits, crc_type, \
                dec->d_crc_results, filler_start, filler_count, cache_1cb.cols)

        if (dec->base_graph == 1) {
            if (full_shmem_1cb) {
                if (offset_zero_nms) { LAUNCH_1CB_BP(1, true, true); }
                else                 { LAUNCH_1CB_BP(1, true, false); }
            } else {
                if (offset_zero_nms) { LAUNCH_1CB_BP(1, false, true); }
                else                 { LAUNCH_1CB_BP(1, false, false); }
            }
        } else {
            if (full_shmem_1cb) {
                if (offset_zero_nms) { LAUNCH_1CB_BP(2, true, true); }
                else                 { LAUNCH_1CB_BP(2, true, false); }
            } else {
                if (offset_zero_nms) { LAUNCH_1CB_BP(2, false, true); }
                else                 { LAUNCH_1CB_BP(2, false, false); }
            }
        }
        #undef LAUNCH_1CB_BP
    } else if (use_1cb) {
        // 1-CB min-sum kernel
        AppCacheChoice cache_1cb = choose_1cb_app_cache(dec->layered_half_shmem_ok);
        bool full_shmem_1cb = cache_1cb.full_shmem;
        size_t shmem_1cb = cache_1cb.shmem_bytes;
        if (!full_shmem_1cb) {
            const void* kernel_ptr = (dec->base_graph == 1)
                ? (const void*)ldpc_decode_layered_half_kernel<1, false>
                : (const void*)ldpc_decode_layered_half_kernel<2, false>;
            if (!prepare_dynamic_shmem(kernel_ptr, shmem_1cb)) {
                cache_1cb.cols = dec->Kb;
                shmem_1cb = shmem_kb_1cb;
            }
        }

        #define LAUNCH_1CB(BG_VAL, FSHMEM) \
            ldpc_decode_layered_half_kernel<BG_VAL, FSHMEM><<<num_codewords, dec->Z, shmem_1cb, stream>>>( \
                d_llr_half, dec->d_app_half[ws_buf_idx], dec->d_c2v_half[ws_buf_idx], \
                d_output, dec->d_scaled_shifts, dec->Z, dec->N, dec->M, dec->Kb, \
                dec->nnz, dec->max_deg, dec->N_llrs, dec->K_words, \
                dec->params.max_iterations, scale, offset, clamp, num_codewords, \
                dec->d_iterations, crc_et, conf_thresh, crc_bits, crc_type, \
                dec->d_crc_results, filler_start, filler_count, cache_1cb.cols)

        if (dec->base_graph == 1) {
            if (full_shmem_1cb) { LAUNCH_1CB(1, true); }
            else                { LAUNCH_1CB(1, false); }
        } else {
            if (full_shmem_1cb) { LAUNCH_1CB(2, true); }
            else                { LAUNCH_1CB(2, false); }
        }
        #undef LAUNCH_1CB
    } else if (use_compressed_c2v) {
        // 2-CB compressed-C2V min-sum kernel with FULL_SHMEM support
        bool full_shmem_2cb = use_full_shmem(dec->boxplus_half2_shmem_ok);
        size_t shmem_2cb = full_shmem_2cb ? shmem_all_2cb : shmem_kb_2cb;
        const void* kernel_ptr = (dec->base_graph == 1)
            ? (full_shmem_2cb
                   ? (offset_zero_nms
                          ? (const void*)ldpc_decode_boxplus_half2_compressed_kernel<1, true, true>
                          : (const void*)ldpc_decode_boxplus_half2_compressed_kernel<1, true, false>)
                   : (offset_zero_nms
                          ? (const void*)ldpc_decode_boxplus_half2_compressed_kernel<1, false, true>
                          : (const void*)ldpc_decode_boxplus_half2_compressed_kernel<1, false, false>))
            : (full_shmem_2cb
                   ? (offset_zero_nms
                          ? (const void*)ldpc_decode_boxplus_half2_compressed_kernel<2, true, true>
                          : (const void*)ldpc_decode_boxplus_half2_compressed_kernel<2, true, false>)
                   : (offset_zero_nms
                          ? (const void*)ldpc_decode_boxplus_half2_compressed_kernel<2, false, true>
                          : (const void*)ldpc_decode_boxplus_half2_compressed_kernel<2, false, false>));
        if (!prepare_dynamic_shmem(kernel_ptr, shmem_2cb)) {
            full_shmem_2cb = false;
            shmem_2cb = shmem_kb_2cb;
        }

        #define LAUNCH_2CB_BP(BG_VAL, FSHMEM, OFFSET_ZERO_VAL) \
            ldpc_decode_boxplus_half2_compressed_kernel<BG_VAL, FSHMEM, OFFSET_ZERO_VAL><<<num_pairs, dec->Z, shmem_2cb, stream>>>( \
                d_llr_half, dec->d_app_half[ws_buf_idx], dec->d_c2v_half[ws_buf_idx], \
                d_output, dec->d_scaled_shifts, dec->Z, dec->N, dec->M, dec->Kb, \
                dec->nnz, dec->max_deg, dec->N_llrs, dec->K_words, \
                dec->params.max_iterations, scale, offset, clamp, num_codewords, \
                dec->d_iterations, dec->params.syndrome_tolerance, \
                crc_et, conf_thresh, crc_bits, crc_type, \
                dec->d_crc_results, filler_start, filler_count)

        if (dec->base_graph == 1) {
            if (full_shmem_2cb) {
                if (offset_zero_nms) { LAUNCH_2CB_BP(1, true, true); }
                else                 { LAUNCH_2CB_BP(1, true, false); }
            } else {
                if (offset_zero_nms) { LAUNCH_2CB_BP(1, false, true); }
                else                 { LAUNCH_2CB_BP(1, false, false); }
            }
        } else {
            if (full_shmem_2cb) {
                if (offset_zero_nms) { LAUNCH_2CB_BP(2, true, true); }
                else                 { LAUNCH_2CB_BP(2, true, false); }
            } else {
                if (offset_zero_nms) { LAUNCH_2CB_BP(2, false, true); }
                else                 { LAUNCH_2CB_BP(2, false, false); }
            }
        }
        #undef LAUNCH_2CB_BP
    } else if (use_full_shmem(dec->layered_half2_shmem_ok)) {
        // 2-CB half2 with FULL shared memory (all N columns) — best throughput
        if (dec->base_graph == 1) {
            ldpc_decode_layered_half2_kernel<1, true><<<num_pairs, dec->Z, shmem_all_2cb, stream>>>(
            d_llr_half,
            dec->d_app_half[ws_buf_idx],
            dec->d_c2v_half[ws_buf_idx],
            d_output,
            dec->d_scaled_shifts,
            dec->Z,
            dec->N,
            dec->M,
            dec->Kb,
            dec->nnz,
            dec->max_deg,
            dec->N_llrs,
            dec->K_words,
            dec->params.max_iterations,
            scale,
            offset,
            clamp,
            num_codewords,
            dec->d_iterations,
            crc_et,
            conf_thresh,
            crc_bits,
            crc_type,
            dec->d_crc_results,
            filler_start,
            filler_count
        );
        } else {
            ldpc_decode_layered_half2_kernel<2, true><<<num_pairs, dec->Z, shmem_all_2cb, stream>>>(
            d_llr_half,
            dec->d_app_half[ws_buf_idx],
            dec->d_c2v_half[ws_buf_idx],
            d_output,
            dec->d_scaled_shifts,
            dec->Z,
            dec->N,
            dec->M,
            dec->Kb,
            dec->nnz,
            dec->max_deg,
            dec->N_llrs,
            dec->K_words,
            dec->params.max_iterations,
            scale,
            offset,
            clamp,
            num_codewords,
            dec->d_iterations,
            crc_et,
            conf_thresh,
            crc_bits,
            crc_type,
            dec->d_crc_results,
            filler_start,
            filler_count
        );
        }
    } else {
        // 2-CB half2 with LOW shared memory (Kb info columns only, parity in global)
        if (dec->base_graph == 1) {
            ldpc_decode_layered_half2_kernel<1, false><<<num_pairs, dec->Z, shmem_kb_2cb, stream>>>(
            d_llr_half,
            dec->d_app_half[ws_buf_idx],
            dec->d_c2v_half[ws_buf_idx],
            d_output,
            dec->d_scaled_shifts,
            dec->Z,
            dec->N,
            dec->M,
            dec->Kb,
            dec->nnz,
            dec->max_deg,
            dec->N_llrs,
            dec->K_words,
            dec->params.max_iterations,
            scale,
            offset,
            clamp,
            num_codewords,
            dec->d_iterations,
            crc_et,
            conf_thresh,
            crc_bits,
            crc_type,
            dec->d_crc_results,
            filler_start,
            filler_count
        );
        } else {
            ldpc_decode_layered_half2_kernel<2, false><<<num_pairs, dec->Z, shmem_kb_2cb, stream>>>(
            d_llr_half,
            dec->d_app_half[ws_buf_idx],
            dec->d_c2v_half[ws_buf_idx],
            d_output,
            dec->d_scaled_shifts,
            dec->Z,
            dec->N,
            dec->M,
            dec->Kb,
            dec->nnz,
            dec->max_deg,
            dec->N_llrs,
            dec->K_words,
            dec->params.max_iterations,
            scale,
            offset,
            clamp,
            num_codewords,
            dec->d_iterations,
            crc_et,
            conf_thresh,
            crc_bits,
            crc_type,
            dec->d_crc_results,
            filler_start,
            filler_count
        );
        }
    }

    } // end FP16 dispatch scope

    // Record workspace completion event for triple-buffering synchronization.
    cudaEventRecord(dec->workspace_complete[ws_buf_idx], stream);

    // Handle iteration stats based on mode
    if (dec->deferred_stats_enabled) {
        // Deferred mode: issue async D2H, record event, don't block
        cudaMemcpyAsync(dec->h_iterations, dec->d_iterations,
                        num_codewords * sizeof(int), cudaMemcpyDeviceToHost, stream);
        cudaEventRecord(dec->iteration_stats_event, stream);
        dec->iteration_stats_pending = true;
        dec->iteration_stats_count = num_codewords;
    } else if (!dec->params.skip_iteration_stats) {
        // Legacy blocking mode (deprecated)
        cudaMemcpyAsync(dec->h_iterations, dec->d_iterations,
                        num_codewords * sizeof(int), cudaMemcpyDeviceToHost, stream);
        cudaStreamSynchronize(stream);

        int total_iterations = 0;
        for (int i = 0; i < num_codewords; i++) {
            total_iterations += dec->h_iterations[i];
        }
        dec->last_avg_iterations = (float)total_iterations / num_codewords;
    }

    return NR_LDPC_SUCCESS;
}

nr_ldpc_status_t ldpc_decoder_decode_batch_half_from_rate_matched(
    ldpc_decoder_handle_t handle,
    const void* d_rate_matched_llrs_half,
    uint32_t* d_output,
    int num_codewords,
    int Q_m,
    int N_cb,
    int k0,
    const int* d_rm_lengths,
    const unsigned int* d_rm_offsets,
    const unsigned int* d_scramble_sequence,
    int scramble_offset,
    cudaStream_t stream,
    int workspace_buffer_index)
{
    FlexibleLdpcDecoder* dec = reinterpret_cast<FlexibleLdpcDecoder*>(handle);
    if (!dec || !d_rate_matched_llrs_half || !d_output || !d_rm_lengths || !d_rm_offsets ||
        num_codewords <= 0 || Q_m <= 0 || Q_m > 8) {
        return NR_LDPC_ERROR_INVALID_CONFIG;
    }

    if (dec->base_graph != 1 || dec->Z != 384 || !dec->params.use_boxplus) {
        return NR_LDPC_ERROR_INVALID_CONFIG;
    }

    const __half* d_rm_half = static_cast<const __half*>(d_rate_matched_llrs_half);

    int ws_buf_idx;
    if (workspace_buffer_index >= 0 && workspace_buffer_index < FlexibleLdpcDecoder::NUM_WORKSPACE_BUFFERS) {
        ws_buf_idx = workspace_buffer_index;
    } else {
        ws_buf_idx = dec->current_workspace_buf;
        dec->current_workspace_buf = (dec->current_workspace_buf + 1) % FlexibleLdpcDecoder::NUM_WORKSPACE_BUFFERS;
    }

    size_t app_size = num_codewords * dec->N * dec->Z * sizeof(__half);
    size_t c2v_size = num_codewords * dec->M * dec->max_deg * dec->Z * sizeof(__half);
    size_t needed = app_size + c2v_size;

    if (needed > dec->workspace_size_half || num_codewords > dec->max_batch_size_half) {
        for (int i = 0; i < FlexibleLdpcDecoder::NUM_WORKSPACE_BUFFERS; i++) {
            if (dec->d_app_half[i]) cudaFree(dec->d_app_half[i]);
            if (dec->d_c2v_half[i]) cudaFree(dec->d_c2v_half[i]);
            cudaError_t err = cudaMalloc(&dec->d_app_half[i], app_size);
            if (err != cudaSuccess) return NR_LDPC_ERROR_ALLOC_FAILED;
            err = cudaMalloc(&dec->d_c2v_half[i], c2v_size);
            if (err != cudaSuccess) return NR_LDPC_ERROR_ALLOC_FAILED;
        }
        if (cudaStreamSynchronize(stream) != cudaSuccess) return NR_LDPC_ERROR_CUDA_FAILED;
        dec->workspace_size_half = needed;
        dec->max_batch_size_half = num_codewords;
    }

    if (num_codewords > dec->iterations_buffer_size) {
        if (dec->d_iterations) cudaFree(dec->d_iterations);
        if (dec->h_iterations) cudaFreeHost(dec->h_iterations);
        cudaMalloc(&dec->d_iterations, num_codewords * sizeof(int));
        cudaMallocHost(&dec->h_iterations, num_codewords * sizeof(int));
        dec->iterations_buffer_size = num_codewords;
    }

    if (dec->params.crc_early_termination && num_codewords > dec->crc_results_buffer_size) {
        if (dec->d_crc_results) cudaFree(dec->d_crc_results);
        if (dec->h_crc_results) cudaFreeHost(dec->h_crc_results);
        cudaMalloc(&dec->d_crc_results, num_codewords * sizeof(int));
        cudaMallocHost(&dec->h_crc_results, num_codewords * sizeof(int));
        dec->crc_results_buffer_size = num_codewords;
    }

    cudaStreamWaitEvent(stream, dec->workspace_complete[ws_buf_idx], 0);

    __half scale = __float2half(dec->effective_scale);
    __half offset = __float2half(dec->params.min_sum_offset);
    __half clamp = __float2half(dec->params.llr_clamp);
    int crc_bits = dec->config.num_info_bits;
    int crc_type = static_cast<int>(dec->params.crc_type);
    int filler_start = dec->config.num_info_bits;
    int filler_count = dec->config.num_filler_bits;
    bool offset_zero_nms = (dec->params.min_sum_offset == 0.0f);

    int cache_cols = 65;
    if (dec->app_cache_cols > 0) {
        cache_cols = dec->app_cache_cols;
    }
    if (cache_cols < dec->Kb) cache_cols = dec->Kb;
    if (cache_cols > dec->N) cache_cols = dec->N;

    size_t shmem_bytes = static_cast<size_t>(cache_cols) * dec->Z * sizeof(__half);
    const void* kernel_ptr = offset_zero_nms
                                 ? (const void*)ldpc_decode_boxplus_bg1_z384_direct_kernel<true>
                                 : (const void*)ldpc_decode_boxplus_bg1_z384_direct_kernel<false>;
    if (shmem_bytes >= 48 * 1024) {
        if ((int)shmem_bytes > dec->platform_cfg.max_shmem_per_block) {
            return NR_LDPC_ERROR_INVALID_CONFIG;
        }
        cudaError_t attr_err =
            cudaFuncSetAttribute(kernel_ptr, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)shmem_bytes);
        if (attr_err != cudaSuccess) {
            cudaGetLastError();
            return NR_LDPC_ERROR_CUDA_FAILED;
        }
    }

#define LAUNCH_DIRECT(OFFSET_ZERO_VAL) \
    ldpc_decode_boxplus_bg1_z384_direct_kernel<OFFSET_ZERO_VAL><<<num_codewords, dec->Z, shmem_bytes, stream>>>( \
        d_rm_half, dec->d_app_half[ws_buf_idx], dec->d_c2v_half[ws_buf_idx], d_output, dec->K_words, \
        dec->params.max_iterations, scale, offset, clamp, num_codewords, Q_m, N_cb, k0, d_rm_lengths, \
        d_rm_offsets, d_scramble_sequence, scramble_offset, dec->d_iterations, dec->params.crc_early_termination, \
        crc_bits, crc_type, dec->d_crc_results, filler_start, filler_count, cache_cols)

    if (offset_zero_nms) {
        LAUNCH_DIRECT(true);
    } else {
        LAUNCH_DIRECT(false);
    }
#undef LAUNCH_DIRECT

    cudaError_t launch_err = cudaGetLastError();
    if (launch_err != cudaSuccess) {
        return NR_LDPC_ERROR_CUDA_FAILED;
    }

    cudaEventRecord(dec->workspace_complete[ws_buf_idx], stream);

    if (dec->deferred_stats_enabled) {
        cudaMemcpyAsync(dec->h_iterations, dec->d_iterations, num_codewords * sizeof(int), cudaMemcpyDeviceToHost, stream);
        cudaEventRecord(dec->iteration_stats_event, stream);
        dec->iteration_stats_pending = true;
        dec->iteration_stats_count = num_codewords;
    } else if (!dec->params.skip_iteration_stats) {
        cudaMemcpyAsync(dec->h_iterations, dec->d_iterations, num_codewords * sizeof(int), cudaMemcpyDeviceToHost, stream);
        cudaStreamSynchronize(stream);

        int total_iterations = 0;
        for (int i = 0; i < num_codewords; i++) {
            total_iterations += dec->h_iterations[i];
        }
        dec->last_avg_iterations = (float)total_iterations / num_codewords;
    }

    return NR_LDPC_SUCCESS;
}

nr_ldpc_status_t ldpc_decoder_preallocate_workspace(ldpc_decoder_handle_t handle,
                                                      int max_batch_size) {
    FlexibleLdpcDecoder* dec = reinterpret_cast<FlexibleLdpcDecoder*>(handle);
    if (!dec || max_batch_size <= 0) {
        return NR_LDPC_ERROR_INVALID_CONFIG;
    }

    // Check if decoder is configured (N, Z, M must be set)
    if (dec->N == 0 || dec->Z == 0 || dec->M == 0) {
        return NR_LDPC_ERROR_INVALID_CONFIG;
    }

    // Compute required FP16 workspace sizes
    size_t app_size = max_batch_size * dec->N * dec->Z * sizeof(__half);
    size_t c2v_size = max_batch_size * dec->M * dec->max_deg * dec->Z * sizeof(__half);
    size_t needed = app_size + c2v_size;

    // Allocate/reallocate FP32 workspace (single buffer for non-E2E path)
    if (needed > dec->workspace_size || max_batch_size > dec->max_batch_size) {
        if (dec->d_app) cudaFree(dec->d_app);
        if (dec->d_c2v) cudaFree(dec->d_c2v);

        cudaError_t err = cudaMalloc(&dec->d_app, app_size);
        if (err != cudaSuccess) {
            dec->d_app = nullptr;
            dec->d_c2v = nullptr;
            dec->workspace_size = 0;
            dec->max_batch_size = 0;
            return NR_LDPC_ERROR_ALLOC_FAILED;
        }

        err = cudaMalloc(&dec->d_c2v, c2v_size);
        if (err != cudaSuccess) {
            cudaFree(dec->d_app);
            dec->d_app = nullptr;
            dec->d_c2v = nullptr;
            dec->workspace_size = 0;
            dec->max_batch_size = 0;
            return NR_LDPC_ERROR_ALLOC_FAILED;
        }

        dec->workspace_size = needed;
        dec->max_batch_size = max_batch_size;
    }

    // Allocate/reallocate FP16 triple-buffered workspace (for E2E GPU-resident path)
    if (needed > dec->workspace_size_half || max_batch_size > dec->max_batch_size_half) {
        for (int i = 0; i < FlexibleLdpcDecoder::NUM_WORKSPACE_BUFFERS; i++) {
            if (dec->d_app_half[i]) cudaFree(dec->d_app_half[i]);
            if (dec->d_c2v_half[i]) cudaFree(dec->d_c2v_half[i]);
            dec->d_app_half[i] = nullptr;
            dec->d_c2v_half[i] = nullptr;
        }

        for (int i = 0; i < FlexibleLdpcDecoder::NUM_WORKSPACE_BUFFERS; i++) {
            cudaError_t err = cudaMalloc(&dec->d_app_half[i], app_size);
            if (err != cudaSuccess) {
                for (int j = 0; j <= i; j++) {
                    if (dec->d_app_half[j]) cudaFree(dec->d_app_half[j]);
                    if (dec->d_c2v_half[j]) cudaFree(dec->d_c2v_half[j]);
                    dec->d_app_half[j] = nullptr;
                    dec->d_c2v_half[j] = nullptr;
                }
                dec->workspace_size_half = 0;
                dec->max_batch_size_half = 0;
                return NR_LDPC_ERROR_ALLOC_FAILED;
            }

            err = cudaMalloc(&dec->d_c2v_half[i], c2v_size);
            if (err != cudaSuccess) {
                cudaFree(dec->d_app_half[i]);
                for (int j = 0; j < i; j++) {
                    if (dec->d_app_half[j]) cudaFree(dec->d_app_half[j]);
                    if (dec->d_c2v_half[j]) cudaFree(dec->d_c2v_half[j]);
                    dec->d_app_half[j] = nullptr;
                    dec->d_c2v_half[j] = nullptr;
                }
                dec->workspace_size_half = 0;
                dec->max_batch_size_half = 0;
                return NR_LDPC_ERROR_ALLOC_FAILED;
            }
        }

        dec->workspace_size_half = needed;
        dec->max_batch_size_half = max_batch_size;
    }

    // Also allocate iteration tracking buffers
    if (max_batch_size > dec->iterations_buffer_size) {
        if (dec->d_iterations) cudaFree(dec->d_iterations);
        if (dec->h_iterations) cudaFreeHost(dec->h_iterations);

        cudaMalloc(&dec->d_iterations, max_batch_size * sizeof(int));
        cudaMallocHost(&dec->h_iterations, max_batch_size * sizeof(int));
        dec->iterations_buffer_size = max_batch_size;
    }

    return NR_LDPC_SUCCESS;
}

void ldpc_decoder_destroy(ldpc_decoder_handle_t handle) {
    FlexibleLdpcDecoder* dec = reinterpret_cast<FlexibleLdpcDecoder*>(handle);
    if (dec) {
        if (dec->d_scaled_shifts) cudaFree(dec->d_scaled_shifts);
        // Free FP32 single-buffer workspace
        if (dec->d_app) cudaFree(dec->d_app);
        if (dec->d_c2v) cudaFree(dec->d_c2v);
        // Free FP16 triple-buffered workspaces
        for (int i = 0; i < FlexibleLdpcDecoder::NUM_WORKSPACE_BUFFERS; i++) {
            if (dec->d_app_half[i]) cudaFree(dec->d_app_half[i]);
            if (dec->d_c2v_half[i]) cudaFree(dec->d_c2v_half[i]);
            // PHASE 0 FIX: Destroy workspace completion events
            if (dec->workspace_complete[i]) cudaEventDestroy(dec->workspace_complete[i]);
        }
        if (dec->d_iterations) cudaFree(dec->d_iterations);
        if (dec->h_iterations) cudaFreeHost(dec->h_iterations);
        if (dec->d_crc_results) cudaFree(dec->d_crc_results);
        if (dec->h_crc_results) cudaFreeHost(dec->h_crc_results);
        if (dec->iteration_stats_event) cudaEventDestroy(dec->iteration_stats_event);
        delete dec;
    }
}

int ldpc_decoder_get_input_llrs(ldpc_decoder_handle_t handle) {
    FlexibleLdpcDecoder* dec = reinterpret_cast<FlexibleLdpcDecoder*>(handle);
    return dec ? dec->N_llrs : 0;
}

int ldpc_decoder_get_output_bits(ldpc_decoder_handle_t handle) {
    FlexibleLdpcDecoder* dec = reinterpret_cast<FlexibleLdpcDecoder*>(handle);
    return dec ? dec->K_bits : 0;
}

int ldpc_decoder_get_output_words(ldpc_decoder_handle_t handle) {
    FlexibleLdpcDecoder* dec = reinterpret_cast<FlexibleLdpcDecoder*>(handle);
    return dec ? dec->K_words : 0;
}

float ldpc_decoder_get_avg_iterations(ldpc_decoder_handle_t handle) {
    FlexibleLdpcDecoder* dec = reinterpret_cast<FlexibleLdpcDecoder*>(handle);
    if (!dec) return 0.0f;

    // If deferred stats are pending, wait for D2H and compute average
    if (dec->iteration_stats_pending) {
        cudaEventSynchronize(dec->iteration_stats_event);

        int total = 0;
        for (int i = 0; i < dec->iteration_stats_count; i++) {
            total += dec->h_iterations[i];
        }
        dec->last_avg_iterations = (float)total / dec->iteration_stats_count;
        dec->iteration_stats_pending = false;
    }

    return dec->last_avg_iterations;
}

bool ldpc_decoder_iteration_stats_ready(ldpc_decoder_handle_t handle) {
    FlexibleLdpcDecoder* dec = reinterpret_cast<FlexibleLdpcDecoder*>(handle);
    if (!dec || !dec->iteration_stats_pending) return true;

    // Check if event has completed without blocking
    cudaError_t status = cudaEventQuery(dec->iteration_stats_event);
    return (status == cudaSuccess);
}

float ldpc_decoder_get_avg_iterations_async(ldpc_decoder_handle_t handle, bool* ready) {
    FlexibleLdpcDecoder* dec = reinterpret_cast<FlexibleLdpcDecoder*>(handle);
    if (!dec) {
        if (ready) *ready = true;
        return 0.0f;
    }

    // If no pending stats, return cached value immediately
    if (!dec->iteration_stats_pending) {
        if (ready) *ready = true;
        return dec->last_avg_iterations;
    }

    // Check if D2H has completed
    cudaError_t status = cudaEventQuery(dec->iteration_stats_event);
    if (status == cudaSuccess) {
        // D2H complete - compute average
        int total = 0;
        for (int i = 0; i < dec->iteration_stats_count; i++) {
            total += dec->h_iterations[i];
        }
        dec->last_avg_iterations = (float)total / dec->iteration_stats_count;
        dec->iteration_stats_pending = false;
        if (ready) *ready = true;
        return dec->last_avg_iterations;
    }

    // Not ready - return cached value
    if (ready) *ready = false;
    return dec->last_avg_iterations;
}

// ============================================================================
// CRC Results Access API
// ============================================================================

bool ldpc_decoder_has_crc_results(ldpc_decoder_handle_t handle) {
    FlexibleLdpcDecoder* dec = reinterpret_cast<FlexibleLdpcDecoder*>(handle);
    return dec != nullptr &&
           dec->d_crc_results != nullptr &&
           dec->params.crc_early_termination;
}

int* ldpc_decoder_get_crc_results_ptr(ldpc_decoder_handle_t handle) {
    FlexibleLdpcDecoder* dec = reinterpret_cast<FlexibleLdpcDecoder*>(handle);
    if (!dec || !dec->d_crc_results) {
        return nullptr;
    }
    return dec->d_crc_results;
}

const int* ldpc_decoder_get_crc_results_host(ldpc_decoder_handle_t handle, int num_cbs, cudaStream_t stream) {
    FlexibleLdpcDecoder* dec = reinterpret_cast<FlexibleLdpcDecoder*>(handle);
    if (!dec || !dec->d_crc_results || !dec->h_crc_results) {
        return nullptr;
    }

    // Copy results to host
    cudaMemcpyAsync(dec->h_crc_results,
                    dec->d_crc_results,
                    num_cbs * sizeof(int),
                    cudaMemcpyDeviceToHost,
                    stream);
    cudaStreamSynchronize(stream);

    return dec->h_crc_results;
}

// ============================================================================
// Bit Reformat Kernel: Reverse bits within each byte of LDPC decoder output
// Converts LSB-first-per-byte (GPU kernel output) to MSB-first-per-byte (3GPP)
// ============================================================================

__global__ void reformat_bits_kernel(uint32_t* data, int words_per_cb, int nof_cbs) {
    int cb = blockIdx.x;
    int word = threadIdx.x;
    if (cb >= nof_cbs || word >= words_per_cb) return;
    uint32_t v = data[cb * words_per_cb + word];
    // Reverse bits within each byte (4 bytes in parallel)
    v = ((v & 0xF0F0F0F0) >> 4) | ((v & 0x0F0F0F0F) << 4);
    v = ((v & 0xCCCCCCCC) >> 2) | ((v & 0x33333333) << 2);
    v = ((v & 0xAAAAAAAA) >> 1) | ((v & 0x55555555) << 1);
    data[cb * words_per_cb + word] = v;
}

nr_ldpc_status_t ldpc_decoder_reformat_output_bits(
    ldpc_decoder_handle_t handle,
    uint32_t* d_output,
    int nof_cbs,
    cudaStream_t stream)
{
    FlexibleLdpcDecoder* dec = reinterpret_cast<FlexibleLdpcDecoder*>(handle);
    if (!dec || !d_output || nof_cbs <= 0) return NR_LDPC_ERROR_INVALID_CONFIG;

    int words_per_cb = dec->K_words;
    if (words_per_cb <= 0) return NR_LDPC_ERROR_INVALID_CONFIG;

    // Launch with one block per CB, threads per block = words_per_cb (max 264 for BG1 Z=384)
    int threads = (words_per_cb + 31) / 32 * 32;  // Round up to warp multiple
    if (threads > 1024) threads = 1024;
    reformat_bits_kernel<<<nof_cbs, threads, 0, stream>>>(d_output, words_per_cb, nof_cbs);

    return NR_LDPC_SUCCESS;
}

}  // extern "C"
